// @id           explorer-hide-focus-border
// @name         File Explorer Focus Border Remover
// @name:vi-VN   Xóa viền focus trong File Explorer
// @description  Removes the white focus border around selected items in File Explorer while preserving the normal selection highlight.
// @description:vi-VN Xóa viền focus màu trắng quanh mục đang chọn trong File Explorer nhưng vẫn giữ nền chọn bình thường.
// @version      1.0.0
// @author       Hùng
// @github       https://github.com/NoMorePlz
// @include      explorer.exe
// @architecture x86-64
// @compilerOptions -luxtheme
// @license      MIT
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# File Explorer Focus Border Remover

Removes the white rectangular focus border around selected files, folders and
drives in Windows 11 File Explorer while keeping the normal selection and hover
highlights intact.

This is different from [No Focus Rectangle](https://github.com/ramensoftware/windhawk-mods/blob/main/mods/no-focus-rectangle.wh.cpp):
that mod suppresses the classic dotted `DrawFocusRect`, while this mod targets
the themed focus border used by the modern File Explorer item view.

## Before / After

![Before and after](https://raw.githubusercontent.com/NoMorePlz/windhawk-mods/cbf6be5c3a729079aff4d7cd44011f5189ed771f/assets/explorer-hide-focus-border-before-after-v2.png)

## Notes

- Designed for Windows 11 File Explorer.
- The effect is applied at draw time, so it takes effect without restarting
  Explorer when the mod is enabled.
- The implementation relies on an undocumented File Explorer theme detail:
  `ItemsView`, part 3, state 1 is used for the focus border on current Windows
  builds. A future Windows update may change this.
- On the tested Windows 11 build, `GetThemeClass` resolved the File Explorer
  item view to the full class name `ItemsView` in both the tested light/dark
  scenarios, so the implementation matches that class name exactly.
- The mod is scoped to `explorer.exe`; common Open/Save dialogs hosted by other
  applications are not affected.
- Older Windows versions are untested.
- The intended targets include regular File Explorer items and
  **This PC > Devices and drives**.
- The same focus-border effect can also be changed by the **Rounded Selection**
  option in Win32 UI Modernizer; using both for this effect is redundant.
*/
// ==/WindhawkModReadme==

#include <windows.h>
#include <uxtheme.h>
#include <windhawk_utils.h>

#include <wchar.h>

static decltype(&DrawThemeBackground) DrawThemeBackground_Original = nullptr;
static decltype(&DrawThemeBackgroundEx) DrawThemeBackgroundEx_Original = nullptr;

static bool IsItemsViewTheme(HTHEME hTheme) {
    using GetThemeClass_t = HRESULT(WINAPI*)(HTHEME, LPWSTR, int);

    static auto getThemeClass = reinterpret_cast<GetThemeClass_t>(
        GetProcAddress(GetModuleHandleW(L"uxtheme.dll"), MAKEINTRESOURCEA(74)));

    if (!getThemeClass || !hTheme) {
        if (!getThemeClass) {
            Wh_Log(L"GetThemeClass (uxtheme ordinal 74) is unavailable");
        }
        return false;
    }

    WCHAR className[256] = {};
    if (FAILED(getThemeClass(hTheme, className, ARRAYSIZE(className)))) {
        return false;
    }

    // Verified on Windows 11 during review: GetThemeClass returned the full
    // resolved class name "ItemsView" for the File Explorer item view.
    return _wcsicmp(className, L"ItemsView") == 0;
}

static bool ShouldSuppressFocusBorder(HTHEME hTheme,
                                      int partId,
                                      int stateId) {
    // Current File Explorer DirectUI ItemsView behavior:
    //   part 3, state 1 = focus border
    // Other states include hover/selection overlays and must remain visible.
    return partId == 3 && stateId == 1 && IsItemsViewTheme(hTheme);
}

HRESULT WINAPI DrawThemeBackground_Hook(HTHEME hTheme,
                                         HDC hdc,
                                         int iPartId,
                                         int iStateId,
                                         LPCRECT pRect,
                                         LPCRECT pClipRect) {
    if (ShouldSuppressFocusBorder(hTheme, iPartId, iStateId)) {
        return S_OK;
    }

    return DrawThemeBackground_Original(hTheme, hdc, iPartId, iStateId,
                                        pRect, pClipRect);
}

HRESULT WINAPI DrawThemeBackgroundEx_Hook(HTHEME hTheme,
                                           HDC hdc,
                                           int iPartId,
                                           int iStateId,
                                           LPCRECT pRect,
                                           const DTBGOPTS* pOptions) {
    if (ShouldSuppressFocusBorder(hTheme, iPartId, iStateId)) {
        return S_OK;
    }

    return DrawThemeBackgroundEx_Original(hTheme, hdc, iPartId, iStateId,
                                          pRect, pOptions);
}

BOOL Wh_ModInit() {
    Wh_Log(L">");

    if (!WindhawkUtils::SetFunctionHook(DrawThemeBackground,
                                        DrawThemeBackground_Hook,
                                        &DrawThemeBackground_Original) ||
        !WindhawkUtils::SetFunctionHook(DrawThemeBackgroundEx,
                                        DrawThemeBackgroundEx_Hook,
                                        &DrawThemeBackgroundEx_Original)) {
        Wh_Log(L"Failed to hook uxtheme drawing functions");
        return FALSE;
    }

    return TRUE;
}

// ==WindhawkMod==
// @id              explorer-navigation-pane-tweaks
// @name            Explorer Navigation Tree Offset
// @description     Adjusts the Explorer navigation tree offset and optional tree view visual styles
// @version         1.1
// @author          Languster
// @github          https://github.com/Languster
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -lcomctl32 -luxtheme
// @license         MIT
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Explorer Navigation Tree Offset

Adjusts the horizontal position and visual tree style of the navigation pane in Windows Explorer.

> Recommended: use this mod together with [Explorer TreeItem Tweaker](https://windhawk.net/mods/explorer-treeitem-tweaker) and [Explorer TreeLine Killer](https://windhawk.net/mods/explorer-treeline-killer) for the best navigation tree appearance.

## Before / After

### Default Explorer

![Before](https://raw.githubusercontent.com/Languster/ExplorerNavHook/main/screenshots/before.jpg)

### With Explorer Navigation Tree Offset

![After](https://raw.githubusercontent.com/Languster/ExplorerNavHook/main/screenshots/after.jpg)

## Features

- shifts the whole Explorer navigation tree left or right
- keeps parent and child tree levels moving together
- can remove all expand/collapse glyphs
- can remove only the first/root expand glyph while keeping child glyphs
- can remove connector lines
- item background position compensation

## Settings

- **Navigation tree left shift**: moves the whole navigation tree. `0` keeps Explorer's original position. Positive values move the tree left.
- **Remove all expand/collapse glyphs**: removes the tree expand/collapse glyphs in the navigation pane.
- **Remove first expand glyph**: removes only the first/root expand/collapse glyph while keeping child glyphs. Works when **Remove all expand/collapse glyphs** is disabled.
- **Remove connector lines**: removes the tree connector lines in the navigation pane.
- **Compensate item background position**: when the tree is shifted, the hover/selected item background shifts with it. This option moves the background back into place.

## Notes

This version intentionally doesn't use `TVM_SETINDENT` as the main shift mechanism. `TVM_SETINDENT` changes the distance between tree hierarchy levels, which is why the original behavior depended on whether root/tree glyphs were visible.

The live-layout correction is done after Explorer positions the tree, without hooking `SetWindowPos`, `MoveWindow`, or `DeferWindowPos`. This keeps Explorer's own scrollbar calculation intact.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- TargetIndent: 25
  $name: Navigation tree left shift
  $description: Moves the whole Explorer navigation tree. 0 keeps Explorer's original position. Positive values move the tree left.

- RemoveHasButtons: true
  $name: Remove all expand/collapse glyphs
  $description: Removes the tree expand/collapse glyphs in the navigation pane

- RemoveLinesAtRoot: true
  $name: Remove first expand glyph
  $description: Removes the first/root expand/collapse glyph while keeping child glyphs. Works when "Remove all expand/collapse glyphs" is disabled.

- RemoveHasLines: true
  $name: Remove connector lines
  $description: Removes the tree connector lines in the navigation pane

- CompensateItemBackgroundPosition: true
  $name: Compensate item background position
  $description: When the tree is shifted, the hover/selected item background shifts with it. This option moves the background back into place.
*/
// ==/WindhawkModSettings==

#include <windows.h>
#include <commctrl.h>
