    HTHEME, HDC, int, int, LPCRECT, const DTBGOPTS*) = nullptr;

static thread_local HWND g_CurrentPaintingTree = nullptr;
static thread_local int g_CurrentPaintingTreeDepth = 0;

static int AbsInt(int value)
{
    return value < 0 ? -value : value;
}

static bool AlmostEqualInt(int a, int b)
{
    return AbsInt(a - b) <= 1;
}

static bool RectAlmostEquals(const RECT& a, const RECT& b)
{
    return AlmostEqualInt(a.left, b.left) &&
           AlmostEqualInt(a.top, b.top) &&
           AlmostEqualInt(a.right, b.right) &&
           AlmostEqualInt(a.bottom, b.bottom);
}

static int RectWidth(const RECT& rc)
{
    return rc.right - rc.left;
}

static int RectHeight(const RECT& rc)
{
    return rc.bottom - rc.top;
}

static bool GetWindowRectInParent(HWND hwnd, RECT* rc)
{
    if (!IsWindow(hwnd) || !rc)
        return false;

    HWND hParent = GetParent(hwnd);
    if (!hParent)
        return false;

    RECT windowRect{};
    if (!GetWindowRect(hwnd, &windowRect))
        return false;

    POINT points[2] = {
        {windowRect.left, windowRect.top},
        {windowRect.right, windowRect.bottom},
    };

    MapWindowPoints(HWND_DESKTOP, hParent, points, 2);

    rc->left = points[0].x;
    rc->top = points[0].y;
    rc->right = points[1].x;
    rc->bottom = points[1].y;
    return true;
}

static void LoadSettings()
{
    // Keep the original key for compatibility with existing installs.
    // The value now shifts the whole tree control instead of changing TVM_SETINDENT.
    g_TargetIndent = Wh_GetIntSetting(L"TargetIndent");
    g_RemoveHasButtons = Wh_GetIntSetting(L"RemoveHasButtons");
    g_RemoveHasLines = Wh_GetIntSetting(L"RemoveHasLines");
    g_RemoveLinesAtRoot = Wh_GetIntSetting(L"RemoveLinesAtRoot");
    g_CompensateItemBackgroundPosition = Wh_GetIntSetting(L"CompensateItemBackgroundPosition");

    Wh_Log(L"Settings loaded, treeLeftShift=%d, compensateItemBackground=%d", g_TargetIndent, g_CompensateItemBackgroundPosition);
}

static bool IsExplorerTopWindow(HWND hwnd)
{
    if (!IsWindow(hwnd))
        return false;

    wchar_t cls[128] = {};
    GetClassNameW(hwnd, cls, ARRAYSIZE(cls));

    return lstrcmpiW(cls, L"CabinetWClass") == 0 ||
           lstrcmpiW(cls, L"ExploreWClass") == 0;
}

static HWND FindExplorerTopWindowFromChild(HWND hwnd)
{
    HWND root = GetAncestor(hwnd, GA_ROOT);
    if (root && IsExplorerTopWindow(root))
        return root;

    return nullptr;
}

static bool IsTreeViewClassName(LPCWSTR className)
{
    if (!className || IS_INTRESOURCE(className))
        return false;

    return lstrcmpiW(className, WC_TREEVIEWW) == 0 ||
           lstrcmpiW(className, L"SysTreeView32") == 0;
}

static bool IsTreeViewClass(HWND hwnd)
{
    if (!IsWindow(hwnd))
        return false;

    wchar_t cls[128] = {};
    GetClassNameW(hwnd, cls, ARRAYSIZE(cls));

    return IsTreeViewClassName(cls);
}

static bool IsLikelyNavTree(HWND hwnd)
{
    if (!IsTreeViewClass(hwnd))
        return false;

    if (!FindExplorerTopWindowFromChild(hwnd))
        return false;

    RECT rc{};
    if (!GetWindowRect(hwnd, &rc))
        return false;

    int w = rc.right - rc.left;
    int h = rc.bottom - rc.top;

    if (w < 80 || h < 80)
        return false;

    return true;
}

static ExplorerState* FindExplorerState_NoLock(HWND hExplorer)
{
    for (auto& state : g_ExplorerStates)
    {
        if (state.hExplorer == hExplorer)
            return &state;
    }

    return nullptr;
}

static ExplorerState* GetOrCreateExplorerState_NoLock(HWND hExplorer)
{
    ExplorerState* existing = FindExplorerState_NoLock(hExplorer);
    if (existing)
        return existing;

    ExplorerState state{};
    state.hExplorer = hExplorer;
    state.hTree = nullptr;
    state.repatchPending = false;
    g_ExplorerStates.push_back(state);
    return &g_ExplorerStates.back();
}

static TreeState* FindTreeState_NoLock(HWND hTree)
{
    for (auto& state : g_TreeStates)
    {
        if (state.hTree == hTree)
            return &state;
    }

    return nullptr;
}

static TreeState* GetOrCreateTreeState_NoLock(HWND hExplorer, HWND hTree)
{
    TreeState* existing = FindTreeState_NoLock(hTree);
    if (existing)
    {
        existing->hExplorer = hExplorer;
        return existing;
    }

    TreeState state{};
    state.hExplorer = hExplorer;
    state.hTree = hTree;
    state.capturedStyle = false;
    state.originalStyle = 0;
    state.capturedLayout = false;
    state.baseRect = {};
    state.appliedRect = {};
    state.appliedShift = 0;
    g_TreeStates.push_back(state);
    return &g_TreeStates.back();
}

static void CleanupDeadStates()
{
    if (!g_StateLockInitialized)
        return;

    EnterCriticalSection(&g_StateLock);

    for (size_t i = 0; i < g_ExplorerStates.size();)
    {
        if (!IsWindow(g_ExplorerStates[i].hExplorer))
            g_ExplorerStates.erase(g_ExplorerStates.begin() + i);
        else
            ++i;
    }

    for (size_t i = 0; i < g_TreeStates.size();)
    {
        if (!IsWindow(g_TreeStates[i].hTree))
            g_TreeStates.erase(g_TreeStates.begin() + i);
        else
            ++i;
    }

    LeaveCriticalSection(&g_StateLock);
}

class ScopedInternalWindowPos
{
public:
    ScopedInternalWindowPos()
    {
        InterlockedIncrement(&g_InternalWindowPosDepth);
    }

    ~ScopedInternalWindowPos()
    {
        InterlockedDecrement(&g_InternalWindowPosDepth);
    }
};


class ScopedTreePaintContext
{
public:
    explicit ScopedTreePaintContext(HWND hTree)
    {
        m_previousTree = g_CurrentPaintingTree;
        g_CurrentPaintingTree = hTree;
        ++g_CurrentPaintingTreeDepth;
    }

    ~ScopedTreePaintContext()
    {
        if (g_CurrentPaintingTreeDepth > 0)
            --g_CurrentPaintingTreeDepth;

        g_CurrentPaintingTree = m_previousTree;

        if (g_CurrentPaintingTreeDepth <= 0)
        {
            g_CurrentPaintingTreeDepth = 0;
            g_CurrentPaintingTree = nullptr;
        }
    }

private:
    HWND m_previousTree = nullptr;
};

#ifndef TVP_TREEITEM
#define TVP_TREEITEM 1
#endif

static bool ShouldCompensateTreeItemBackground(int partId, LPCRECT pRect)
{
    if (!g_CompensateItemBackgroundPosition || g_Uninitializing || g_TargetIndent == 0)
        return false;

    if (g_CurrentPaintingTreeDepth <= 0 || !IsWindow(g_CurrentPaintingTree))
        return false;

    if (partId != TVP_TREEITEM)
        return false;

    if (!pRect)
        return false;

    int rectWidth = RectWidth(*pRect);
    int rectHeight = RectHeight(*pRect);
    if (rectWidth <= 0 || rectHeight <= 0)
        return false;

    if (!IsLikelyNavTree(g_CurrentPaintingTree))
        return false;

    if (rectHeight < 8 || rectHeight > 80)
        return false;

    // DrawThemeBackground is also used by the themed scrollbar hosted by the
    // TreeView. Scrollbar arrow buttons can use the same numeric part id as
    // TVP_TREEITEM. The previous protection filtered out all narrow rectangles,
    // but short tree items such as "Videos" also have narrow background rects.
    // Exclude only rectangles that are actually inside the vertical scrollbar
    // strip at the right edge of the TreeView.
    RECT clientRect{};
    if (GetClientRect(g_CurrentPaintingTree, &clientRect))
    {
        int clientWidth = RectWidth(clientRect);
        int clientHeight = RectHeight(clientRect);
        int scrollbarWidth = GetSystemMetrics(SM_CXVSCROLL);
        int scrollbarHeight = GetSystemMetrics(SM_CYVSCROLL);

        int scrollbarLeft = clientWidth - scrollbarWidth - 4;
        if (scrollbarLeft < 0)
            scrollbarLeft = 0;

        bool inVerticalScrollbarStrip =
            pRect->left >= scrollbarLeft &&
            pRect->right <= clientWidth + 4;

        bool looksLikeScrollbarButton =
            rectWidth <= scrollbarWidth + 8 &&
            rectHeight <= scrollbarHeight + 8 &&
            (pRect->top <= 4 || pRect->bottom >= clientHeight - 4);

        if (inVerticalScrollbarStrip && looksLikeScrollbarButton)
            return false;
    }

    int maxExpectedLeft = g_TargetIndent + 16;
    if (maxExpectedLeft < 32)
        maxExpectedLeft = 32;

    if (pRect->left > maxExpectedLeft)
        return false;

    return true;
}

static HRESULT WINAPI DrawThemeBackground_Hook(
    HTHEME hTheme,
    HDC hdc,
    int iPartId,
    int iStateId,
    LPCRECT pRect,
    LPCRECT pClipRect)
{
    if (ShouldCompensateTreeItemBackground(iPartId, pRect))
    {
        RECT adjustedRect = *pRect;

        // The shifted tree is wider by g_TargetIndent pixels: its left edge moves
        // left, while the right edge stays aligned with Explorer's layout. Moving
        // the whole background rect to the right fixes the left edge, but pushes
        // the right edge too far. Only trim the left side instead.
        adjustedRect.left += g_TargetIndent;
        if (adjustedRect.left > adjustedRect.right)
            adjustedRect.left = adjustedRect.right;

        RECT adjustedClipRect{};
        LPCRECT finalClipRect = pClipRect;
        if (pClipRect)
        {
            adjustedClipRect = *pClipRect;
            adjustedClipRect.left += g_TargetIndent;
            if (adjustedClipRect.left > adjustedClipRect.right)
                adjustedClipRect.left = adjustedClipRect.right;
            finalClipRect = &adjustedClipRect;
        }

        return DrawThemeBackground_Original(
            hTheme,
            hdc,
            iPartId,
            iStateId,
            &adjustedRect,
            finalClipRect);
    }

    return DrawThemeBackground_Original(hTheme, hdc, iPartId, iStateId, pRect, pClipRect);
}

static HRESULT WINAPI DrawThemeBackgroundEx_Hook(
    HTHEME hTheme,
    HDC hdc,
    int iPartId,
    int iStateId,
    LPCRECT pRect,
    const DTBGOPTS* pOptions)
{
    if (ShouldCompensateTreeItemBackground(iPartId, pRect))
    {
        RECT adjustedRect = *pRect;

        // Keep the right edge unchanged and compensate only the left edge.
        // This prevents the background from stretching toward the content area.
        adjustedRect.left += g_TargetIndent;
        if (adjustedRect.left > adjustedRect.right)
            adjustedRect.left = adjustedRect.right;

        DTBGOPTS adjustedOptions{};
        const DTBGOPTS* finalOptions = pOptions;
        if (pOptions)
        {
            adjustedOptions = *pOptions;
            if (adjustedOptions.dwFlags & DTBG_CLIPRECT)
            {
                adjustedOptions.rcClip.left += g_TargetIndent;
                if (adjustedOptions.rcClip.left > adjustedOptions.rcClip.right)
                    adjustedOptions.rcClip.left = adjustedOptions.rcClip.right;
            }
            finalOptions = &adjustedOptions;
        }

        return DrawThemeBackgroundEx_Original(
            hTheme,
            hdc,
            iPartId,
            iStateId,
            &adjustedRect,
            finalOptions);
    }

    return DrawThemeBackgroundEx_Original(hTheme, hdc, iPartId, iStateId, pRect, pOptions);
}


static void AdjustTreeWindowPosChanging(HWND hTree, WINDOWPOS* wp)
{
    if (!wp || g_Uninitializing || g_InternalWindowPosDepth > 0)
        return;

    if ((wp->flags & SWP_NOMOVE) && (wp->flags & SWP_NOSIZE))
        return;

    HWND hExplorer = FindExplorerTopWindowFromChild(hTree);
    if (!hExplorer)
        return;

    RECT currentRect{};
    if (!GetWindowRectInParent(hTree, &currentRect))
        return;

    int currentWidth = RectWidth(currentRect);
    int currentHeight = RectHeight(currentRect);

    if (currentWidth < 50 || currentHeight < 50)
        return;

    int shift = g_TargetIndent;
    if (shift == 0)
        return;

    int proposedX = (wp->flags & SWP_NOMOVE) ? currentRect.left : wp->x;
    int proposedY = (wp->flags & SWP_NOMOVE) ? currentRect.top : wp->y;
    int proposedCx = (wp->flags & SWP_NOSIZE) ? currentWidth : wp->cx;
    int proposedCy = (wp->flags & SWP_NOSIZE) ? currentHeight : wp->cy;

    if (proposedCx < 50 || proposedCy < 50)
        return;

    bool alreadyShifted = false;

    if (g_StateLockInitialized)
    {
        EnterCriticalSection(&g_StateLock);

        TreeState* state = FindTreeState_NoLock(hTree);
        if (state && state->capturedLayout)
        {
            // Important: only the coordinates proposed by Explorer matter here.
            // In reset-v4 this also checked currentRect.left. During live resize the
            // current rect is often still our shifted rect, while Explorer proposes
            // the unshifted/default x. Treating that as already shifted caused the
            // tree to temporarily jump back to the default position.
            alreadyShifted =
                AlmostEqualInt(proposedX, state->appliedRect.left) ||
                AlmostEqualInt(proposedX, state->baseRect.left - state->appliedShift);
        }

        LeaveCriticalSection(&g_StateLock);
    }

    RECT baseRect{};
    RECT targetRect{};

    if (alreadyShifted)
    {
        targetRect.left = proposedX;
        targetRect.top = proposedY;
        targetRect.right = proposedX + proposedCx;
        targetRect.bottom = proposedY + proposedCy;

        baseRect = targetRect;
        baseRect.left += shift;
    }
    else
    {
        baseRect.left = proposedX;
        baseRect.top = proposedY;
        baseRect.right = proposedX + proposedCx;
        baseRect.bottom = proposedY + proposedCy;

        targetRect = baseRect;
        targetRect.left = baseRect.left - shift;
    }

    int targetWidth = RectWidth(targetRect);
    int targetHeight = RectHeight(targetRect);

    if (targetWidth < 50)
        targetWidth = 50;

    if (targetHeight < 50)
        targetHeight = 50;

    targetRect.right = targetRect.left + targetWidth;
    targetRect.bottom = targetRect.top + targetHeight;

    if (g_StateLockInitialized)
    {
        EnterCriticalSection(&g_StateLock);

        TreeState* state = GetOrCreateTreeState_NoLock(hExplorer, hTree);
        if (state)
        {
            state->capturedLayout = true;
            state->baseRect = baseRect;
            state->appliedRect = targetRect;
            state->appliedShift = shift;
        }

        LeaveCriticalSection(&g_StateLock);
    }

    wp->x = targetRect.left;
    wp->y = targetRect.top;
    wp->cx = targetWidth;
    wp->cy = targetHeight;
    wp->flags &= ~(SWP_NOMOVE | SWP_NOSIZE);
}

static LRESULT CALLBACK TreeSubclassProc(
    HWND hwnd,
    UINT msg,
    WPARAM wParam,
    LPARAM lParam,
    DWORD_PTR)
{
    if (msg == WM_NCDESTROY)
    {
        LRESULT result = DefSubclassProc(hwnd, msg, wParam, lParam);
        WindhawkUtils::RemoveWindowSubclassFromAnyThread(hwnd, TreeSubclassProc);
        return result;
    }

    if (msg == WM_WINDOWPOSCHANGING && !g_Uninitializing && g_InternalWindowPosDepth <= 0)
    {
        AdjustTreeWindowPosChanging(hwnd, (WINDOWPOS*)lParam);
    }

    LRESULT result = 0;
    if (msg == WM_PAINT || msg == WM_PRINTCLIENT)
    {
        ScopedTreePaintContext paintContext(hwnd);
        result = DefSubclassProc(hwnd, msg, wParam, lParam);
    }
    else
    {
        result = DefSubclassProc(hwnd, msg, wParam, lParam);
    }

    if (g_Uninitializing || g_InternalWindowPosDepth > 0)
        return result;

    if (msg == WM_WINDOWPOSCHANGED ||
        msg == WM_SHOWWINDOW)
    {
        HWND hExplorer = FindExplorerTopWindowFromChild(hwnd);
        if (hExplorer)
            PatchTree(hExplorer, hwnd);
    }

    return result;
}


static LRESULT CALLBACK ExplorerSubclassProc(
    HWND hwnd,
    UINT msg,
    WPARAM wParam,
    LPARAM lParam,
    DWORD_PTR)
{
    LRESULT result = DefSubclassProc(hwnd, msg, wParam, lParam);

    if (msg == WM_NCDESTROY)
    {
        WindhawkUtils::RemoveWindowSubclassFromAnyThread(hwnd, ExplorerSubclassProc);
        return result;
    }

    if (g_Uninitializing || g_InternalWindowPosDepth > 0)
        return result;

    if (msg == WM_WINDOWPOSCHANGED ||
        msg == WM_SIZE ||
        msg == WM_EXITSIZEMOVE)
    {
        PatchExplorerWindow(hwnd);
    }

    return result;
}

static void TrySubclassTree(HWND hTree)
{
    if (!IsWindow(hTree))
        return;

    WindhawkUtils::SetWindowSubclassFromAnyThread(hTree, TreeSubclassProc, 0);
}

static void TrySubclassExplorer(HWND hExplorer)
{
    if (!IsWindow(hExplorer))
        return;

    WindhawkUtils::SetWindowSubclassFromAnyThread(hExplorer, ExplorerSubclassProc, 0);
}

static void CaptureAndApplyTreeStyle(HWND hExplorer, HWND hTree)
{
    if (!IsWindow(hTree) || !g_StateLockInitialized)
        return;

    LONG_PTR style = GetWindowLongPtrW(hTree, GWL_STYLE);
    LONG_PTR originalStyle = style;

    EnterCriticalSection(&g_StateLock);
    TreeState* state = GetOrCreateTreeState_NoLock(hExplorer, hTree);
    if (state)
    {
        if (!state->capturedStyle)
        {
            state->capturedStyle = true;
            state->originalStyle = style;
        }

        originalStyle = state->originalStyle;
    }
    LeaveCriticalSection(&g_StateLock);

    LONG_PTR newStyle = style;

    if (g_RemoveHasButtons)
        newStyle &= ~TVS_HASBUTTONS;
    else
        newStyle = (newStyle & ~TVS_HASBUTTONS) | (originalStyle & TVS_HASBUTTONS);

    if (g_RemoveHasLines)
        newStyle &= ~TVS_HASLINES;
    else
        newStyle = (newStyle & ~TVS_HASLINES) | (originalStyle & TVS_HASLINES);

    if (g_RemoveLinesAtRoot)
        newStyle &= ~TVS_LINESATROOT;
    else
        newStyle = (newStyle & ~TVS_LINESATROOT) | (originalStyle & TVS_LINESATROOT);

    if (newStyle != style)
    {
        SetWindowLongPtrW(hTree, GWL_STYLE, newStyle);

        ScopedInternalWindowPos internalMove;

        SetWindowPos(
            hTree,
            nullptr,
            0, 0, 0, 0,
            SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE | SWP_FRAMECHANGED);
    }
}

static void ApplyTreeLeftShift(HWND hExplorer, HWND hTree)
{
    if (!IsWindow(hExplorer) || !IsWindow(hTree) || !g_StateLockInitialized)
        return;

    RECT currentRect{};
    if (!GetWindowRectInParent(hTree, &currentRect))
        return;

    if (RectWidth(currentRect) < 50 || RectHeight(currentRect) < 50)
        return;

    int shift = g_TargetIndent;
    RECT baseRect = currentRect;
    bool hadCapturedLayout = false;
    int previousShift = 0;

    EnterCriticalSection(&g_StateLock);

    TreeState* state = GetOrCreateTreeState_NoLock(hExplorer, hTree);
    if (state)
    {
        hadCapturedLayout = state->capturedLayout;
        previousShift = state->appliedShift;

        if (state->capturedLayout && previousShift != 0)
        {
            bool currentLooksShifted =
                AlmostEqualInt(currentRect.left, state->appliedRect.left) ||
                AlmostEqualInt(currentRect.left, state->baseRect.left - previousShift);

            if (currentLooksShifted)
            {
                // The tree is already in our shifted coordinate space, even if Explorer
                // changed only height/width during resize. Convert it back to base space
                // before calculating the new target. This prevents cumulative shifting.
                baseRect.left = currentRect.left + previousShift;
                baseRect.top = currentRect.top;
                baseRect.right = currentRect.right;
                baseRect.bottom = currentRect.bottom;
            }
        }
    }

    LeaveCriticalSection(&g_StateLock);

    if (!hadCapturedLayout && shift > 0 && currentRect.left < 0)
    {
        // Defensive recovery after reloading from an older shifted build.
        baseRect.left = currentRect.left + shift;
        baseRect.top = currentRect.top;
        baseRect.right = currentRect.right;
        baseRect.bottom = currentRect.bottom;
    }
    else if (!hadCapturedLayout || RectAlmostEquals(baseRect, currentRect))
    {
        // Explorer's latest unshifted layout becomes the base.
        baseRect = currentRect;
    }

    RECT targetRect = baseRect;
    targetRect.left = baseRect.left - shift;

    int targetWidth = targetRect.right - targetRect.left;
    int targetHeight = targetRect.bottom - targetRect.top;

    if (targetWidth < 50)
        targetWidth = 50;

    if (targetHeight < 50)
        targetHeight = 50;

    targetRect.right = targetRect.left + targetWidth;
    targetRect.bottom = targetRect.top + targetHeight;

    EnterCriticalSection(&g_StateLock);
    state = GetOrCreateTreeState_NoLock(hExplorer, hTree);
    if (state)
    {
        state->capturedLayout = true;
        state->baseRect = baseRect;
        state->appliedRect = targetRect;
        state->appliedShift = shift;
    }
    LeaveCriticalSection(&g_StateLock);

    if (RectAlmostEquals(currentRect, targetRect))
        return;

    ScopedInternalWindowPos internalMove;

    SetWindowPos(
        hTree,
        nullptr,
        targetRect.left,
        targetRect.top,
        targetWidth,
        targetHeight,
        SWP_NOZORDER | SWP_NOACTIVATE);
}

static void PatchTree(HWND hExplorer, HWND hTree)
{
    if (!IsWindow(hExplorer) || !IsWindow(hTree))
        return;

    CaptureAndApplyTreeStyle(hExplorer, hTree);
    ApplyTreeLeftShift(hExplorer, hTree);

}

static BOOL CALLBACK FindTreeEnumProc(HWND hwnd, LPARAM lParam)
{
    HWND* pFound = (HWND*)lParam;
    if (*pFound)
        return FALSE;

    if (IsLikelyNavTree(hwnd))
    {
        *pFound = hwnd;
        return FALSE;
    }

    return TRUE;
}

static HWND FindNavTreeInExplorer(HWND hExplorer)
{
    if (!IsExplorerTopWindow(hExplorer))
        return nullptr;

    HWND found = nullptr;
    EnumChildWindows(hExplorer, FindTreeEnumProc, (LPARAM)&found);
    return found;
}

static void PatchExplorerWindow(HWND hExplorer)
{
    if (!IsExplorerTopWindow(hExplorer))
        return;

    HWND hTree = FindNavTreeInExplorer(hExplorer);
    if (!hTree)
        return;

    TrySubclassExplorer(hExplorer);
    TrySubclassTree(hTree);

    if (g_StateLockInitialized)
    {
        EnterCriticalSection(&g_StateLock);
        ExplorerState* state = GetOrCreateExplorerState_NoLock(hExplorer);
        if (state)
            state->hTree = hTree;
        LeaveCriticalSection(&g_StateLock);
    }

    PatchTree(hExplorer, hTree);
}


static void FinishRepatchThread()
{
    LONG remaining = InterlockedDecrement(&g_ActiveRepatchThreads);
    if (remaining <= 0)
    {
        InterlockedExchange(&g_ActiveRepatchThreads, 0);
        if (g_hNoRepatchThreadsEvent)
            SetEvent(g_hNoRepatchThreadsEvent);
    }
}

static void WaitForRepatchThreadsToFinish()
{
    if (!g_hNoRepatchThreadsEvent)
        return;

    WaitForSingleObject(g_hNoRepatchThreadsEvent, 3000);
}

static void RemoveAllSubclasses()
{
    if (!g_StateLockInitialized)
        return;

    std::vector<HWND> trees;
    std::vector<HWND> explorers;

    EnterCriticalSection(&g_StateLock);

    for (const auto& state : g_TreeStates)
    {
        if (state.hTree)
            trees.push_back(state.hTree);
    }

    for (const auto& state : g_ExplorerStates)
    {
        if (state.hExplorer)
            explorers.push_back(state.hExplorer);
    }

    LeaveCriticalSection(&g_StateLock);

    for (HWND hTree : trees)
    {
        if (IsWindow(hTree))
            WindhawkUtils::RemoveWindowSubclassFromAnyThread(hTree, TreeSubclassProc);
    }

    for (HWND hExplorer : explorers)
    {
        if (IsWindow(hExplorer))
            WindhawkUtils::RemoveWindowSubclassFromAnyThread(hExplorer, ExplorerSubclassProc);
    }
}

static DWORD WINAPI RepatchThreadProc(LPVOID param)
{
    RepatchContext* ctx = (RepatchContext*)param;
    if (!ctx)
    {
        FinishRepatchThread();
        return 0;
    }

    HWND hExplorer = ctx->hExplorer;
    DWORD delayMs = ctx->delayMs;
    delete ctx;

    Sleep(delayMs);

    if (!g_Uninitializing && IsWindow(hExplorer))
        PatchExplorerWindow(hExplorer);

    if (g_StateLockInitialized)
    {
        EnterCriticalSection(&g_StateLock);
        ExplorerState* state = FindExplorerState_NoLock(hExplorer);
        if (state)
            state->repatchPending = false;
        LeaveCriticalSection(&g_StateLock);
    }

    FinishRepatchThread();
    return 0;
}

static void ScheduleOneRepatch(HWND hExplorer, DWORD delayMs)
{
    if (!IsWindow(hExplorer) || !g_StateLockInitialized || g_Uninitializing)
        return;

    bool shouldStart = false;

    EnterCriticalSection(&g_StateLock);
    ExplorerState* state = GetOrCreateExplorerState_NoLock(hExplorer);
    if (state && !state->repatchPending)
    {
        state->repatchPending = true;
        shouldStart = true;
    }
    LeaveCriticalSection(&g_StateLock);

    if (!shouldStart)
        return;

    RepatchContext* ctx = new RepatchContext{};
    ctx->hExplorer = hExplorer;
    ctx->delayMs = delayMs;

    if (g_hNoRepatchThreadsEvent)
        ResetEvent(g_hNoRepatchThreadsEvent);
    InterlockedIncrement(&g_ActiveRepatchThreads);

    HANDLE hThread = CreateThread(nullptr, 0, RepatchThreadProc, ctx, 0, nullptr);
    if (hThread)
    {
        CloseHandle(hThread);
    }
    else
    {
        FinishRepatchThread();
        delete ctx;

        EnterCriticalSection(&g_StateLock);
        state = FindExplorerState_NoLock(hExplorer);
        if (state)
            state->repatchPending = false;
        LeaveCriticalSection(&g_StateLock);
    }
}

static BOOL CALLBACK EnumTopWindowsProc(HWND hwnd, LPARAM)
{
    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);

    if (pid == GetCurrentProcessId() && IsExplorerTopWindow(hwnd))
        PatchExplorerWindow(hwnd);

    return TRUE;
}

static void InitialPatchAllExplorerWindows()
{
    EnumWindows(EnumTopWindowsProc, 0);
}

static void CALLBACK WinEventProc(
    HWINEVENTHOOK,
    DWORD event,
    HWND hwnd,
    LONG idObject,
    LONG,
    DWORD,
    DWORD)
{
    if (!hwnd || g_Uninitializing)
        return;

    if (idObject != OBJID_WINDOW)
        return;

    CleanupDeadStates();

    if (event == EVENT_SYSTEM_MOVESIZEEND)
    {
        HWND hExplorer = IsExplorerTopWindow(hwnd) ? hwnd : FindExplorerTopWindowFromChild(hwnd);
        if (hExplorer)
            ScheduleOneRepatch(hExplorer, 30);
        return;
    }

    if (IsExplorerTopWindow(hwnd))
    {
        PatchExplorerWindow(hwnd);
        ScheduleOneRepatch(hwnd, 120);
        return;
    }

    if (IsLikelyNavTree(hwnd))
    {
        HWND hExplorer = FindExplorerTopWindowFromChild(hwnd);
        if (hExplorer)
        {
            PatchTree(hExplorer, hwnd);
            ScheduleOneRepatch(hExplorer, 120);
        }
        return;
    }

    HWND hExplorer = FindExplorerTopWindowFromChild(hwnd);
    if (hExplorer)
        ScheduleOneRepatch(hExplorer, 120);
}

static HWND WINAPI CreateWindowExW_Hook(
    DWORD dwExStyle,
    LPCWSTR lpClassName,
    LPCWSTR lpWindowName,
    DWORD dwStyle,
    int X,
    int Y,
    int nWidth,
    int nHeight,
    HWND hWndParent,
    HMENU hMenu,
    HINSTANCE hInstance,
    LPVOID lpParam)
{
    HWND hwnd = CreateWindowExW_Original(
        dwExStyle,
        lpClassName,
        lpWindowName,
        dwStyle,
        X,
        Y,
        nWidth,
        nHeight,
        hWndParent,
        hMenu,
        hInstance,
        lpParam);

    if (g_Uninitializing || !hwnd)
        return hwnd;

    if (IsExplorerTopWindow(hwnd))
    {
        TrySubclassExplorer(hwnd);
        PatchExplorerWindow(hwnd);
    }
    else if (IsTreeViewClassName(lpClassName) || IsTreeViewClass(hwnd))
    {
        HWND hExplorer = FindExplorerTopWindowFromChild(hwnd);
        if (hExplorer)
        {
            TrySubclassTree(hwnd);
            PatchTree(hExplorer, hwnd);
        }
    }

    return hwnd;
}

static void RestorePatchedTrees()
{
    if (!g_StateLockInitialized)
        return;

    struct RestoreInfo
    {
        HWND hTree;
        bool restoreStyle;
        LONG_PTR originalStyle;
        bool restoreLayout;
        RECT baseRect;
    };

    std::vector<RestoreInfo> restoreInfos;

    EnterCriticalSection(&g_StateLock);
    for (const auto& state : g_TreeStates)
    {
        RestoreInfo info{};
        info.hTree = state.hTree;
        info.restoreStyle = state.capturedStyle;
        info.originalStyle = state.originalStyle;
        info.restoreLayout = state.capturedLayout;
        info.baseRect = state.baseRect;
        restoreInfos.push_back(info);
    }
    LeaveCriticalSection(&g_StateLock);

    for (const auto& info : restoreInfos)
    {
        if (!IsWindow(info.hTree))
            continue;

        ScopedInternalWindowPos internalMove;

        if (info.restoreStyle)
        {
            SetWindowLongPtrW(info.hTree, GWL_STYLE, info.originalStyle);
            SetWindowPos(
                info.hTree,
                nullptr,
                0, 0, 0, 0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE | SWP_FRAMECHANGED);
        }

        if (info.restoreLayout && RectWidth(info.baseRect) >= 50 && RectHeight(info.baseRect) >= 50)
        {
            SetWindowPos(
                info.hTree,
                nullptr,
                info.baseRect.left,
                info.baseRect.top,
                RectWidth(info.baseRect),
                RectHeight(info.baseRect),
                SWP_NOZORDER | SWP_NOACTIVATE);
        }
    }
}

static DWORD WINAPI WorkerThreadProc(LPVOID)
{
    InitializeCriticalSection(&g_StateLock);
    g_StateLockInitialized = true;

    Wh_Log(L"Worker started");

    InitialPatchAllExplorerWindows();

    DWORD pid = GetCurrentProcessId();

    g_hEventHookShow = SetWinEventHook(
        EVENT_OBJECT_SHOW,
        EVENT_OBJECT_SHOW,
        nullptr,
        WinEventProc,
        pid,
        0,
        WINEVENT_OUTOFCONTEXT);

    g_hEventHookCreate = SetWinEventHook(
        EVENT_OBJECT_CREATE,
        EVENT_OBJECT_CREATE,
        nullptr,
        WinEventProc,
        pid,
        0,
        WINEVENT_OUTOFCONTEXT);

    g_hEventHookMoveSizeEnd = SetWinEventHook(
        EVENT_SYSTEM_MOVESIZEEND,
        EVENT_SYSTEM_MOVESIZEEND,
        nullptr,
        WinEventProc,
        pid,
        0,
        WINEVENT_OUTOFCONTEXT);

    if (!g_hEventHookShow || !g_hEventHookCreate || !g_hEventHookMoveSizeEnd)
        Wh_Log(L"Failed to install one or more WinEvent hooks");
    else
        Wh_Log(L"WinEvent hooks installed");

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    if (g_hEventHookShow)
    {
        UnhookWinEvent(g_hEventHookShow);
        g_hEventHookShow = nullptr;
    }

    if (g_hEventHookCreate)
    {
        UnhookWinEvent(g_hEventHookCreate);
        g_hEventHookCreate = nullptr;
    }

    if (g_hEventHookMoveSizeEnd)
    {
        UnhookWinEvent(g_hEventHookMoveSizeEnd);
        g_hEventHookMoveSizeEnd = nullptr;
    }

    Wh_Log(L"Worker stopped");
    return 0;
}

BOOL Wh_ModInit()
{
    g_Uninitializing = false;
    InterlockedExchange(&g_ActiveRepatchThreads, 0);

    g_hNoRepatchThreadsEvent = CreateEventW(nullptr, TRUE, TRUE, nullptr);
    if (!g_hNoRepatchThreadsEvent)
        Wh_Log(L"Failed to create repatch thread event");

    LoadSettings();

    if (!Wh_SetFunctionHook((void*)CreateWindowExW, (void*)CreateWindowExW_Hook, (void**)&CreateWindowExW_Original))
        Wh_Log(L"Failed to hook CreateWindowExW");

    if (!Wh_SetFunctionHook((void*)DrawThemeBackground, (void*)DrawThemeBackground_Hook, (void**)&DrawThemeBackground_Original))
        Wh_Log(L"Failed to hook DrawThemeBackground");

    if (!Wh_SetFunctionHook((void*)DrawThemeBackgroundEx, (void*)DrawThemeBackgroundEx_Hook, (void**)&DrawThemeBackgroundEx_Original))
        Wh_Log(L"Failed to hook DrawThemeBackgroundEx");

    g_hWorkerThread = CreateThread(
        nullptr,
        0,
        WorkerThreadProc,
        nullptr,
        0,
        &g_WorkerThreadId);

    if (!g_hWorkerThread)
    {
        Wh_Log(L"Failed to create worker thread");
        return FALSE;
    }

    Wh_Log(L"Mod initialized");
    return TRUE;
}

void Wh_ModUninit()
{
    Wh_Log(L"Uninitializing");

    g_Uninitializing = true;

    // Stop WinEvent callbacks first. Otherwise Explorer can create/resize/show
    // windows while we're restoring geometry and unloading the DLL.
    if (g_WorkerThreadId)
        PostThreadMessageW(g_WorkerThreadId, WM_QUIT, 0, 0);

    if (g_hWorkerThread)
    {
        WaitForSingleObject(g_hWorkerThread, 3000);
        CloseHandle(g_hWorkerThread);
        g_hWorkerThread = nullptr;
    }

    // Detached one-shot repatch threads could wake up after Windhawk had already
    // unloaded the module. Wait for them before returning from Wh_ModUninit.
    WaitForRepatchThreadsToFinish();

    // Remove subclass procedures before the DLL is unloaded. Leaving a subclass
    // installed with a callback address inside this module can crash Explorer on
    // the next message and make it look like Explorer restarted on mod disable.
    RemoveAllSubclasses();

    RestorePatchedTrees();

    if (g_StateLockInitialized)
    {
        DeleteCriticalSection(&g_StateLock);
        g_StateLockInitialized = false;
    }

    if (g_hNoRepatchThreadsEvent)
    {
        CloseHandle(g_hNoRepatchThreadsEvent);
        g_hNoRepatchThreadsEvent = nullptr;
    }

    g_WorkerThreadId = 0;
    g_ExplorerStates.clear();
    g_TreeStates.clear();
}

void Wh_ModSettingsChanged()
{
    LoadSettings();
    InitialPatchAllExplorerWindows();
}

// ==WindhawkMod==
// @id              faster-virtual-desktop-switching
// @name            Faster Virtual Desktop Switching
// @description     Removes the long pre-animation lag caused by oversized wallpaper thumbnail requests on Windows 11.
// @version         1.0.1
// @author          meteoni
// @github          https://github.com/Meteoni
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -luser32
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Faster Virtual Desktop Switching

Removes the long-standing pre-animation lag caused by oversized wallpaper thumbnail requests on Windows 11.

![GIF](https://raw.githubusercontent.com/Meteoni/meteoni-assets/main/faster-virtual-desktop-switching/faster-virtual-desktop-switching.gif)

_Note: This can make the wallpaper look softer during the switch. The mod is a no-op on Windows 10._

Windows 11 can synchronously request a full-monitor-sized wallpaper thumbnail
before beginning a virtual desktop transition. On a high-DPI display with specific wallpaper
configurations, that request can take roughly 136-169 ms when warm and more than one second 
when cold (exact figure depends).

This mod caps that request to the maximum size documented for `IThumbnailCache`, which is 
1024 pixels. In testing, that netted a latency reduction of ~150ms, effectively eliminating 
the long-standing pre-animation stutter issue. 

Laptop users who use three- or four-finger swipe gestures can especially benefit from this mod. 

*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- maximumThumbnailSize: 1024
  $name: Maximum thumbnail size
  $description: Requested size used for the transition wallpaper, clamped to the range 64-1024. Microsoft documents 1024 as the maximum supported value.
*/
// ==/WindhawkModSettings==

#include <windows.h>
#include <windhawk_api.h>
#include <windhawk_utils.h>

#include <atomic>

namespace {

struct WtsThumbnailId {
    BYTE value[16];
};

using ThumbnailCacheGetThumbnail = HRESULT(STDMETHODCALLTYPE*)(
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId);
using MakeBackgroundThumbnailFromThumbnailCache = HRESULT(STDMETHODCALLTYPE*)(
    void* self,
    void* dcompThumbnail,
    void* virtualDesktop,
    void* wallpaperPath,
    RECT bounds,
    void** result);
using LoadLibraryExW_t = decltype(&LoadLibraryExW);

// Every target needs its own original pointer. Reusing one across registrations
// would make an earlier detour call whichever target was registered last.
ThumbnailCacheGetThumbnail g_thumbcacheGetThumbnailOriginal = nullptr;
ThumbnailCacheGetThumbnail g_thumbcacheApiGetThumbnailOriginal = nullptr;
ThumbnailCacheGetThumbnail g_windowsStorageGetThumbnailOriginal = nullptr;
ThumbnailCacheGetThumbnail g_windowsStorageApiGetThumbnailOriginal = nullptr;
MakeBackgroundThumbnailFromThumbnailCache
    g_makeBackgroundThumbnailOriginal = nullptr;
LoadLibraryExW_t g_loadLibraryExWOriginal = nullptr;
thread_local int g_makeBackgroundThumbnailDepth = 0;
std::atomic_bool g_twinuiPcShellHookAttempted{false};
std::atomic_bool g_thumbcacheHookAttempted{false};
std::atomic_bool g_windowsStorageHookAttempted{false};
std::atomic_bool g_thumbnailClampLogged{false};
std::atomic<int> g_maximumThumbnailSize{1024};

// Load settings atomically because Explorer can switch desktops while the
// Windhawk settings callback runs on another thread.
void LoadSettings() {
    int maximumSize = Wh_GetIntSetting(L"maximumThumbnailSize");
    if (maximumSize < 64) {
        maximumSize = 64;
    } else if (maximumSize > 1024) {
        maximumSize = 1024;
    }
    g_maximumThumbnailSize.store(maximumSize);
    g_thumbnailClampLogged.store(false);
}

bool IsWindows11OrGreater() {
    using RtlGetVersion_t = LONG(WINAPI*)(OSVERSIONINFOW*);
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    auto rtlGetVersion = ntdll
        ? reinterpret_cast<RtlGetVersion_t>(
              GetProcAddress(ntdll, "RtlGetVersion"))
        : nullptr;
    if (!rtlGetVersion) {
        return false;
    }

    OSVERSIONINFOW versionInfo{};
    versionInfo.dwOSVersionInfoSize = sizeof(versionInfo);
    return rtlGetVersion(&versionInfo) == 0 &&
           versionInfo.dwMajorVersion >= 10 &&
           versionInfo.dwBuildNumber >= 22000;
}

HRESULT STDMETHODCALLTYPE MakeBackgroundThumbnailFromThumbnailCacheHook(
    void* self,
    void* dcompThumbnail,
    void* virtualDesktop,
    void* wallpaperPath,
    RECT bounds,
    void** result) {
    struct DepthGuard {
        DepthGuard() {
            ++g_makeBackgroundThumbnailDepth;
        }

        ~DepthGuard() {
            --g_makeBackgroundThumbnailDepth;
        }
    } depthGuard;

    return g_makeBackgroundThumbnailOriginal(
        self,
        dcompThumbnail,
        virtualDesktop,
        wallpaperPath,
        bounds,
        result);
}

UINT ClampTransitionThumbnailSize(UINT requestedSize) {
    if (g_makeBackgroundThumbnailDepth <= 0) {
        return requestedSize;
    }

    const UINT maximumSize =
        static_cast<UINT>(g_maximumThumbnailSize.load());
    if (requestedSize <= maximumSize) {
        return requestedSize;
    }

    if (!g_thumbnailClampLogged.exchange(true)) {
        Wh_Log(L"Clamped virtual desktop wallpaper thumbnail from %u to %u",
               requestedSize,
               maximumSize);
    }
    return maximumSize;
}

HRESULT CallThumbnailCacheGetThumbnail(
    ThumbnailCacheGetThumbnail original,
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId) {
    requestedSize = ClampTransitionThumbnailSize(requestedSize);
    return original(
        self,
        shellItem,
        requestedSize,
        flags,
        sharedBitmap,
        outFlags,
        thumbnailId);
}

// Clamp only calls made synchronously by Windows' virtual desktop wallpaper
// helper. All other thumbnail-cache clients receive their original arguments.
HRESULT STDMETHODCALLTYPE ThumbcacheGetThumbnailHook(
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId) {
    return CallThumbnailCacheGetThumbnail(
        g_thumbcacheGetThumbnailOriginal,
        self,
        shellItem,
        requestedSize,
        flags,
        sharedBitmap,
        outFlags,
        thumbnailId);
}

HRESULT STDMETHODCALLTYPE ThumbcacheApiGetThumbnailHook(
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId) {
    return CallThumbnailCacheGetThumbnail(
        g_thumbcacheApiGetThumbnailOriginal,
        self,
        shellItem,
        requestedSize,
        flags,
        sharedBitmap,
        outFlags,
        thumbnailId);
}

HRESULT STDMETHODCALLTYPE WindowsStorageGetThumbnailHook(
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId) {
    return CallThumbnailCacheGetThumbnail(
        g_windowsStorageGetThumbnailOriginal,
        self,
        shellItem,
        requestedSize,
        flags,
        sharedBitmap,
        outFlags,
        thumbnailId);
}

HRESULT STDMETHODCALLTYPE WindowsStorageApiGetThumbnailHook(
    void* self,
    void* shellItem,
    UINT requestedSize,
    DWORD flags,
    void** sharedBitmap,
    DWORD* outFlags,
    WtsThumbnailId* thumbnailId) {
    return CallThumbnailCacheGetThumbnail(
        g_windowsStorageApiGetThumbnailOriginal,
        self,
        shellItem,
        requestedSize,
        flags,
        sharedBitmap,
        outFlags,
        thumbnailId);
}

// Hook the outer wallpaper helper so the thumbnail-cache detour can identify
// its dynamic call context without relying on compiler code layout.
bool HookBackgroundThumbnailHelper(HMODULE module) {
    if (!module || g_twinuiPcShellHookAttempted.exchange(true)) {
        return false;
    }

    // twinui.pcshell.dll
    WindhawkUtils::SYMBOL_HOOK symbolHooks[] = {
        {
            {
                L"protected: long __cdecl VirtualDesktopGestureWindow::MakeBackgroundThumbnailFromThumbnailCache(struct IDCompThumbnail *,struct IVirtualDesktop *,struct HSTRING__ *,struct tagRECT,struct IDCompThumbnail * *)",
            },
            &g_makeBackgroundThumbnailOriginal,
            MakeBackgroundThumbnailFromThumbnailCacheHook,
            false,
        },
    };

    const bool symbolsHooked = WindhawkUtils::HookSymbols(
        module, symbolHooks, ARRAYSIZE(symbolHooks));
    if (!g_makeBackgroundThumbnailOriginal) {
        Wh_Log(L"Failed to hook the virtual desktop wallpaper helper");
        return false;
    }
    if (!symbolsHooked) {
        Wh_Log(L"HookSymbols reported a failure after registering the "
               L"virtual desktop wallpaper helper hook");
    }
    return true;
}

// The implementation moved between windows.storage.dll and thumbcache.dll.
// Hook each loaded copy independently, avoiding COM activation and a hard-coded
// vtable slot.
bool HookThumbnailCache(
    HMODULE module,
    std::atomic_bool* hookAttempted,
    PCWSTR moduleName,
    ThumbnailCacheGetThumbnail* getThumbnailOriginal,
    ThumbnailCacheGetThumbnail getThumbnailHook,
    ThumbnailCacheGetThumbnail* apiGetThumbnailOriginal,
    ThumbnailCacheGetThumbnail apiGetThumbnailHook) {
    if (!module || hookAttempted->exchange(true)) {
        return false;
    }

    // thumbcache.dll, windows.storage.dll
    WindhawkUtils::SYMBOL_HOOK symbolHooks[] = {
        {
            {
                L"public: virtual long __cdecl CThumbnailCache::GetThumbnail(struct IShellItem *,unsigned int,enum WTS_FLAGS,struct ISharedBitmap * *,enum WTS_CACHEFLAGS *,struct WTS_THUMBNAILID *)",
            },
            getThumbnailOriginal,
            getThumbnailHook,
            true,
        },
        {
            {
                L"public: virtual long __cdecl CThumbnailCacheAPI::GetThumbnail(struct IShellItem *,unsigned int,enum WTS_FLAGS,struct ISharedBitmap * *,enum WTS_CACHEFLAGS *,struct WTS_THUMBNAILID *)",
            },
            apiGetThumbnailOriginal,
            apiGetThumbnailHook,
            true,
        },
    };

    const bool symbolsHooked = WindhawkUtils::HookSymbols(
        module, symbolHooks, ARRAYSIZE(symbolHooks));
    const bool registeredHook = *getThumbnailOriginal ||
                                *apiGetThumbnailOriginal;
    if (!registeredHook) {
        Wh_Log(L"Failed to hook thumbnail cache in %s", moduleName);
        return false;
    }
    if (!symbolsHooked) {
        Wh_Log(L"HookSymbols reported a failure after registering a "
               L"thumbnail cache hook in %s",
               moduleName);
    }

    Wh_Log(L"Hooked thumbnail cache in %s (concrete=%d api=%d)",
           moduleName,
           *getThumbnailOriginal != nullptr,
           *apiGetThumbnailOriginal != nullptr);
    return true;
}

bool HandleLoadedModule(HMODULE module) {
    if (!module) {
        return false;
    }

    if (!g_twinuiPcShellHookAttempted.load() &&
        module == GetModuleHandleW(L"twinui.pcshell.dll")) {
        return HookBackgroundThumbnailHelper(module);
    }
    if (!g_thumbcacheHookAttempted.load() &&
        module == GetModuleHandleW(L"thumbcache.dll")) {
        return HookThumbnailCache(
            module,
            &g_thumbcacheHookAttempted,
            L"thumbcache.dll",
            &g_thumbcacheGetThumbnailOriginal,
            ThumbcacheGetThumbnailHook,
            &g_thumbcacheApiGetThumbnailOriginal,
            ThumbcacheApiGetThumbnailHook);
    }
    if (!g_windowsStorageHookAttempted.load() &&
        module == GetModuleHandleW(L"windows.storage.dll")) {
        return HookThumbnailCache(
            module,
            &g_windowsStorageHookAttempted,
            L"windows.storage.dll",
            &g_windowsStorageGetThumbnailOriginal,
            WindowsStorageGetThumbnailHook,
            &g_windowsStorageApiGetThumbnailOriginal,
            WindowsStorageApiGetThumbnailHook);
    }
    return false;
}

bool HandleAlreadyLoadedModules() {
    bool hooksRegistered = HandleLoadedModule(
        GetModuleHandleW(L"twinui.pcshell.dll"));
    hooksRegistered = HandleLoadedModule(
                          GetModuleHandleW(L"thumbcache.dll")) ||
                      hooksRegistered;
    hooksRegistered = HandleLoadedModule(
                          GetModuleHandleW(L"windows.storage.dll")) ||
                      hooksRegistered;
    return hooksRegistered;
}

HMODULE WINAPI LoadLibraryExWHook(
    LPCWSTR fileName, HANDLE file, DWORD flags) {
    HMODULE module = g_loadLibraryExWOriginal(fileName, file, flags);
    constexpr DWORD dataOnlyFlags =
        LOAD_LIBRARY_AS_DATAFILE | LOAD_LIBRARY_AS_DATAFILE_EXCLUSIVE |
        LOAD_LIBRARY_AS_IMAGE_RESOURCE;
    if (!module || (flags & dataOnlyFlags)) {
        return module;
    }

    if (HandleLoadedModule(module) && !Wh_ApplyHookOperations()) {
        Wh_Log(L"Failed to apply late-loaded hooks");
    }
    return module;
}

}  // namespace

BOOL Wh_ModInit() {
    if (!IsWindows11OrGreater()) {
        Wh_Log(L"Skipping unsupported Windows version");
        return FALSE;
    }

    LoadSettings();

    HMODULE kernelBase = GetModuleHandleW(L"kernelbase.dll");
    auto loadLibraryExW = kernelBase
        ? reinterpret_cast<LoadLibraryExW_t>(
              GetProcAddress(kernelBase, "LoadLibraryExW"))
        : nullptr;
    if (!loadLibraryExW ||
        !WindhawkUtils::SetFunctionHook(
            loadLibraryExW,
            LoadLibraryExWHook,
            &g_loadLibraryExWOriginal)) {
        Wh_Log(L"Failed to hook kernelbase!LoadLibraryExW");
        return FALSE;
    }

    HandleAlreadyLoadedModules();
    if (g_twinuiPcShellHookAttempted.load() &&
        !g_makeBackgroundThumbnailOriginal) {
        return FALSE;
    }

    return TRUE;
}

void Wh_ModAfterInit() {
    if (HandleAlreadyLoadedModules() && !Wh_ApplyHookOperations()) {
        Wh_Log(L"Failed to apply hooks in Wh_ModAfterInit");
    }
}

void Wh_ModSettingsChanged() {
    LoadSettings();
}

// ==WindhawkMod==
// @id              file-operation-styler
// @name            File Operation Styler
// @description     Portable custom presentation for native Explorer file operations with a skin-safe unified presentation.
// @version         1.2.0
// @author          digART
// @github          https://github.com/digart11
// @license         GPL-3.0
// @include         explorer.exe
// @architecture    x86-64
// @compilerOptions -lcomctl32 -lgdi32 -lgdiplus -lshlwapi -ladvapi32 -luxtheme
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*

# File Operation Styler

A modern replacement for the standard Windows 11 file operation window.

File Operation Styler gives copy, move, delete, and recycle operations a cleaner modern layout while keeping the normal Windows file operation behavior.

![File Operation Styler](https://raw.githubusercontent.com/digart11/File-Operation-Styler/master/images/file-operation-styler.png)

### Interactive Controls

![File Operation Styler interactive controls](https://raw.githubusercontent.com/digart11/File-Operation-Styler/master/images/file-operation-styler-controls.png)

The large progress circle can pause and resume operations, while optional settings can hide the smaller controls and title-bar percentage for a cleaner layout.

### Default vs File Operation Styler

![Default vs File Operation Styler](https://raw.githubusercontent.com/digart11/File-Operation-Styler/master/images/file-operation-styler-compare.png)

### Themes

![File Operation Styler Themes](https://raw.githubusercontent.com/digart11/File-Operation-Styler/master/images/file-operation-styler-themes-1.2.png)

## What's new in 1.2.0

- Added a Frosted Glass theme with Windows Acrylic and Custom Blur styles.
- Added current-file progress while the circular indicator continues to show overall operation progress.
- Added interactive Pause / Resume behavior to the large progress circle.
- Added an option to hide the small Pause / Resume and Cancel buttons in the upper-right corner. The large progress-circle control and bottom Cancel button remain available.
- Added an option to hide the percentage from the file-operation window title.
- Improved multiple-operation support, including synchronized More / Fewer Details behavior.
- Improved fallback to the native Windows UI for conflicts, errors, and unsupported presentation states.
- Improved restoration and teardown when the mod is disabled, reloaded, or settings are changed.

## Features

- Modern copy, move, delete, and recycle operation window
- Circular overall progress indicator
- Current-file progress bar
- Transferred size, remaining items, speed, and estimated time
- Progress graph in More Details view
- Multiple file operations in the same window
- Pause, resume, and cancel controls
- Interactive Pause / Resume control in the large progress circle
- Option to hide the small Pause / Resume and Cancel buttons
- Option to hide the percentage from the window title
- Works with normal Windows conflict and error dialogs
- Several built-in themes, including Frosted Glass
- Windows Acrylic and Custom Blur glass styles
- Custom colors, fonts, text sizes, and progress thickness

## Customization

Choose one of the included themes or adjust the available colors, typography, progress styling, and other presentation options to create your own look.

The Frosted Glass theme supports both Windows Acrylic and Custom Blur, including adjustable tint and opacity.

## Notes

File Operation Styler changes the appearance of the normal Windows file operation window only. Windows continues to handle the actual copy, move, delete, conflicts, errors, pause, resume, and cancel operations.

Settings changes apply to new file-operation windows; operations already in progress may use the native Windows presentation until they complete.

File Operation Styler has been tested on Windows 11 24H2 x64. It relies on private Explorer and Shell presentation interfaces, so other Windows builds can use different symbols or layouts. Unsupported presentations are designed to fall back to the native Windows UI.

*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
