                &COperationStatusTileRateCalculator_CalculateRate_Original))
        {
            Wh_Log(L"Skin setup failed: unable to hook native rate update");
            return false;
        }

        return true;
    }

} // namespace

BOOL Wh_ModInit()
{
    g_unloading.store(false, std::memory_order_release);
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" initialization started");

    LoadSettings();

    if (!InitializeProgressCircleUi())
    {
        return FALSE;
    }

    SkinTargets targets{};
    if (!ResolveSkinTargets(&targets) || !InstallSkinHooks(targets))
    {
        ShutdownProgressCircleUi();
        ReleaseOwnedSkinTargetModules();
        return FALSE;
    }

    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" initialization complete");
    return TRUE;
}

void Wh_ModBeforeUninit()
{
    if (g_unloading.exchange(true, std::memory_order_acq_rel))
    {
        return;
    }

    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" presentation teardown started");
    {
        std::unique_lock<std::mutex> lock(g_presentationActivationMutex);
        g_presentationActivationCondition.wait(
            lock, []
            { return g_presentationActivations == 0; });
    }
    DestroyAllProgressCircles();
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" presentation teardown complete");
}

void Wh_ModUninit()
{
    ShutdownProgressCircleUi();
    {
        std::lock_guard<std::mutex> lock(g_transferSummaryMutex);
        g_transferSummaries.clear();
        ClearOperationDataBindingsLocked();
    }
    ClearSkinState();
    ReleaseOwnedSkinTargetModules();
    ShutdownSharedProgressBridge();
    ShutdownGlassBufferedPaintApi();
    ShutdownDwmApi();
    ShutdownShellMemoryApi();
    Wh_Log(L"File Operation Styler " WH_MOD_VERSION
           L" uninitialization complete");
}

BOOL Wh_ModSettingsChanged(BOOL *bReload)
{
    if (bReload)
    {
        *bReload = TRUE;
    }
    return TRUE;
}

// ==WindhawkMod==
// @id              fix-explorer-white-flash
// @name            Fix white flashes in explorer
// @description     Removes the annoying white flash when opening Explorer tabs.
// @version         1.4
// @author          Mgg Sk
// @github          https://github.com/MGGSK
// @include         explorer.exe
// @compilerOptions -lgdi32
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Fix white flashes in explorer
Removes the annoying white flash when opening new tabs in File Explorer.
This mod blocks intermediate white frames that appear during Explorer tab creation and redraw, making tab opening look cleaner and less distracting.

### Before
![Before](https://raw.githubusercontent.com/MGGSK/MGGSK/refs/heads/main/WindhawkModReadmeImages/fix-explorer-white-flash-before.png)
### After
![After](https://raw.githubusercontent.com/MGGSK/MGGSK/refs/heads/main/WindhawkModReadmeImages/fix-explorer-white-flash-after.png)

## Notes
This mod is focused specifically on the white flash problem. It can also slightly reduce some of the visual jumping during tab creation, but its main purpose is removing the white flash itself.

#### Credits: [mode0192](https://github.com/mode0192), [Languster](https://github.com/Languster)

*/
// ==/WindhawkModReadme==

#include <windows.h>
#include <windhawk_utils.h>
#include <algorithm>

static HMODULE g_hUxTheme = nullptr;

using ShouldAppsUseDarkMode_T = bool(WINAPI*)();
static ShouldAppsUseDarkMode_T ShouldAppsUseDarkMode = nullptr;

decltype(&FillRect) FillRect_Original = nullptr;
decltype(&BitBlt) BitBlt_Original = nullptr;

struct RecentWhiteFill
{
    HDC hdc;
    int w;
    int h;
    DWORD tick;
};

struct FollowupBlock
{
    HWND hWndDest;
    HDC hdcSrc;
    int cx;
    int cy;
    DWORD tick;
    int blocksLeft;
    bool armed;
};

thread_local static RecentWhiteFill g_recent[32];
thread_local static FollowupBlock g_followup[8];

bool IsDarkModeActive()
{
    return ShouldAppsUseDarkMode && ShouldAppsUseDarkMode();
}

int AbsI(int v)
{
    return v < 0 ? -v : v;
}

bool IsWindowClass(HWND hWnd, PCWSTR clsName)
{
    if (!hWnd || !clsName || !*clsName)
        return false;

    wchar_t cls[128] = {};
    GetClassNameW(hWnd, cls, ARRAYSIZE(cls));
    return wcscmp(cls, clsName) == 0;
}

bool IsWhiteishColor(COLORREF c)
{
    return GetRValue(c) >= 230 &&
           GetGValue(c) >= 230 &&
           GetBValue(c) >= 230;
}

bool IsWhiteishBrush(HBRUSH hBrush)
{
    if (!hBrush)
        return false;

    LOGBRUSH logBrush = {};
    if (GetObjectW(hBrush, sizeof(logBrush), &logBrush) != sizeof(logBrush))
        return false;

    if (logBrush.lbStyle != BS_SOLID)
        return false;

    return IsWhiteishColor(logBrush.lbColor);
}

bool TextContainsI(const wchar_t* text, const wchar_t* needle)
{
    if (!text || !needle || !*needle)
        return false;

    wchar_t textLower[1024] = {};
    wchar_t needleLower[256] = {};

    lstrcpynW(textLower, text, ARRAYSIZE(textLower));
    lstrcpynW(needleLower, needle, ARRAYSIZE(needleLower));

    CharLowerBuffW(textLower, lstrlenW(textLower));
    CharLowerBuffW(needleLower, lstrlenW(needleLower));

    return wcsstr(textLower, needleLower) != nullptr;
}

bool IsControlPanelFactoryProcess()
{
    PCWSTR cmd = GetCommandLineW();
    if (!cmd || !*cmd)
        return false;

    if (TextContainsI(cmd, L"/factory,{5bd95610-9434-43c2-886c-57852cc8a120}"))
        return true;

    return false;
}

bool IsRegularExplorerRootWindow(HWND hWndAny)
{
    if (!hWndAny)
        return false;

    HWND hRoot = GetAncestor(hWndAny, GA_ROOT);
    if (!hRoot)
        hRoot = hWndAny;

    if (IsWindowClass(hRoot, L"CabinetWClass"))
        return true;

    if (IsWindowClass(hRoot, L"ExploreWClass"))
        return true;

    return false;
}

bool ShouldHandleBitBltForWindow(HWND hWndDest)
{
    if (!hWndDest)
        return false;

    if (!IsWindowClass(hWndDest, L"DirectUIHWND"))
        return false;

    if (!IsRegularExplorerRootWindow(hWndDest))
        return false;

    return true;
}

bool IsCandidateRectSize(int w, int h)
{
    if (w < 80 || h < 50)
        return false;

    return (w * h) >= 6000;
}

bool IsNearWholeDirectUISurface(HWND hWndDest, int x, int y, int cx, int cy)
{
    RECT rcClient;
    if (!GetClientRect(hWndDest, &rcClient))
        return false;

    int clientW = rcClient.right - rcClient.left;
    int clientH = rcClient.bottom - rcClient.top;

    if (clientW <= 0 || clientH <= 0)
        return false;

    if (AbsI(x) > 8 || AbsI(y) > 8)
        return false;

    int widthSlack  = std::max(24, clientW / 8);
    int heightSlack = std::max(24, clientH / 8);

    if (cx < clientW - widthSlack)
        return false;

    if (cy < clientH - heightSlack)
        return false;

    long blitArea   = 1LL * cx * cy;
    long clientArea = 1LL * clientW * clientH;

    if (blitArea * 100 < clientArea * 70)
        return false;

    return true;
}

void RememberWhiteFill(HDC hdc, int w, int h)
{
    DWORD now = GetTickCount();

    int best = 0;
    DWORD oldest = g_recent[0].tick;

    for (UINT i = 0; i < ARRAYSIZE(g_recent); i++)
    {
        if (g_recent[i].hdc == hdc)
        {
            g_recent[i].w = w;
            g_recent[i].h = h;
            g_recent[i].tick = now;
            return;
        }

        if (g_recent[i].tick < oldest)
        {
            oldest = g_recent[i].tick;
            best = i;
        }
    }

    g_recent[best].hdc = hdc;
    g_recent[best].w = w;
    g_recent[best].h = h;
    g_recent[best].tick = now;
}

int GetMatchTolerance(int size)
{
    if (size < 180)
        return 24;

    if (size < 300)
        return 18;

    return 12;
}

bool MatchRecentWhiteFill(HDC hdc, int w, int h)
{
    DWORD now = GetTickCount();

    for (UINT i = 0; i < ARRAYSIZE(g_recent); i++)
    {
        if (g_recent[i].hdc != hdc)
            continue;

        DWORD age = now - g_recent[i].tick;
        if (age > 650)
            continue;

        int dw = AbsI(g_recent[i].w - w);
        int dh = AbsI(g_recent[i].h - h);

        int tolW = GetMatchTolerance(w);
        int tolH = GetMatchTolerance(h);

        if (dw <= tolW && dh <= tolH)
            return true;
    }

    return false;
}

void ForgetRecentWhiteFill(HDC hdc)
{
    for (UINT i = 0; i < ARRAYSIZE(g_recent); i++)
    {
        if (g_recent[i].hdc == hdc)
        {
            g_recent[i].hdc = nullptr;
            g_recent[i].w = 0;
            g_recent[i].h = 0;
            g_recent[i].tick = 0;
        }
    }
}

int GetFollowupTolerance(int size)
{
    if (size < 180)
        return 28;

    if (size < 300)
        return 20;

    return 14;
}

void ArmFollowupBlock(HWND hWndDest, HDC hdcSrc, int cx, int cy)
{
    DWORD now = GetTickCount();

    int best = 0;
    DWORD oldest = g_followup[0].tick;

    for (UINT i = 0; i < ARRAYSIZE(g_followup); i++)
    {
        if (g_followup[i].armed &&
            g_followup[i].hWndDest == hWndDest)
        {
            g_followup[i].hdcSrc = hdcSrc;
            g_followup[i].cx = cx;
            g_followup[i].cy = cy;
            g_followup[i].tick = now;
            g_followup[i].blocksLeft = 2;
            return;
        }

        if (!g_followup[i].armed)
        {
            best = i;
            break;
        }

        if (g_followup[i].tick < oldest)
        {
            oldest = g_followup[i].tick;
            best = i;
        }
    }

    g_followup[best].hWndDest = hWndDest;
    g_followup[best].hdcSrc = hdcSrc;
    g_followup[best].cx = cx;
    g_followup[best].cy = cy;
    g_followup[best].tick = now;
    g_followup[best].blocksLeft = 2;
    g_followup[best].armed = true;
}

bool ShouldBlockFollowupBitBlt(HWND hWndDest, HDC hdcSrc, int cx, int cy)
{
    DWORD now = GetTickCount();

    for (UINT i = 0; i < ARRAYSIZE(g_followup); i++)
    {
        if (!g_followup[i].armed)
            continue;

        DWORD age = now - g_followup[i].tick;
        if (age > 120 || g_followup[i].blocksLeft <= 0)
        {
            g_followup[i].armed = false;
            continue;
        }

        if (g_followup[i].hWndDest != hWndDest)
            continue;

        int tolW = GetFollowupTolerance(cx);
        int tolH = GetFollowupTolerance(cy);

        if (AbsI(g_followup[i].cx - cx) > tolW ||
            AbsI(g_followup[i].cy - cy) > tolH)
            continue;

        bool sameSrc = (g_followup[i].hdcSrc == hdcSrc);

        if (!sameSrc && age > 45)
            continue;

        g_followup[i].hdcSrc = hdcSrc;
        g_followup[i].cx = cx;
        g_followup[i].cy = cy;
        g_followup[i].tick = now;
        g_followup[i].blocksLeft--;

        if (g_followup[i].blocksLeft <= 0)
            g_followup[i].armed = false;

        return true;
    }

    return false;
}

int WINAPI FillRect_Hook(HDC hdc, const RECT* lprc, HBRUSH hbr)
{
    if (IsDarkModeActive() && lprc && hbr)
    {
        int w = lprc->right - lprc->left;
        int h = lprc->bottom - lprc->top;

        if (IsCandidateRectSize(w, h))
        {
            HWND hWnd = WindowFromDC(hdc);

            if (!hWnd && IsWhiteishBrush(hbr))
                RememberWhiteFill(hdc, w, h);
        }
    }

    return FillRect_Original(hdc, lprc, hbr);
}

BOOL WINAPI BitBlt_Hook(
    HDC hdcDest,
    int x,
    int y,
    int cx,
    int cy,
    HDC hdcSrc,
    int x1,
    int y1,
    DWORD rop)
{
    if (IsDarkModeActive() &&
        rop == SRCCOPY &&
        IsCandidateRectSize(cx, cy))
    {
        HWND hWndDest = WindowFromDC(hdcDest);

        if (ShouldHandleBitBltForWindow(hWndDest) &&
            IsNearWholeDirectUISurface(hWndDest, x, y, cx, cy))
        {
            if (ShouldBlockFollowupBitBlt(hWndDest, hdcSrc, cx, cy))
                return TRUE;

            if (MatchRecentWhiteFill(hdcSrc, cx, cy))
            {
                ForgetRecentWhiteFill(hdcSrc);
                ArmFollowupBlock(hWndDest, hdcSrc, cx, cy);
                return TRUE;
            }
        }
    }

    return BitBlt_Original(hdcDest, x, y, cx, cy, hdcSrc, x1, y1, rop);
}

BOOL Wh_ModInit()
{
    if (IsControlPanelFactoryProcess())
        return FALSE;

    g_hUxTheme = LoadLibraryExW(L"UxTheme.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!g_hUxTheme)
    {
        Wh_Log(L"Failed to load UxTheme.dll!");
        return FALSE;
    }

    ShouldAppsUseDarkMode = (ShouldAppsUseDarkMode_T)GetProcAddress(g_hUxTheme, MAKEINTRESOURCEA(132));

    if (!WindhawkUtils::SetFunctionHook(FillRect, FillRect_Hook, &FillRect_Original))
    {
        Wh_Log(L"Failed to hook FillRect!");
        return FALSE;
    }

    if (!WindhawkUtils::SetFunctionHook(BitBlt, BitBlt_Hook, &BitBlt_Original))
    {
        Wh_Log(L"Failed to hook BitBlt!");
        return FALSE;
    }

    ZeroMemory(g_recent, sizeof(g_recent));
    ZeroMemory(g_followup, sizeof(g_followup));

    return TRUE;
}

void Wh_ModUninit()
{
    if (g_hUxTheme)
    {
        FreeLibrary(g_hUxTheme);
        g_hUxTheme = nullptr;
    }
}

// ==WindhawkMod==
// @id              gnome-dynamic-desktops
// @name            GNOME-like dynamic virtual desktops
// @description     Makes the Windows 11 virtual desktop system behave like the GNOME desktop environment
// @version         1.4
// @author          Giggig
// @github          https://github.com/Giggigx
// @include         windhawk.exe
// @compilerOptions -lole32 -luuid -luser32 -ldwmapi
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# GNOME-Like dynamic virtual desktops

Makes Windows' virtual desktops behave like the GNOME desktop environment. 

### What is "GNOME behavior"?
In the GNOME desktop environment (popular on Linux), virtual workspaces are managed dynamically:
* There is always exactly *one* empty desktop at the end of your workspace list.
* If you move or open a window in that last empty desktop, a new empty desktop is immediately created to its right.
* If a desktop in the middle of your workspaces becomes completely empty, it is automatically deleted, shifting the others over.
* When absolutely no windows are open, the system cleanly reduces itself to a single empty desktop.

This mod implements this exact logic on Windows 11. It's perfect for laptops with trackpad gestures, allowing for endless, seamless switching between workspaces without ever having to manually create or close a desktop again.

![GNOME mod demo](https://i.imgur.com/wih0nm0.gif)

**⚠️ Warning:** When this mod runs, your existing virtual desktops and their custom names are dynamically managed and reset to match GNOME's behavior. Disabling the mod does not automatically restore your previous desktop layout.

Works with Windows 11 build 26100+

**Settings**

* **Don't delete empty desktop immediately**: If you're in an empty virtual desktop it waits for you to switch into another virtual desktop before deleting it. If disabled the desktop will be deleted as soon as it becomes empty.

Special thanks to [VD.ahk](https://github.com/FuPeiJiang/VD.ahk) for providing the correct GUIDs to interface with the virtual desktops system.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- delayedDeletion: true
  $name: Don't delete empty desktop immediately
  $description: When a desktop gets empty, it waits for you to switch desktop before deleting it.
*/
// ==/WindhawkModSettings==

#include <windows.h>
#include <windhawk_api.h>
#include <shobjidl.h>
#include <ObjectArray.h>
#include <dwmapi.h>
#include <vector>
#include <algorithm>

// -------------------------------------------------------------------------
// GUID  (Windows 11 26100+)
// -------------------------------------------------------------------------
const GUID CLSID_ImmersiveShell = { 0xc2f03a33, 0x21f5, 0x47fa, { 0xb4, 0xbb, 0x15, 0x63, 0x62, 0xa2, 0xf2, 0x39 } };
const GUID CLSID_VirtualDesktopManagerInternal = { 0xc5e0cdca, 0x7b6e, 0x41b2, { 0x9f, 0xc4, 0xd9, 0x39, 0x75, 0xcc, 0x46, 0x7b } };
const GUID IID_IVirtualDesktop = { 0x3f07f4be, 0xb107, 0x441a, { 0xaf, 0x0f, 0x39, 0xd8, 0x25, 0x29, 0x07, 0x2c } };
const GUID IID_IVirtualDesktopManagerInternal = { 0x53f5ca0b, 0x158f, 0x4124, { 0x90, 0x0c, 0x05, 0x71, 0x58, 0x06, 0x0b, 0x27 } };

DECLARE_INTERFACE_IID_(IVirtualDesktop, IUnknown, "3f07f4be-b107-441a-af0f-39d82529072c") {
    STDMETHOD(Dummy3)() PURE;
    STDMETHOD(GetId)(GUID* pGuid) PURE;
};

DECLARE_INTERFACE_IID_(IVirtualDesktopManagerInternal, IUnknown, "53f5ca0b-158f-4124-900c-057158060b27") {
    STDMETHOD(Dummy3)() PURE;
    STDMETHOD(MoveViewToDesktop)(IUnknown* pView, IVirtualDesktop* pDesktop) PURE;
    STDMETHOD(Dummy5)() PURE;
    STDMETHOD(GetCurrentDesktop)(IVirtualDesktop** desktop) PURE;
    STDMETHOD(GetDesktops)(IObjectArray** desktops) PURE;
    STDMETHOD(Dummy8)() PURE;
    STDMETHOD(SwitchDesktop)(IVirtualDesktop* desktop) PURE;
    STDMETHOD(Dummy10)() PURE;
    STDMETHOD(CreateDesktop)(IVirtualDesktop** newDesktop) PURE;
    STDMETHOD(Dummy12)() PURE;
    STDMETHOD(RemoveDesktop)(IVirtualDesktop* desktop, IVirtualDesktop* fallback) PURE;
};

// Global Variables
struct ModSettings {
    bool delayedDeletion;
} g_settings;

IVirtualDesktopManagerInternal* g_pDesktopManager = nullptr;
IVirtualDesktopManager* g_pPublicDesktopManager = nullptr;

DWORD g_threadId = 0;
HANDLE g_hThread = nullptr;
HANDLE g_hReadyEvent = nullptr;
HWINEVENTHOOK g_hHookFg = nullptr;
HWINEVENTHOOK g_hHookShowHide = nullptr;
UINT_PTR g_debounceTimer = 0;
GUID g_lastActiveDesktop = {0};

void LoadSettings() {
    g_settings.delayedDeletion = Wh_GetIntSetting(L"delayedDeletion") != 0;
    Wh_Log(L"Settings Loaded - delayedDeletion: %d", g_settings.delayedDeletion);
}

void CleanupCOM() {
    if (g_pDesktopManager) { g_pDesktopManager->Release(); g_pDesktopManager = nullptr; }
    if (g_pPublicDesktopManager) { g_pPublicDesktopManager->Release(); g_pPublicDesktopManager = nullptr; }
}

bool InitializeCOM() {
    if (g_pDesktopManager && g_pPublicDesktopManager) return true;
    
    CleanupCOM();

    IServiceProvider* pServiceProvider = nullptr;
    HRESULT hr = CoCreateInstance(CLSID_ImmersiveShell, NULL, CLSCTX_LOCAL_SERVER, __uuidof(IServiceProvider), (void**)&pServiceProvider);
    if (SUCCEEDED(hr)) {
        pServiceProvider->QueryService(CLSID_VirtualDesktopManagerInternal, IID_IVirtualDesktopManagerInternal, (void**)&g_pDesktopManager);
        pServiceProvider->Release();
    }
    CoCreateInstance(__uuidof(VirtualDesktopManager), NULL, CLSCTX_INPROC_SERVER, __uuidof(IVirtualDesktopManager), (void**)&g_pPublicDesktopManager);
    
    if (!g_pDesktopManager || !g_pPublicDesktopManager) {
        CleanupCOM();
        return false;
    }
    return true;
}

bool IsShellClass(HWND hwnd) {
    static const wchar_t* kShellClasses[] = {
        L"Progman", L"WorkerW", L"Shell_TrayWnd", L"Shell_SecondaryTrayWnd",
        L"Windows.UI.Core.CoreWindow", L"XamlExplorerHostIslandWindow",
        L"MultitaskingViewFrame", L"NotifyIconOverflowWindow",
        L"Windows.UI.Composition.DesktopWindowContentBridge",
    };
    WCHAR className[64];
    if (!GetClassNameW(hwnd, className, ARRAYSIZE(className))) return false;
    for (const wchar_t* name : kShellClasses) {
        if (_wcsicmp(className, name) == 0) return true;
    }
    return false;
}

bool IsValidAppWindow(HWND hwnd, const GUID& currentDesktopId) {
    if (!IsWindowVisible(hwnd)) return false;
    
    LONG_PTR exStyle = GetWindowLongPtr(hwnd, GWL_EXSTYLE);
    if (exStyle & WS_EX_TOOLWINDOW) return false;
    if (GetWindow(hwnd, GW_OWNER) != NULL) return false;

    if (hwnd == GetShellWindow()) return false;
    if (IsShellClass(hwnd)) return false;

    int cloaked = 0;
    if (SUCCEEDED(DwmGetWindowAttribute(hwnd, DWMWA_CLOAKED, &cloaked, sizeof(cloaked)))) {
        // 1 = DWM_CLOAKED_APP (phantom UWP background apps)
        if (cloaked & 1) return false;
        
        // 2 = DWM_CLOAKED_SHELL 
        if (cloaked & 2) {
            GUID winDesktopId = {0};
            if (g_pPublicDesktopManager && SUCCEEDED(g_pPublicDesktopManager->GetWindowDesktopId(hwnd, &winDesktopId))) {
                if (memcmp(&winDesktopId, &currentDesktopId, sizeof(GUID)) == 0) {
                    return false;
                }
            }
        }
    }

    return true;
}

struct EnumCtx {
    std::vector<GUID> windowDesktops;
    int candidates = 0;
    GUID currentDesktopId;
};

BOOL CALLBACK CollectWindowDesktops(HWND hwnd, LPARAM lParam) {
    auto* ctx = (EnumCtx*)lParam;
    if (IsValidAppWindow(hwnd, ctx->currentDesktopId)) {
        ctx->candidates++;
        GUID id{};
        if (SUCCEEDED(g_pPublicDesktopManager->GetWindowDesktopId(hwnd, &id))) {
            ctx->windowDesktops.push_back(id);
        }
    }
    return TRUE;
}

struct ReentrancyGuard {
    bool& flag;
    ReentrancyGuard(bool& f) : flag(f) { flag = true; }
    ~ReentrancyGuard() { flag = false; }
};

// Core Logic
void EvaluateDesktops() {
    static bool g_evaluating = false;
    if (g_evaluating) return;
    ReentrancyGuard guard(g_evaluating);

    if (!InitializeCOM()) return;

    IObjectArray* pDesktops = nullptr;
    HRESULT hr = g_pDesktopManager->GetDesktops(&pDesktops);
    
    if (FAILED(hr) || !pDesktops) {
        Wh_Log(L"COM GetDesktops failed (0x%08X). Skipping this cycle.", hr);
        CleanupCOM();
        return;
    }

    UINT totalDesktops = 0;
    pDesktops->GetCount(&totalDesktops);
    if (totalDesktops == 0) {
        pDesktops->Release();
        return;
    }

    IVirtualDesktop* pCurrentDesktop = nullptr;
    GUID currentDesktopId = {0};
    HRESULT hrCur = g_pDesktopManager->GetCurrentDesktop(&pCurrentDesktop);
    
    if (FAILED(hrCur) || !pCurrentDesktop) {
        Wh_Log(L"GetCurrentDesktop failed. Skipping cycle to prevent blind deletion.");
        pDesktops->Release();
        return;
    }
    
    hrCur = pCurrentDesktop->GetId(&currentDesktopId);
    pCurrentDesktop->Release();
    
    if (FAILED(hrCur)) {
        Wh_Log(L"GetId on current desktop failed. Skipping cycle.");
        pDesktops->Release();
        return;
    }

    bool triggeredBySwitch = false;
    if (memcmp(&currentDesktopId, &g_lastActiveDesktop, sizeof(GUID)) != 0) {
        triggeredBySwitch = true;
        g_lastActiveDesktop = currentDesktopId;
        Wh_Log(L"Desktop switched!");
    }

    EnumCtx ctx;
    ctx.currentDesktopId = currentDesktopId;
    EnumWindows(CollectWindowDesktops, (LPARAM)&ctx);

    if (ctx.candidates > 0 && ctx.windowDesktops.empty()) {
        Wh_Log(L"Could not map any window to a desktop, skipping evaluation to prevent data loss.");
        pDesktops->Release();
        return;
    }

    std::vector<IVirtualDesktop*> desktops;
    std::vector<GUID> desktopIds;
    std::vector<int> windowCounts;

    for (UINT i = 0; i < totalDesktops; ++i) {
        IVirtualDesktop* pDesktop = nullptr;
        if (SUCCEEDED(pDesktops->GetAt(i, IID_IVirtualDesktop, (void**)&pDesktop)) && pDesktop) {
            GUID id = {0};
            if (SUCCEEDED(pDesktop->GetId(&id))) {
                desktops.push_back(pDesktop);
                desktopIds.push_back(id);
                
                int count = (int)std::count_if(ctx.windowDesktops.begin(), ctx.windowDesktops.end(), 
                    [&id](const GUID& winId) { return memcmp(&winId, &id, sizeof(GUID)) == 0; });
                windowCounts.push_back(count);
            } else {
                pDesktop->Release();
            }
        }
    }
    pDesktops->Release();

    totalDesktops = (UINT)desktops.size();
    if (totalDesktops == 0) {
        return;
    }

    int lastPopulatedIndex = -1;
    for (int i = totalDesktops - 1; i >= 0; --i) {
        if (windowCounts[i] > 0) {
            lastPopulatedIndex = i;
            break;
        }
    }

    int desiredTotal = lastPopulatedIndex + 2;
    if (lastPopulatedIndex == -1) {
        desiredTotal = 1;
    }

    // Trailing Desktops
    if (totalDesktops < (UINT)desiredTotal) {
        Wh_Log(L"Creating a new empty desktop on the right.");
        IVirtualDesktop* newDesktop = nullptr;
        g_pDesktopManager->CreateDesktop(&newDesktop);
        if (newDesktop) newDesktop->Release();
    } else if (totalDesktops > (UINT)desiredTotal) {
        for (int i = totalDesktops - 1; i >= desiredTotal; --i) {
            bool isCurrent = (memcmp(&desktopIds[i], &currentDesktopId, sizeof(GUID)) == 0);
            
            if (lastPopulatedIndex != -1 && g_settings.delayedDeletion && isCurrent) {
                Wh_Log(L"Skipping deletion of in-use trailing desktop.");
                break; 
            }
            
            Wh_Log(L"Destroying excess empty trailing desktop.");
            g_pDesktopManager->RemoveDesktop(desktops[i], desktops[0]);
        }
    }

    // Middle Desktops
    if (lastPopulatedIndex != -1) {
        IVirtualDesktop* pFallback = desktops[lastPopulatedIndex];
        for (int i = 0; i < lastPopulatedIndex; ++i) {
            if (windowCounts[i] == 0) {
                bool isCurrent = (memcmp(&desktopIds[i], &currentDesktopId, sizeof(GUID)) == 0);
                if (g_settings.delayedDeletion) {
                    if (triggeredBySwitch && !isCurrent) {
                        Wh_Log(L"Destroying empty desktop in the middle (Switched to other desktop).");
                        g_pDesktopManager->RemoveDesktop(desktops[i], pFallback);
                    }
                } else {
                    Wh_Log(L"Destroying empty desktop in the middle (Immediate).");
                    g_pDesktopManager->RemoveDesktop(desktops[i], pFallback);
                }
            }
        }
    }

    for (auto* p : desktops) {
        p->Release();
    }
}

// Events
VOID CALLBACK TimerProc(HWND hwnd, UINT uMsg, UINT_PTR idEvent, DWORD dwTime) {
    KillTimer(NULL, idEvent);
    g_debounceTimer = 0;
    EvaluateDesktops();
}

void CALLBACK WinEventProc(HWINEVENTHOOK hWinEventHook, DWORD event, HWND hwnd, LONG idObject, LONG idChild, DWORD dwEventThread, DWORD dwmsEventTime) {
    if (idObject != OBJID_WINDOW || hwnd == NULL) return;
    
    if (g_debounceTimer) KillTimer(NULL, g_debounceTimer);
    g_debounceTimer = SetTimer(NULL, 150, 150, TimerProc);
}

DWORD WINAPI BackgroundEventThread(LPVOID lpParam) {
    CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);

    MSG msg;
    PeekMessage(&msg, nullptr, 0, 0, PM_NOREMOVE); // forces queue creation
    if (g_hReadyEvent) SetEvent(g_hReadyEvent);

    g_hHookFg = SetWinEventHook(EVENT_SYSTEM_FOREGROUND, EVENT_SYSTEM_FOREGROUND, NULL, WinEventProc, 0, 0, WINEVENT_OUTOFCONTEXT);
    g_hHookShowHide = SetWinEventHook(EVENT_OBJECT_DESTROY, EVENT_OBJECT_HIDE, NULL, WinEventProc, 0, 0, WINEVENT_OUTOFCONTEXT);

    Wh_Log(L"Listening background thread started");
    
    LoadSettings();

    while (GetMessage(&msg, NULL, 0, 0)) {
        if (!msg.hwnd && msg.message == WM_APP) {
            LoadSettings(); 
            EvaluateDesktops();
            continue;
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    Wh_Log(L"Closing background thread");

    if (g_hHookFg) UnhookWinEvent(g_hHookFg);
    if (g_hHookShowHide) UnhookWinEvent(g_hHookShowHide);

    CleanupCOM();
    CoUninitialize();
    return 0;
}

// -------------------------------------------------------------------------
// Tool Lifecycle
// -------------------------------------------------------------------------
BOOL WhTool_ModInit() {
    Wh_Log(L"=== INITIALIZATION ===");
    
    g_hReadyEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (!g_hReadyEvent) {
        return FALSE;
    }

    g_hThread = CreateThread(NULL, 0, BackgroundEventThread, NULL, 0, &g_threadId);
    if (!g_hThread || WaitForSingleObject(g_hReadyEvent, 5000) != WAIT_OBJECT_0) {
        if (g_hThread) {
            CloseHandle(g_hThread);
            g_hThread = nullptr;
            g_threadId = 0;
        }
        CloseHandle(g_hReadyEvent);
        g_hReadyEvent = nullptr;
        return FALSE;
    }
    
    CloseHandle(g_hReadyEvent);
    g_hReadyEvent = nullptr;
    return TRUE;
}

void WhTool_ModUninit() {
    Wh_Log(L"=== UNLOADING ===");
    if (g_threadId && g_hThread) {
        PostThreadMessage(g_threadId, WM_QUIT, 0, 0);
        
        DWORD waitResult = WaitForSingleObject(g_hThread, 5000);
        if (waitResult == WAIT_TIMEOUT) {
            Wh_Log(L"Background thread didn't exit in 5s. Exiting anyway to prevent hang.");
        }
        
        CloseHandle(g_hThread);
        g_hThread = nullptr;
        g_threadId = 0;
    }
}

void WhTool_ModSettingsChanged() {
    Wh_Log(L"=== SETTING CHANGED ===");
    if (g_threadId) {
        PostThreadMessage(g_threadId, WM_APP, 0, 0);
    }
}

