        ComPtr<IToolTipServiceStaticsAbi> spService;
        if (FAILED(RoGetActivationFactory(
                HStringReference(L"Windows.UI.Xaml.Controls.ToolTipService")
                    .Get(),
                kIID_IToolTipServiceStatics, &spService)) ||
            !spService) {
