std::vector<HWND> GetCoreWindows() {
    struct ENUM_WINDOWS_PARAM {
        std::vector<HWND>* hWnds;
    };

    std::vector<HWND> hWnds;
    ENUM_WINDOWS_PARAM param = {&hWnds};
    EnumWindows(
        [](HWND hWnd, LPARAM lParam) -> BOOL {
            ENUM_WINDOWS_PARAM& param = *(ENUM_WINDOWS_PARAM*)lParam;

            if (IsTargetCoreWindow(hWnd)) {
                param.hWnds->push_back(hWnd);
            }

            return TRUE;
        },
        (LPARAM)&param);

    return hWnds;
}

void AdjustCoreWindowPos(int* x, int* y, int* cx, int* cy) {
    Wh_Log(L"Before: %dx%d %dx%d", *x, *y, *cx, *cy);

    RECT rc{
        .left = *x,
        .top = *y,
        .right = *x + *cx,
        .bottom = *y + *cy,
    };
    HMONITOR srcMonitor = MonitorFromRect(&rc, MONITOR_DEFAULTTONEAREST);

    UINT srcMonitorDpiX = 96;
    UINT srcMonitorDpiY = 96;
    GetDpiForMonitor(srcMonitor, MDT_DEFAULT, &srcMonitorDpiX, &srcMonitorDpiY);

    RECT srcMonitorWorkArea;
    if (!GetMonitorWorkArea(srcMonitor, &srcMonitorWorkArea)) {
        return;
    }

    HMONITOR destMonitor = nullptr;

    if (!g_unloading) {
        if (*g_settings.monitorInterfaceName.get()) {
            destMonitor = GetMonitorByInterfaceNameSubstr(
                g_settings.monitorInterfaceName.get());
        } else if (g_settings.monitor == 0) {
            POINT pt;
            GetCursorPos(&pt);
            destMonitor = MonitorFromPoint(pt, MONITOR_DEFAULTTONEAREST);
        } else if (g_settings.monitor >= 1) {
            destMonitor = GetMonitorById(g_settings.monitor - 1);
        }
    }

    if (!destMonitor) {
        HMONITOR primaryMonitor =
            MonitorFromPoint({0, 0}, MONITOR_DEFAULTTONEAREST);

        destMonitor = primaryMonitor;
    }

    RECT destMonitorWorkArea;
    int horizontalDistanceFromScreenEdge = 0;
    int verticalDistanceFromScreenEdge = 0;

    Wh_Log(L"Monitor %p->%p", srcMonitor, destMonitor);

    if (destMonitor != srcMonitor) {
        UINT destMonitorDpiX = 96;
        UINT destMonitorDpiY = 96;
        GetDpiForMonitor(destMonitor, MDT_DEFAULT, &destMonitorDpiX,
                         &destMonitorDpiY);

        if (!GetMonitorWorkArea(destMonitor, &destMonitorWorkArea)) {
            return;
        }

        *cx = MulDiv(*cx, destMonitorDpiX, srcMonitorDpiX);
        if (*y + *cy == srcMonitorWorkArea.bottom) {
            *y = destMonitorWorkArea.bottom -
                 MulDiv(*cy, destMonitorDpiY, srcMonitorDpiY);
            *cy = MulDiv(*cy, destMonitorDpiY, srcMonitorDpiY);
        } else {
            *cy = MulDiv(*cy, destMonitorDpiY, srcMonitorDpiY);
        }

        if (*y == destMonitorWorkArea.top &&
            *y + *cy > destMonitorWorkArea.bottom) {
            *cy = destMonitorWorkArea.bottom - destMonitorWorkArea.top;
        }

        if (!g_unloading) {
            horizontalDistanceFromScreenEdge =
                MulDiv(g_settings.horizontalDistanceFromScreenEdge,
                       destMonitorDpiX, 96);
            verticalDistanceFromScreenEdge = MulDiv(
                g_settings.verticalDistanceFromScreenEdge, destMonitorDpiY, 96);
        }
    } else {
        CopyRect(&destMonitorWorkArea, &srcMonitorWorkArea);

        if (!g_unloading) {
            horizontalDistanceFromScreenEdge =
                MulDiv(g_settings.horizontalDistanceFromScreenEdge,
                       srcMonitorDpiX, 96);
            verticalDistanceFromScreenEdge = MulDiv(
                g_settings.verticalDistanceFromScreenEdge, srcMonitorDpiY, 96);
        }
    }

    switch (g_unloading ? HorizontalPlacement::right
                        : g_settings.horizontalPlacement) {
        case HorizontalPlacement::right:
            *x = destMonitorWorkArea.right - *cx -
                 horizontalDistanceFromScreenEdge;
            break;

        case HorizontalPlacement::left:
            *x = destMonitorWorkArea.left + horizontalDistanceFromScreenEdge;
            break;

        case HorizontalPlacement::center:
            *x = destMonitorWorkArea.left +
                 (destMonitorWorkArea.right - destMonitorWorkArea.left - *cx) /
                     2 +
                 horizontalDistanceFromScreenEdge;
            break;
    }

    switch (g_unloading ? VerticalPlacement::bottom
                        : g_settings.verticalPlacement) {
        case VerticalPlacement::bottom:
            *y = destMonitorWorkArea.bottom - *cy -
                 verticalDistanceFromScreenEdge;
            break;

        case VerticalPlacement::top:
            *y = destMonitorWorkArea.top + verticalDistanceFromScreenEdge;
            break;

        case VerticalPlacement::center:
            *y = destMonitorWorkArea.top +
                 (destMonitorWorkArea.bottom - destMonitorWorkArea.top - *cy) /
                     2 +
                 verticalDistanceFromScreenEdge;
            break;
    }

    Wh_Log(L"After: %dx%d %dx%d", *x, *y, *cx, *cy);
}

using CToastCenterExperienceManager_PositionView_t =
    HRESULT(WINAPI*)(void* pThis);
CToastCenterExperienceManager_PositionView_t
    CToastCenterExperienceManager_PositionView_Original;
HRESULT WINAPI CToastCenterExperienceManager_PositionView_Hook(void* pThis) {
    Wh_Log(L">");

    g_inCToastCenterExperienceManager_PositionView = true;
    HRESULT ret = CToastCenterExperienceManager_PositionView_Original(pThis);
    g_inCToastCenterExperienceManager_PositionView = false;

    return ret;
}

using MonitorFromPoint_t = decltype(&MonitorFromPoint);
MonitorFromPoint_t MonitorFromPoint_Original;
HMONITOR WINAPI MonitorFromPoint_Hook(POINT pt, DWORD dwFlags) {
    Wh_Log(L">");

    if (g_inCToastCenterExperienceManager_PositionView && !g_unloading &&
        pt.x == 0 && pt.y == 0) {
        HMONITOR monitor = nullptr;

        if (*g_settings.monitorInterfaceName.get()) {
            monitor = GetMonitorByInterfaceNameSubstr(
                g_settings.monitorInterfaceName.get());
        } else if (g_settings.monitor == 0) {
            POINT cursorPt;
            GetCursorPos(&cursorPt);
            monitor =
                MonitorFromPoint_Original(cursorPt, MONITOR_DEFAULTTONEAREST);
        } else if (g_settings.monitor >= 1) {
            monitor = GetMonitorById(g_settings.monitor - 1);
        }

        if (monitor) {
            return monitor;
        }
    }

    return MonitorFromPoint_Original(pt, dwFlags);
}

void UpdateAnimationDirectionStyle() {
    int angle = 0;

    switch (g_unloading ? AnimationDirection::fromRight
                        : g_settings.animationDirection) {
        case AnimationDirection::automatic:
            if (g_settings.horizontalPlacement == HorizontalPlacement::center) {
                if (g_settings.verticalPlacement == VerticalPlacement::bottom) {
                    angle = 90;
                } else {
                    angle = -90;
                }
            } else if (g_settings.horizontalPlacement ==
                       HorizontalPlacement::left) {
                angle = 180;
            }
            break;

        case AnimationDirection::fromLeft:
            angle = 180;
            break;

        case AnimationDirection::fromRight:
            break;

        case AnimationDirection::fromTop:
            angle = 90;
            break;

        case AnimationDirection::fromBottom:
            angle = -90;
            break;
    }

    if (!g_customAnimationDirectionApplied && !angle) {
        return;
    }

    auto window = Window::Current();
    if (!window) {
        Wh_Log(L"Failed to get current window");
        return;
    }

    FrameworkElement windowContent = window.Content().as<FrameworkElement>();
    if (!windowContent) {
        Wh_Log(L"Failed to get window content");
        return;
    }

    FrameworkElement launcherFrame = nullptr;

    FrameworkElement child = windowContent;
    if ((child = FindChildByClassName(
             child, L"Windows.UI.Xaml.Controls.ContentPresenter")) &&
        (child =
             FindChildByClassName(child, L"ActionCenter.ToastCenterPage")) &&
        (child = FindChildByName(child, L"ToastCenterMainGrid")) &&
        (child = FindChildByName(child, L"ToastCenterView")) &&
        (child = FindChildByName(child, L"ToastCenterScrollViewer")) &&
        (child = FindChildByName(child, L"Root")) &&
        (child =
             FindChildByClassName(child, L"Windows.UI.Xaml.Controls.Grid")) &&
        (child = FindChildByName(child, L"ScrollContentPresenter")) &&
        (child = FindChildByName(child, L"ToastCenterGrid"))) {
        launcherFrame = child;
    }

    if (!launcherFrame) {
        Wh_Log(L"Failed to find launcher frame");
        return;
    }

    auto origin = winrt::Windows::Foundation::Point{0.5, 0.5};

    bool foundAnyRootGridContent = false;
    EnumChildElements(launcherFrame, [&](FrameworkElement toastView) {
        auto name = toastView.Name();
        if (name.empty()) {
            return false;  // continue enumeration
        }

        if (!name.starts_with(L"FlexibleNormalToastView") &&
            !name.starts_with(L"FlexiblePriorityToastView")) {
            return false;  // continue enumeration
        }

        FrameworkElement mainGrid = FindChildByName(toastView, L"MainGrid");
        if (!mainGrid) {
            return false;  // continue enumeration
        }

        if (FrameworkElement revealGrid =
                FindChildByName(mainGrid, L"RevealGrid")) {
            Wh_Log(L"Applying transform to toast view %s", name.c_str());

            Media::RotateTransform transform;
            transform.Angle(-angle);
            revealGrid.RenderTransform(transform);
            revealGrid.RenderTransformOrigin(origin);

            foundAnyRootGridContent = true;
        }

        // Older Windows 11 versions have both RevealGrid and RevealGrid2
        // (before ~Jul 2026). Newer builds only have RevealGrid.
        if (FrameworkElement revealGrid2 =
                FindChildByName(mainGrid, L"RevealGrid2")) {
            Wh_Log(L"Applying transform to toast view %s", name.c_str());

            Media::RotateTransform transform;
            transform.Angle(-angle);
            revealGrid2.RenderTransform(transform);
            revealGrid2.RenderTransformOrigin(origin);

            foundAnyRootGridContent = true;
        }

        return false;  // continue enumeration to find all matching children
    });

    if (!foundAnyRootGridContent) {
        Wh_Log(L"Failed to find root grid content");
        return;
    }

    Media::RotateTransform transform;
    transform.Angle(angle);
    launcherFrame.RenderTransform(transform);
    launcherFrame.RenderTransformOrigin(origin);

    g_customAnimationDirectionApplied = (angle != 0);
}

using SetWindowPos_t = decltype(&SetWindowPos);
SetWindowPos_t SetWindowPos_Original;
BOOL WINAPI SetWindowPos_Hook(HWND hWnd,
                              HWND hWndInsertAfter,
                              int X,
                              int Y,
                              int cx,
                              int cy,
                              UINT uFlags) {
    auto original = [&]() {
        return SetWindowPos_Original(hWnd, hWndInsertAfter, X, Y, cx, cy,
                                     uFlags);
    };

    if (!IsTargetCoreWindow(hWnd)) {
        return original();
    }

    Wh_Log(L"%08X %08X", (DWORD)(ULONG_PTR)hWnd, uFlags);

    RECT rc{};
    GetWindowRect(hWnd, &rc);

    // Skip if no size or empty size.
    if ((uFlags & SWP_NOSIZE) || cx == 0 || cy == 0) {
        Wh_Log(L"Skipping");
        uFlags |= SWP_NOMOVE | SWP_NOSIZE;
        return original();
    }

    if (uFlags & SWP_NOMOVE) {
        uFlags &= ~SWP_NOMOVE;
        X = rc.left;
        Y = rc.top;
    }

    if (uFlags & SWP_NOSIZE) {
        uFlags &= ~SWP_NOSIZE;
        cx = rc.right - rc.left;
        cy = rc.bottom - rc.top;
    }

    AdjustCoreWindowPos(&X, &Y, &cx, &cy);

    BOOL ret =
        SetWindowPos_Original(hWnd, hWndInsertAfter, X, Y, cx, cy, uFlags);

    if (g_target == Target::ShellExperienceHost &&
        GetWindowThreadProcessId(hWnd, nullptr) == GetCurrentThreadId()) {
        UpdateAnimationDirectionStyle();
    }

    return ret;
}

namespace ShellExperienceHost {

void ApplySettings() {
    for (HWND hCoreWnd : GetCoreWindows()) {
        Wh_Log(L"Adjusting core window %08X", (DWORD)(ULONG_PTR)hCoreWnd);

        RECT rc;
        if (!GetWindowRect(hCoreWnd, &rc)) {
            continue;
        }

        int x = rc.left;
        int y = rc.top;
        int cx = rc.right - rc.left;
        int cy = rc.bottom - rc.top;

        AdjustCoreWindowPos(&x, &y, &cx, &cy);

        SetWindowPos_Original(hCoreWnd, nullptr, x, y, cx, cy,
                              SWP_NOZORDER | SWP_NOACTIVATE);
    }
}

}  // namespace ShellExperienceHost

bool HookTwinuiPcshellSymbols() {
    HMODULE module = LoadLibraryEx(L"twinui.pcshell.dll", nullptr,
                                   LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!module) {
        Wh_Log(L"Loading twinui.pcshell.dll failed");
        return false;
    }

    // twinui.pcshell.dll
    WindhawkUtils::SYMBOL_HOOK symbolHooks[] = {
        {
            {LR"(private: long __cdecl CToastCenterExperienceManager::PositionView(void))"},
            &CToastCenterExperienceManager_PositionView_Original,
            CToastCenterExperienceManager_PositionView_Hook,
        },
    };

    if (!HookSymbols(module, symbolHooks, ARRAYSIZE(symbolHooks))) {
        Wh_Log(L"HookSymbols failed");
        return false;
    }

    return true;
}

void LoadSettings() {
    g_settings.monitor = Wh_GetIntSetting(L"monitor");
    g_settings.monitorInterfaceName =
        WindhawkUtils::StringSetting::make(L"monitorInterfaceName");

    PCWSTR horizontalPlacement = Wh_GetStringSetting(L"horizontalPlacement");
    g_settings.horizontalPlacement = HorizontalPlacement::right;
    if (wcscmp(horizontalPlacement, L"left") == 0) {
        g_settings.horizontalPlacement = HorizontalPlacement::left;
    } else if (wcscmp(horizontalPlacement, L"center") == 0) {
        g_settings.horizontalPlacement = HorizontalPlacement::center;
    }
    Wh_FreeStringSetting(horizontalPlacement);

    g_settings.horizontalDistanceFromScreenEdge =
        Wh_GetIntSetting(L"horizontalDistanceFromScreenEdge");

    PCWSTR verticalPlacement = Wh_GetStringSetting(L"verticalPlacement");
    g_settings.verticalPlacement = VerticalPlacement::bottom;
    if (wcscmp(verticalPlacement, L"top") == 0) {
        g_settings.verticalPlacement = VerticalPlacement::top;
    } else if (wcscmp(verticalPlacement, L"center") == 0) {
        g_settings.verticalPlacement = VerticalPlacement::center;
    }
    Wh_FreeStringSetting(verticalPlacement);

    g_settings.verticalDistanceFromScreenEdge =
        Wh_GetIntSetting(L"verticalDistanceFromScreenEdge");

    PCWSTR animationDirection = Wh_GetStringSetting(L"animationDirection");
    g_settings.animationDirection = AnimationDirection::automatic;
    if (wcscmp(animationDirection, L"fromLeft") == 0) {
        g_settings.animationDirection = AnimationDirection::fromLeft;
    } else if (wcscmp(animationDirection, L"fromRight") == 0) {
        g_settings.animationDirection = AnimationDirection::fromRight;
    } else if (wcscmp(animationDirection, L"fromTop") == 0) {
        g_settings.animationDirection = AnimationDirection::fromTop;
    } else if (wcscmp(animationDirection, L"fromBottom") == 0) {
        g_settings.animationDirection = AnimationDirection::fromBottom;
    }
    Wh_FreeStringSetting(animationDirection);
}

BOOL Wh_ModInit() {
    Wh_Log(L">");

    LoadSettings();

    g_target = Target::Explorer;

    WCHAR moduleFilePath[MAX_PATH];
    switch (
        GetModuleFileName(nullptr, moduleFilePath, ARRAYSIZE(moduleFilePath))) {
        case 0:
        case ARRAYSIZE(moduleFilePath):
            Wh_Log(L"GetModuleFileName failed");
            return FALSE;

        default:
            if (PCWSTR moduleFileName = wcsrchr(moduleFilePath, L'\\')) {
                moduleFileName++;
                if (_wcsicmp(moduleFileName, L"ShellExperienceHost.exe") == 0) {
                    g_target = Target::ShellExperienceHost;
                }
            } else {
                Wh_Log(L"GetModuleFileName returned an unsupported path");
                return FALSE;
            }
            break;
    }

    WindhawkUtils::SetFunctionHook(SetWindowPos, SetWindowPos_Hook,
                                   &SetWindowPos_Original);

    if (g_target == Target::Explorer) {
        if (!HookTwinuiPcshellSymbols()) {
            return FALSE;
        }

        WindhawkUtils::SetFunctionHook(MonitorFromPoint, MonitorFromPoint_Hook,
                                       &MonitorFromPoint_Original);
    }

    return TRUE;
}

void Wh_ModAfterInit() {
    Wh_Log(L">");

    if (g_target == Target::ShellExperienceHost) {
        ShellExperienceHost::ApplySettings();
    }
}

void Wh_ModBeforeUninit() {
    Wh_Log(L">");

    g_unloading = true;

    if (g_target == Target::ShellExperienceHost) {
        ShellExperienceHost::ApplySettings();
    }
}

void Wh_ModUninit() {
    Wh_Log(L">");
}

void Wh_ModSettingsChanged() {
    Wh_Log(L">");

    LoadSettings();

    if (g_target == Target::ShellExperienceHost) {
        ShellExperienceHost::ApplySettings();
    }
}

// ==WindhawkMod==
// @id              parallax-wallpaper
// @name            Parallax Wallpaper
// @description     Smooth mouse-reactive wallpaper with optional perspective, four motion presets, independent multi-monitor support, and HDR-aware rendering
// @version         0.9.0
// @author          HaVeN80
// @github          https://github.com/haven80
// @license         MIT
// @include         windhawk.exe
// @compilerOptions -lgdi32 -lgdiplus -lole32 -luuid -ldwmapi -ld2d1 -ld3d11 -ldxgi -ldcomp -lshell32
// ==/WindhawkMod==

// clang-format off
// ==WindhawkModReadme==
/*
# Parallax Wallpaper

Adds subtle depth to your desktop by moving the wallpaper in response to the
mouse. Desktop icons stay in place. Each monitor uses its own Windows wallpaper
or an optional local image.

The mod runs in its own background process rather than inside Explorer, so a
graphics driver problem cannot take the shell down with it.
![Parallax Wallpaper demo](https://i.imgur.com/jW1oE6J.gif)
## Motion presets

| Preset | Character | Horizontal / vertical travel | Approx. settling time | Dead zone |
|---|---|---|---|---|
| Elegance | Subtle and restrained | 14 / 8 px | 750 ms | 3% |
| Silk | Soft and floating | 22 / 12 px | 1050 ms | 4% |
| Depth | More noticeable, with a quicker response | 32 / 18 px | 850 ms | 2% |
| Cinema | Broad and slow | 42 / 24 px | 1350 ms | 5% |

Travel is the maximum distance in each direction. Settling time is approximately
how long the critically damped motion takes to reach 95% of a suddenly changed
target from rest. Actual motion depends on the cursor trajectory.

Start with **Elegance**, **Floating dead zone = -1**, manual customization off,
**Subpixel motion** on, **HDR color management** on, and **Frame rate limit = 0**
(automatic).

### Floating dead zone

Small pointer adjustments do not change the animation target. The tolerance
follows the last accepted target instead of applying only at the screen center.
Once the pointer crosses the boundary, the target moves continuously, without a
position jump. Motion that has already started still settles gently.

- `-1` uses each preset's dead zone.
- `0` disables the dead zone while retaining smooth acceleration and deceleration.
- `3` gives a radius equivalent to 3% of the screen width horizontally and 3% of
  its height vertically. Larger values provide more separation from the cursor.

Manual travel and settling-time values apply only when manual customization is
on.

## Optional perspective

Enable **Enable perspective** with **Subpixel motion** on to tilt the wallpaper
as a flat panel following the pointer. Start with 2 degrees on both axes,
intensity 100%, and automatic edge compensation on. Perspective is off by
default.

Horizontal and vertical tilt range from 0 to 8 degrees. Intensity (0 to 200%)
controls perspective foreshortening; zero keeps an orthographic tilt.
Automatic compensation applies a constant zoom, computed once for the largest
tilt, so the screen stays covered without the image visibly zooming in and out
during motion. It crops a little more of the image. Disabling it may reveal
black edges.

Tilt shares the current motion preset's settling time, dead zone, direction,
fullscreen pause and independent-monitor behavior. It also works when travel
is set to zero. Per-monitor perspective can inherit global values, be disabled,
or use custom values independently of the monitor's motion preset.

Perspective is rendered with a Direct3D 11 / Direct2D effect pipeline, using
high-quality cubic sampling to avoid moving line patterns; on low-end GPUs,
lowering the frame rate limit reduces its cost. If the
pipeline is unavailable, the monitor falls back to the standard movement
without perspective. Disabling Subpixel motion also disables perspective. This
is a flat-image illusion, not a depth map or separate moving image layers.

## Multiple monitors

With **Independent monitors** enabled, only the monitor under the pointer receives
new targets. Other monitors finish their existing movement and then stop. When
disabled, all monitors follow the pointer's relative position on the active
monitor. Images remain separate; this is not a continuous panoramic wallpaper.

Display connections, disconnections, resolution changes, HDR changes,
wallpaper changes and Explorer restarts are detected automatically. Rebuilding the layout resets the
motion to the center.

### Per-monitor rules

Add entries under **Per-monitor rules** using `DISPLAY1`, `DISPLAY2`, etc., or the
full hardware path from the mod log. These names do not necessarily match the
numbers shown by Windows' Identify button. DISPLAY names can change when devices
are reconnected; a full hardware path provides a more stable match.

To find the identifiers, enable mod logging in Windhawk's Advanced tab, open the
log output, and save the settings. Each monitor is logged with its DISPLAY name,
rectangle, HDR state and `id`. Copy the complete `id` for an exact,
case-insensitive match. Logging can then be disabled.

The first matching rule wins. Fill entries consecutively: an empty monitor field
ends the list. Up to 32 rules are supported. A rule can inherit the global motion
settings and direction, choose another preset, use manual motion values, disable
the effect, or choose a local image. A blank image path uses that monitor's
Windows wallpaper. Image paths may contain environment variables such as
`%USERPROFILE%`. Image overrides do not change Windows' saved wallpaper settings.

## HDR color management

When Windows HDR ("Use HDR") is turned on for a monitor, this option renders the
wallpaper through a native wide-gamut (scRGB, FP16) swap chain: the image is
explicitly tagged as sRGB, converted with Direct2D's color-management effect,
and scaled to the **SDR content brightness** chosen in Windows' HDR settings.
The result matches how Windows presents other SDR content on that monitor, and
follows the brightness slider when it changes. Source images remain ordinary
SDR files; this does not add high-dynamic-range highlights.

Monitors without HDR, including SDR monitors that only use Windows' automatic
color management, keep the standard rendering path. The option requires
**Subpixel motion**. If the HDR or perspective pipeline fails on a monitor, that
monitor continues with standard rendering. Failures are retried with increasing
intervals and written to the mod log with the HRESULT. GPU resets (driver
updates, remote desktop sessions) are recovered automatically.

## Performance and compatibility

Images are decoded and resized once on a background thread and reused, so
loading a large image does not interrupt the animation. EXIF orientation is
honored. Supported formats are those GDI+ decodes (JPEG, PNG, BMP, GIF, TIFF);
other formats are reported once in the log and the monitor keeps Windows' own
wallpaper.

Rendering uses Direct3D 11, Direct2D and DirectComposition, which works on
both desktop layouts. Without a usable GPU driver, Direct3D's software renderer
(WARP) is used. If rendering fails on a monitor, that monitor shows the regular
Windows wallpaper and rendering is retried with increasing intervals. With
**Subpixel motion** off, the image moves in whole-pixel steps; this also turns
off perspective and HDR color management.

Automatic frame rate follows the highest detected display refresh rate, capped
at 240 Hz. This is a requested rate, not a guarantee of FPS or hardware frame
synchronization; Windows' compositor controls presentation. A high-resolution
waitable timer is used without changing the global timer resolution. When motion
settles, identical frames are not redrawn and pointer polling drops to at most
30 Hz, or 10 Hz while every monitor is paused. Memory usage grows with the total
display resolution.

The fullscreen pause checks the foreground application every 250 ms and pauses
only the monitors it completely covers. It does not inspect every background
window. Desktop attachment supports the classic WorkerW layout and the layered
Windows 11 layout. This undocumented Explorer mechanism can change in Windows
updates; unrecognized layouts are left untouched.

## Limitations

- Intended for Windows 10 and Windows 11.
- Images use aspect-preserving **Fill** cropping with extra space for movement.
  Fit, Center, Tile, and continuous Span are not implemented.
- Transitions between images are not included.
- Perspective and HDR color management are designed for a Direct3D 11-capable
  GPU; on the software renderer they work but cost noticeably more CPU.
- Solid-color desktops without an image remain unchanged.
- Do not combine this mod with another animated-wallpaper application.
*/
// ==/WindhawkModReadme==

