enum class GifPlaybackMode {
    Always,
    Hover,
    Pressed,
    Stopped,
};

enum class GifAnimationStatus {
    Unknown,
    NotAnimated,
    Playing,
    Stopped,
    SystemAnimationsDisabled,
};

enum class IconState : size_t {
    Normal,
    Hover,
    Pressed,
    Activated,
    Count,
};

constexpr size_t kIconStateCount = static_cast<size_t>(IconState::Count);

