using GetWindowBand_t = BOOL(WINAPI*)(HWND hWnd, PDWORD pdwBand);
GetWindowBand_t pGetWindowBand;

// Detects the virtual desktop switcher flyout shown when hovering over the Task
// View button on the taskbar.
bool IsVirtualDesktopSwitcherHoverWindow(HWND hWnd) {
    // Must be in the current process (explorer.exe).
    DWORD dwProcessId = 0;
    DWORD dwThreadId = GetWindowThreadProcessId(hWnd, &dwProcessId);
    if (!dwThreadId || dwProcessId != GetCurrentProcessId()) {
        return false;
    }

    WCHAR className[64];
    if (!GetClassName(hWnd, className, ARRAYSIZE(className)) ||
        _wcsicmp(className, L"XamlExplorerHostIslandWindow") != 0) {
        return false;
    }

    // The Alt+Tab window uses band ZBID_SYSTEM_TOOLS, the Win+Tab window uses
    // band ZBID_IMMERSIVE_APPCHROME, the virtual desktop switcher uses band
    // ZBID_IMMERSIVE_EDGY.
    constexpr DWORD ZBID_IMMERSIVE_EDGY = 7;

    DWORD band = 0;
    if (!pGetWindowBand || !pGetWindowBand(hWnd, &band) ||
        band != ZBID_IMMERSIVE_EDGY) {
        return false;
    }

    // Check thread description for "MultitaskingView".
    HANDLE hThread =
        OpenThread(THREAD_QUERY_LIMITED_INFORMATION, FALSE, dwThreadId);
    if (!hThread) {
        return false;
    }

    bool isMultitaskingView = false;
    PWSTR description = nullptr;
    if (SUCCEEDED(GetThreadDescription(hThread, &description)) && description) {
        isMultitaskingView = wcscmp(description, L"MultitaskingView") == 0;
        LocalFree(description);
    }

    CloseHandle(hThread);
    return isMultitaskingView;
}

using ShowWindow_t = decltype(&ShowWindow);
ShowWindow_t ShowWindow_Original;
BOOL WINAPI ShowWindow_Hook(HWND hWnd, int nCmdShow) {
    if (g_settings.noVirtualDesktopSwitcherHover && nCmdShow != SW_HIDE &&
        IsVirtualDesktopSwitcherHoverWindow(hWnd)) {
        Wh_Log(L"> %08X - %d (virtual desktop switcher)",
               (DWORD)(DWORD_PTR)hWnd, nCmdShow);
        return TRUE;
    }

    if (g_showTaskListButtonHoverFlyoutThreadId == GetCurrentThreadId() &&
        !g_inTransitionToFlyoutVisibleStickyState) {
        Wh_Log(L"> %08X - %d", (DWORD)(DWORD_PTR)hWnd, nCmdShow);

        if (nCmdShow != SW_HIDE) {
            if (hWnd != g_hoverFlyoutWindow.hWnd) {
                g_hoverFlyoutWindow = {.hWnd = hWnd};
            }

            g_hoverFlyoutWindow.pendingCmdShow = nCmdShow;

            return TRUE;
        } else if (hWnd == g_hoverFlyoutWindow.hWnd) {
            g_hoverFlyoutWindow.pendingCmdShow = SW_HIDE;
        }
    }

    return ShowWindow_Original(hWnd, nCmdShow);
}

using EnableWindow_t = decltype(&EnableWindow);
EnableWindow_t EnableWindow_Original;
BOOL WINAPI EnableWindow_Hook(HWND hWnd, BOOL bEnable) {
    if (g_showTaskListButtonHoverFlyoutThreadId == GetCurrentThreadId() &&
        !g_inTransitionToFlyoutVisibleStickyState) {
        Wh_Log(L"> %08X - %d", (DWORD)(DWORD_PTR)hWnd, bEnable);

        if (bEnable) {
            if (hWnd != g_hoverFlyoutWindow.hWnd) {
                g_hoverFlyoutWindow = {.hWnd = hWnd};
            }

            g_hoverFlyoutWindow.pendingEnable = bEnable;

            return TRUE;
        } else if (hWnd == g_hoverFlyoutWindow.hWnd) {
            g_hoverFlyoutWindow.pendingEnable = FALSE;
        }
    }

    return EnableWindow_Original(hWnd, bEnable);
}

using HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_t =
    void(WINAPI*)(void* pThis, void* param1);
HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_t
    HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_Original;
void WINAPI
HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_Hook(void* pThis,
                                                           void* param1) {
    Wh_Log(L">");

    if (g_settings.mode != Mode::disabled &&
        g_settings.mode != Mode::listOnClick) {
        HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_Original(pThis,
                                                                       param1);
        return;
    }

    g_inTransitionToFlyoutVisibleStickyState = true;

    HoverFlyoutModel_TransitionToFlyoutVisibleStickyState_Original(pThis,
                                                                   param1);

    g_inTransitionToFlyoutVisibleStickyState = false;

    HWND hFlyoutWnd = g_hoverFlyoutWindow.hWnd;
    if (hFlyoutWnd) {
        if (int pendingCmdShow = g_hoverFlyoutWindow.pendingCmdShow) {
            ShowWindow_Original(hFlyoutWnd, pendingCmdShow);
        }

        if (BOOL pendingEnable = g_hoverFlyoutWindow.pendingEnable) {
            EnableWindow_Original(hFlyoutWnd, pendingEnable);
        }
    }

    g_hoverFlyoutWindow = {};
}

