static bool StartsWithRtl(const std::wstring& text) {
    for (wchar_t c : text) {
        if (c >= 0x0590 && c <= 0x08FF) return true;
        if (c >= 0xFB1D && c <= 0xFDFF) return true;
        if (c >= 0xFE70 && c <= 0xFEFF) return true;
        if (iswalpha(c)) return false;
    }
    return false;
}
