    INT x = 0, y = 0;
    INT width = 18, height = 18;
    if(!g_themeCache.CreateDIB(g_themeCache.modulelocationbutton[stateIndex], width, height))
        return FALSE;
    
    Microsoft::WRL::ComPtr<ID2D1DCRenderTarget> pRenderTarget;
    RECT rc = { x, y, width, height};
