// Normalizes a path: flips slashes, trims trailing slashes, lowercases.
std::wstring NormalizeRule(std::wstring path) 
{
    if (path.empty()) return path;

    // 1. Normalize slashes
    for (auto& ch : path)
        if (ch == L'/') 
            ch = L'\\';

    // 2. Trim trailing slashes (now guaranteed to be backslashes)
    while (!path.empty() && path.back() == L'\\')
        path.pop_back();
    
    if (path.empty()) 
        return path;

    // 3. Lowercase
    LCMapStringEx(LOCALE_NAME_USER_DEFAULT, LCMAP_LOWERCASE, 
                  path.c_str(), (INT)path.length(), &path[0], (INT)path.length(), 
                  nullptr, nullptr, 0);

    return path;
}

struct CurrentProcessInfo {
    std::wstring fullPath;   // (e.g. c:\windows\system32\notepad.exe)
    std::wstring fileName;   // (e.g. notepad.exe)
    std::wstring directory;  // (e.g. c:\windows\system32)
};

CurrentProcessInfo GetCurrentProcessInfo() 
{
    WCHAR modulePath[MAX_PATH];
    GetModuleFileNameW(nullptr, modulePath, MAX_PATH);

    CurrentProcessInfo info;
    info.fullPath = modulePath;

    // FIX 1: Strip Windows long path prefix if present, otherwise string matches fail
    if (info.fullPath.find(L"\\\\?\\") == 0) {
        info.fullPath.erase(0, 4);
    }

    // FIX 2: Process paths can occasionally contain forward slashes depending on launch method.
    for (auto& ch : info.fullPath) {
        if (ch == L'/') ch = L'\\';
    }

    // Lowercase the main string once
    LCMapStringEx(LOCALE_NAME_USER_DEFAULT, LCMAP_LOWERCASE, 
                  info.fullPath.c_str(), (INT)info.fullPath.length(), 
                  &info.fullPath[0], (INT)info.fullPath.length(), 
                  nullptr, nullptr, 0);

    // Extract substrings cleanly 
    size_t pos = info.fullPath.find_last_of(L'\\');
    if (pos != std::wstring::npos) {
        info.fileName = info.fullPath.substr(pos + 1);
        info.directory = info.fullPath.substr(0, pos);
    } else {
        info.fileName = info.fullPath;
        info.directory = L""; 
    }

    return info;
}

bool MatchesProcessRule(const std::wstring& rawEntry, const CurrentProcessInfo& proc) 
{
    std::wstring entry = NormalizeRule(rawEntry);
    if (entry.empty()) return false;

    // Exact full path or directory match
    if (entry == proc.fullPath || entry == proc.directory)
        return true;

    // Bare name, e.g. "mspaint.exe"
    if (entry.find(L'\\') == std::wstring::npos) {
        return entry == proc.fileName;
    }

    // FIX 3: Subfolder match. Use .find() == 0 for a bulletproof "starts_with" check.
    std::wstring prefix = entry + L"\\";
    if (proc.fullPath.find(prefix) == 0)
        return true;

    return false;
}

VOID LoadWindowProcessRules()
{
    CurrentProcessInfo currProc = GetCurrentProcessInfo();

    for (INT i = 0;; i++) 
    {
        auto program = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].target", i));
        
        if (!*program)
            break; 

        if (MatchesProcessRule(program.get(), currProc))
        {
            g_settings.FillBg = Wh_GetIntSetting(L"RuledPrograms[%d].RenderingMod.ThemeBackground", i);
            
            BOOL globalSetting_CustomTheme = Wh_GetIntSetting(L"RenderingMod.ThemeBackground");
            if (!globalSetting_CustomTheme)
                GenerateTextAlphaGammaLUT();
            
            g_settings.AccentColorize = Wh_GetIntSetting(L"RuledPrograms[%d].RenderingMod.AccentColorControls", i);
            if (g_settings.AccentColorize)
                g_settings.AccentColor = GetAccentColor();
            
            BOOL globalSetting_SetSysColorAPI = Wh_GetIntSetting(L"RenderingMod.Syscolors");

            // Reset system colors to default values if the system color setting is disabled for the specific ruled process
            if (!g_settings.FillBg && globalSetting_SetSysColorAPI)
                g_DefaultSysColors = TRUE;
            
            // Hook all necessary APIs to restore system colors when SetSysColors API has been executed by the mod
            if (g_DefaultSysColors) {
                WindhawkUtils::SetFunctionHook(GetSysColor, HookedGetSysColor, &GetSysColor_orig);
                WindhawkUtils::SetFunctionHook(GetSysColorBrush, HookedGetSysColorBrush, &GetSysColorBrush_orig);               
                WindhawkUtils::SetFunctionHook(FillRect, HookedFillRect, &FillRect_orig);
                User32Hooks(g_settings.SetSystemColors);
            }   

            auto strStyle = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].BackgroundEffects.type", i));
            if (0 == wcscmp(strStyle, L"acrylicblur"))
                g_settings.BgType = g_settings.AccentBlurBehind;
            else if (0 == wcscmp(strStyle, L"acrylicsystem"))
                g_settings.BgType = g_settings.AcrylicSystemBackdrop;
            else if (0 == wcscmp(strStyle, L"mica"))
                g_settings.BgType = g_settings.Mica;
            else if (0 == wcscmp(strStyle, L"mica_tabbed"))
                g_settings.BgType = g_settings.MicaAlt;
            else 
                g_settings.BgType = g_settings.Default;

            g_settings.AccentBlurBehindClr = GetColorSetting(WindhawkUtils::StringSetting(Wh_GetStringSetting(L"RuledPrograms[%d].BackgroundEffects.AccentBlurBehind", i)));
            
            break;
        }
    }
}

VOID LoadSettings()
{
    g_settings.AccentColorize = Wh_GetIntSetting(L"RenderingMod.AccentColorControls");
    if (g_settings.AccentColorize)
       g_settings.AccentColor = GetAccentColor();

    g_settings.FillBg = Wh_GetIntSetting(L"RenderingMod.ThemeBackground");
    if (g_settings.FillBg)
        GenerateTextAlphaGammaLUT();
    
    g_settings.SetSystemColors = Wh_GetIntSetting(L"RenderingMod.Syscolors");
    // SetSysColors API available only in theme customization
    if (g_settings.SetSystemColors && g_settings.FillBg)
        ColorizeSysColors();
    
    auto strStyle = WindhawkUtils::StringSetting(Wh_GetStringSetting(L"BackgroundEffects.type"));
    if (0 == wcscmp(strStyle, L"acrylicblur"))
        g_settings.BgType = g_settings.AccentBlurBehind;
    else if (0 == wcscmp(strStyle, L"acrylicsystem"))
        g_settings.BgType = g_settings.AcrylicSystemBackdrop;
    else if (0 == wcscmp(strStyle, L"mica"))
        g_settings.BgType = g_settings.Mica;
    else if (0 == wcscmp(strStyle, L"mica_tabbed"))
        g_settings.BgType = g_settings.MicaAlt;
    else 
        g_settings.BgType = g_settings.Default;
    
    g_settings.AccentBlurBehindClr = GetColorSetting(WindhawkUtils::StringSetting(Wh_GetStringSetting(L"BackgroundEffects.AccentBlurBehind")));

    g_settings.FlyoutsEffects = Wh_GetIntSetting(L"FlyoutsEffects");
        
    LoadWindowProcessRules();
    
    ApplyHooks();
}

BOOL Wh_ModInit(VOID) 
{
    g_InsideExplorerProc = CheckExplorerProcess();
    if (g_InsideExplorerProc)
        g_explorerStylerNoBackgroundEffectAtom = AddAtom(L"WindhawkFileExplorerStylerNoBackgroundEffect");
    if (InTaskManagerProcess())
        g_InsideTaskMgrProc = TRUE;

    LoadSettings();

    HMODULE hModule = GetModuleHandle(L"win32u.dll");
    if (!hModule) 
        return FALSE;
        
    NtUserCreateWindowEx_t pNtUserCreateWindowEx = (NtUserCreateWindowEx_t)GetProcAddress(hModule, "NtUserCreateWindowEx");
    if (!pNtUserCreateWindowEx)
        return FALSE;
    
    WindhawkUtils::SetFunctionHook(pNtUserCreateWindowEx, HookedNtUserCreateWindowEx, &NtUserCreateWindowEx_Original);
    
    return TRUE;
}

VOID Wh_ModAfterInit() 
{
    #ifdef _WIN64
        const size_t OFFSET_SAME_TEB_FLAGS = 0x17EE;
    #else
        const size_t OFFSET_SAME_TEB_FLAGS = 0x0FCA;
    #endif
    BOOL isInitialThread = *(USHORT*)((BYTE*)NtCurrentTeb() + OFFSET_SAME_TEB_FLAGS) & 0x0400;
    if (!isInitialThread)
        ApplyForExistingWindows();
}

VOID Wh_ModUninit(VOID) 
{
    if (g_explorerStylerNoBackgroundEffectAtom)
        DeleteAtom(g_explorerStylerNoBackgroundEffectAtom);
     
    g_settings.Unload = TRUE;
    if (g_settings.FillBg && g_d2dFactory)
        g_d2dFactory->Release();
    
    if (g_settings.SetSystemColors)
        RevertSysColors();

    for (size_t i = 0; i < g_themeCachedDefaultSysColorBrushes.size(); i++) {
        HBRUSH& brushCustom = g_themeCachedCustomSysColorBrushes[i];
        HBRUSH& brushDefault = g_themeCachedDefaultSysColorBrushes[i];
        if (brushCustom) { 
            DeleteObject(brushCustom); 
            brushCustom = nullptr; 
        }
        if (brushDefault) { 
            DeleteObject(brushDefault); 
            brushDefault = nullptr; 
        }
    }

    ApplyForExistingWindows();
}

BOOL Wh_ModSettingsChanged(BOOL* bReload) 
{
    *bReload = TRUE;
    return TRUE;
}

// ==WindhawkMod==
// @id              tray-hover-expand
// @name            Tray hover expand
// @description     Open the hidden tray icons flyout on hover instead of clicking the chevron; optionally collapse it when the cursor leaves
// @version         1.7.1
// @author          wygodad
// @github          https://github.com/wygodad
// @include         windhawk.exe
// @compilerOptions -lole32 -loleaut32 -lshell32
// @license         MIT
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Tray hover expand

![Demo](https://i.imgur.com/qsNUNpj.png)

Opens the hidden tray icons flyout (the "Show Hidden Icons" chevron) when you
hover the cursor over it, instead of having to click. Optionally collapses it
again once the cursor leaves the opened icons.

It works through UI Automation, so it does not hook internal shell functions —
it is relatively safe and resilient across Windows builds. It runs as a tool
mod in a dedicated process and does not inject into the shell.

## How it differs from similar mods
- *Taskbar tray icons hide on hover* auto-hides the whole tray area and reveals
  it on hover.
- *Show all taskbar notification icons* forces all hidden icons to always show.
- This mod keeps the standard Windows overflow flyout and simply opens it on
  hover (and optionally closes it when you move away).

## How the chevron is detected
Only tray elements are ever considered, so no taskbar application button can be
selected. Among those, detection goes:
1. By class name, which is language-independent: the chevron is the only tray
   element whose class name is `SystemTray.NormalButton` while its AutomationId
   is `SystemTrayIcon`. Notification icons share the class but use a different
   AutomationId, and the clock, volume, network, battery and "show desktop"
   buttons share the AutomationId but use other classes.
2. By name, in case a future Windows build renames those classes. The keyword
   list covers the most common display languages and can be extended.
3. Otherwise nothing happens. The mod does not guess, because invoking an
   unidentified tray button would open whatever it happens to be.

## Notes
- Windows 11 only. The class names this mod identifies the chevron by are
  Windows 11 shell types, so on Windows 10 nothing is identified and the mod
  does nothing.
- If the chevron is not identified, the mod logs every tray candidate it saw
  (class name, AutomationId, position, name). That log is what to attach to a
  bug report.
- Updating the mod does not change settings you have already saved. If you saved
  settings before v1.7.0 and your language is missing, delete every entry under
  "Chevron name keywords" and save: an empty list restores the built-in one.
- Set "Hover delay" to a small value (e.g. 150 ms) if the flyout opens when you
  only brush past the chevron on the way to the clock.
- If auto-collapse does not work, the flyout window class name may differ on your
  build. Change it in the "Flyout window class" setting.
- Windows shows a tooltip for the chevron: "Show hidden icons" before the flyout
  opens, which can appear ahead of it, and "Hide" once it is open, which can cover
  the bottom row of icons. Enable "Hide the chevron tooltip" to suppress both.
- By default the flyout is not opened while the chevron's location is covered by
  a fullscreen app (e.g. a fullscreen video or a game), so it can't pop up over
  the content. It still opens whenever the taskbar itself is visible there, so an
  auto-hidden taskbar works as usual once revealed. Turn off "Do not activate
  over fullscreen apps" to always activate.

---

## Opis po polsku

Otwiera schowek ukrytych ikon zasobnika (strzałkę „Pokaż ukryte ikony") po
najechaniu kursorem, bez konieczności klikania. Opcjonalnie zwija go z powrotem,
gdy kursor opuści otwarte ikony.

Mod działa przez UI Automation, więc nie hookuje wewnętrznych funkcji powłoki —
jest stosunkowo bezpieczny i odporny na zmiany między kompilacjami Windows.
Działa jako „tool mod" w osobnym procesie i nie wstrzykuje się do powłoki.

### Czym różni się od podobnych modów
- *Taskbar tray icons hide on hover* automatycznie ukrywa cały obszar zasobnika
  i odsłania go po najechaniu.
- *Show all taskbar notification icons* wymusza stałe wyświetlanie wszystkich
  ukrytych ikon.
- Ten mod zachowuje standardowy schowek Windows i po prostu otwiera go po
  najechaniu (a opcjonalnie zamyka po odjechaniu kursorem).

### Jak wykrywana jest strzałka
Brane pod uwagę są wyłącznie elementy zasobnika, więc żaden przycisk aplikacji
z paska zadań nie może zostać wybrany. Wśród nich wykrywanie przebiega tak:
1. Po nazwie klasy, niezależnie od języka: strzałka jest jedynym elementem
   zasobnika o klasie `SystemTray.NormalButton` i jednocześnie AutomationId
   `SystemTrayIcon`. Ikony powiadomień mają tę samą klasę, ale inne
   AutomationId, a zegar, głośność, sieć, bateria i „pokaż pulpit" mają to samo
   AutomationId, ale inne klasy.
2. Po nazwie, na wypadek gdyby przyszła kompilacja Windows zmieniła te klasy.
   Lista słów kluczowych obejmuje najpopularniejsze języki i można ją rozszerzyć.
3. W przeciwnym razie nic się nie dzieje. Mod nie zgaduje, bo uruchomienie
   nierozpoznanego przycisku zasobnika otworzyłoby cokolwiek, czym on jest.

### Uwagi
- Tylko Windows 11. Nazwy klas, po których rozpoznawana jest strzałka, to typy
  powłoki Windows 11, więc w Windows 10 nic nie zostanie rozpoznane i mod nie
  robi nic.
- Gdy strzałka nie zostanie rozpoznana, mod zapisuje w logu wszystkich
  kandydatów z zasobnika (nazwa klasy, AutomationId, pozycja, nazwa). To ten log
  warto dołączyć do zgłoszenia błędu.
- Aktualizacja moda nie zmienia ustawień, które zostały już zapisane. Jeśli
  zapisywałeś ustawienia przed wersją 1.7.0, a brakuje Twojego języka, usuń
  wszystkie pozycje w polu „Słowa kluczowe nazwy strzałki" i zapisz: pusta lista
  przywraca wbudowaną.
- Ustaw „Opóźnienie otwierania" na niewielką wartość (np. 150 ms), jeśli schowek
  otwiera się przy samym przejeżdżaniu obok strzałki w drodze do zegara.
- Jeśli auto-zwijanie nie działa, nazwa klasy okna schowka może się różnić na
  Twojej kompilacji systemu. Zmień ją w ustawieniu „Klasa okna schowka".
- Windows pokazuje dla strzałki podpowiedź: „Pokaż ukryte ikony" przed otwarciem
  schowka, która potrafi wyprzedzić jego pojawienie się, oraz „Ukryj" po otwarciu,
  która zasłania dolny rząd ikon. Włącz „Ukryj podpowiedź strzałki", aby wyłączyć
  obie.
- Domyślnie schowek nie otwiera się, gdy miejsce strzałki jest zakryte przez
  aplikację pełnoekranową (np. film na pełnym ekranie lub grę), więc nie wyskoczy
  on na wierzchu treści. Otwiera się natomiast zawsze, gdy widoczny jest tam sam
  pasek zadań, więc automatycznie ukrywany pasek po odsłonięciu działa normalnie.
  Wyłącz „Nie aktywuj na aplikacjach pełnoekranowych", aby aktywować zawsze.
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- autoClose: true
  $name: Collapse when the cursor leaves
  $name:pl-PL: Zwijaj po odjechaniu kursorem
  $description: After the cursor leaves the opened icons (and the chevron), the flyout closes itself.
