// Access VTable function by index for undocumented COM interfaces
template <typename T>
T GetVTableFunction(void* pInterface, int index) {
  return reinterpret_cast<T>((*reinterpret_cast<void***>(pInterface))[index]);
}

bool InitializeVirtualDesktopAPI();

bool UsesHMonitorParameter() { return g_versionIIDs[g_windowsVersionIndex].usesHMonitor; }

UINT ParseModifiers(PCWSTR str) {
  std::wstring normalized;
  for (; str && *str; ++str) {
    if (!std::iswspace(*str)) {
      normalized.push_back(std::towlower(*str));
    }
  }

  if (normalized.empty()) return 0;

  UINT modifiers = 0;
  size_t tokenStart = 0;
  while (tokenStart <= normalized.size()) {
    size_t tokenEnd = normalized.find(L'+', tokenStart);
    size_t tokenLength = tokenEnd == std::wstring::npos
                             ? normalized.size() - tokenStart
                             : tokenEnd - tokenStart;
    if (tokenLength == 0) return 0;

    std::wstring token = normalized.substr(tokenStart, tokenLength);
    if (token == L"alt") {
      modifiers |= MOD_ALT;
    } else if (token == L"ctrl") {
      modifiers |= MOD_CONTROL;
    } else if (token == L"shift") {
      modifiers |= MOD_SHIFT;
    } else if (token == L"win") {
      modifiers |= MOD_WIN;
    } else {
      return 0;
    }

    if (tokenEnd == std::wstring::npos) break;
    tokenStart = tokenEnd + 1;
  }

  return modifiers;
}

std::wstring ReadTrimmedStringSetting(PCWSTR name) {
  PCWSTR rawValue = Wh_GetStringSetting(name);
  std::wstring value = rawValue ? rawValue : L"";
  if (rawValue) Wh_FreeStringSetting(rawValue);

  size_t first = 0;
  while (first < value.size() && std::iswspace(value[first])) ++first;

  size_t last = value.size();
  while (last > first && std::iswspace(value[last - 1])) --last;

  return value.substr(first, last - first);
}

template <typename T>
T LookupTable(PCWSTR str, const std::pair<PCWSTR, T>* table, size_t count, T defaultVal) {
  for (size_t i = 0; i < count; ++i) {
    if (wcscmp(str, table[i].first) == 0) return table[i].second;
  }
  return defaultVal;
}


int ParseWindowsVersion(PCWSTR str) {
  static const std::pair<PCWSTR, int> kVersionMap[] = {
      {L"win10_old", 0}, {L"win10_20348", 1}, {L"win11_22000", 2}, {L"win11_22621", 3}, {L"win11_26100", 4}};
  return LookupTable(str, kVersionMap, _countof(kVersionMap), 4);
}
UINT ReadModifierSetting(PCWSTR name, UINT defaultVal) {
  std::wstring value = ReadTrimmedStringSetting(name);
  UINT result = ParseModifiers(value.c_str());
  Wh_Log(L"ReadModifierSetting: name=%s, value=\"%s\", parsed=0x%X, default=0x%X, using=0x%X",
         name, value.c_str(), result, defaultVal, result ? result : defaultVal);
  return result ? result : defaultVal;
}
// Parse a configured hotkey key. Named keys are case-insensitive; all
// other supported values must be exactly one character.
UINT ParseHotkeyKey(PCWSTR str) {
  if (!str || !str[0]) return 0;

  static const std::pair<PCWSTR, UINT> kNamedKeys[] = {
      {L"Tab", VK_TAB},
      {L"Space", VK_SPACE},
      {L"Enter", VK_RETURN},
  };
  for (const auto& [name, key] : kNamedKeys) {
    if (_wcsicmp(str, name) == 0) return key;
  }

  // Reject unknown multi-character values instead of silently using str[0].
  if (str[1] != L'\0') return 0;

  wchar_t c = str[0];

  // Letters A-Z (and a-z)
  if (c >= L'A' && c <= L'Z') return c;
  if (c >= L'a' && c <= L'z') return c - L'a' + L'A';

  // Numbers 0-9
  if (c >= L'0' && c <= L'9') return c;

  // Number-row symbols are aliases for their underlying physical keys. Shift
  // itself is controlled by the configured modifier setting.
  if (c == L'!') return '1';
  if (c == L'@') return '2';
  if (c == L'#') return '3';
  if (c == L'$') return '4';
  if (c == L'%') return '5';
  if (c == L'^') return '6';
  if (c == L'&') return '7';
  if (c == L'*') return '8';
  if (c == L'(') return '9';
  if (c == L')') return '0';

  // Other common special characters
  if (c == L'`' || c == L'~') return VK_OEM_3;      // Grave/tilde key
  if (c == L'-' || c == L'_') return VK_OEM_MINUS;  // Minus/underscore
  if (c == L'=' || c == L'+') return VK_OEM_PLUS;   // Equals/plus
  if (c == L'[' || c == L'{') return VK_OEM_4;      // Left bracket
  if (c == L']' || c == L'}') return VK_OEM_6;      // Right bracket
  if (c == L'\\' || c == L'|') return VK_OEM_5;     // Backslash/pipe
  if (c == L';' || c == L':') return VK_OEM_1;      // Semicolon/colon
  if (c == L'\'' || c == L'"') return VK_OEM_7;     // Quote
  if (c == L',' || c == L'<') return VK_OEM_COMMA;  // Comma
  if (c == L'.' || c == L'>') return VK_OEM_PERIOD; // Period
  if (c == L'/' || c == L'?') return VK_OEM_2;      // Slash
  if (c == L' ') return VK_SPACE;

  return 0;
}

UINT ReadHotkeySetting(PCWSTR name) {
  std::wstring value = ReadTrimmedStringSetting(name);

  if (value.empty()) {
    Wh_Log(L"ReadHotkeySetting: %s is blank; hotkey disabled", name);
    return 0;
  }

  UINT key = ParseHotkeyKey(value.c_str());
  if (!key) {
    Wh_Log(L"ReadHotkeySetting: %s has invalid value \"%s\"; hotkey disabled", name, value.c_str());
  }
  return key;
}

void LoadSettings() {
  // Windows version
  PCWSTR version = Wh_GetStringSetting(L"WindowsVersion");
  g_windowsVersionIndex = ParseWindowsVersion(version);
  Wh_FreeStringSetting(version);

  // Modifier keys
  g_moveModifiers = ReadModifierSetting(L"MoveWindowModifier", MOD_ALT | MOD_SHIFT);
  g_switchModifiers = ReadModifierSetting(L"SwitchDesktopModifier", MOD_ALT);
  g_utilityModifiers = ReadModifierSetting(L"UtilityModifier", MOD_ALT);

  Wh_Log(L"LoadSettings: moveModifiers=0x%X, switchModifiers=0x%X, utilityModifiers=0x%X",
         g_moveModifiers, g_switchModifiers, g_utilityModifiers);

  g_followMovedWindow = Wh_GetIntSetting(L"FollowMovedWindow") != 0;
  g_maxDesktops = Wh_GetIntSetting(L"MaxDesktops");
  if (g_maxDesktops < 1 || g_maxDesktops > 9) g_maxDesktops = 9;

  // Enable/disable toggles
  g_enableSwitchDesktop = Wh_GetIntSetting(L"EnableSwitchDesktop") != 0;
  g_enableMoveWindow = Wh_GetIntSetting(L"EnableMoveWindow") != 0;
  g_enablePrevNextDesktop = Wh_GetIntSetting(L"EnablePrevNextDesktop") != 0;
  g_enablePinWindow = Wh_GetIntSetting(L"EnablePinWindow") != 0;
  // A blank individual key disables that hotkey without disabling the whole group.
  g_prevDesktopKey = ReadHotkeySetting(L"PrevDesktopKey");
  g_nextDesktopKey = ReadHotkeySetting(L"NextDesktopKey");
  g_lastDesktopKey = ReadHotkeySetting(L"LastDesktopKey");
  g_pinKey = ReadHotkeySetting(L"PinKey");
}

//=============================================================================
// Virtual Desktop API Initialization
//=============================================================================

bool InitializeVirtualDesktopAPIOnce() {
  HRESULT hr = CoCreateInstance(CLSID_ImmersiveShell, nullptr, CLSCTX_LOCAL_SERVER, IID_IServiceProvider,
                                (void**)&g_pServiceProvider);
  if (FAILED(hr) || !g_pServiceProvider) {
    Wh_Log(L"Failed to create ImmersiveShell: 0x%08X", hr);
    return false;
  }

  hr = g_pServiceProvider->QueryService(CLSID_VirtualDesktopManagerInternal,
                                        g_versionIIDs[g_windowsVersionIndex].managerInternal,
                                        (void**)&g_pDesktopManagerInternal);
  if (FAILED(hr) || !g_pDesktopManagerInternal) {
    Wh_Log(L"Failed to get VirtualDesktopManagerInternal: 0x%08X", hr);
    SAFE_RELEASE(g_pServiceProvider);
    return false;
  }

  hr = g_pServiceProvider->QueryService(IID_IApplicationViewCollection, IID_IApplicationViewCollection,
                                        (void**)&g_pViewCollection);
  if (FAILED(hr) || !g_pViewCollection) {
    Wh_Log(L"Failed to get ApplicationViewCollection: 0x%08X", hr);
    SAFE_RELEASE(g_pDesktopManagerInternal);
    SAFE_RELEASE(g_pServiceProvider);
    return false;
  }

  hr = CoCreateInstance(CLSID_VirtualDesktopManager, nullptr, CLSCTX_INPROC_SERVER, IID_IVirtualDesktopManager,
                        (void**)&g_pDesktopManager);
  if (FAILED(hr) || !g_pDesktopManager) {
    Wh_Log(L"Failed to create VirtualDesktopManager: 0x%08X", hr);
    SAFE_RELEASE(g_pViewCollection);
    SAFE_RELEASE(g_pDesktopManagerInternal);
    SAFE_RELEASE(g_pServiceProvider);
    return false;
  }

  // PinnedApps is optional - don't fail if unavailable
  hr = g_pServiceProvider->QueryService(CLSID_VirtualDesktopPinnedApps, IID_IVirtualDesktopPinnedApps,
                                        (void**)&g_pPinnedApps);
  if (FAILED(hr)) {
    Wh_Log(L"PinnedApps service not available (pin feature disabled): 0x%08X", hr);
    g_pPinnedApps = nullptr;
  }

  return true;
}

void CleanupVirtualDesktopAPI();
bool ReinitializeVirtualDesktopAPI();

bool InitializeVirtualDesktopAPI() {
  if (g_bInitialized) return true;

  if (InitializeVirtualDesktopAPIOnce()) {
    g_bInitialized = true;
    return true;
  }
  return false;
}

bool ReinitializeVirtualDesktopAPI() {
  CleanupVirtualDesktopAPI();
  return InitializeVirtualDesktopAPI();
}

void CleanupVirtualDesktopAPI() {
  // Check if Explorer is still running - if not, skip Release calls to avoid hangs
  HWND hShell = GetShellWindow();
  if (!hShell || !IsWindow(hShell)) {
    Wh_Log(L"Explorer not available, skipping COM cleanup to avoid hang");
    g_pPinnedApps = nullptr;
    g_pDesktopManager = nullptr;
    g_pViewCollection = nullptr;
    g_pDesktopManagerInternal = nullptr;
    g_pServiceProvider = nullptr;
    g_bInitialized = false;
    return;
  }

  SAFE_RELEASE(g_pPinnedApps);
  SAFE_RELEASE(g_pDesktopManager);
  SAFE_RELEASE(g_pViewCollection);
  SAFE_RELEASE(g_pDesktopManagerInternal);
  SAFE_RELEASE(g_pServiceProvider);
  g_bInitialized = false;
}

// Unified VTable call for methods with optional HMONITOR parameter (varies by Windows version)
template <typename TResult>
HRESULT CallManagerInternal(int vtableIndex, TResult* outResult) {
  if (UsesHMonitorParameter()) {
    auto pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, HMONITOR, TResult*)>(g_pDesktopManagerInternal,
                                                                                         vtableIndex);
    HRESULT hr = pfn(g_pDesktopManagerInternal, nullptr, outResult);
    if (FAILED(hr) && ReinitializeVirtualDesktopAPI()) {
      // in case explorer.exe restarted
      pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, HMONITOR, TResult*)>(g_pDesktopManagerInternal,
                                                                                      vtableIndex);
      hr = pfn(g_pDesktopManagerInternal, nullptr, outResult);
    }
    return hr;
  } else {
    auto pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, TResult*)>(g_pDesktopManagerInternal, vtableIndex);
    HRESULT hr = pfn(g_pDesktopManagerInternal, outResult);
    if (FAILED(hr) && ReinitializeVirtualDesktopAPI()) {
      pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, TResult*)>(g_pDesktopManagerInternal, vtableIndex);
      hr = pfn(g_pDesktopManagerInternal, outResult);
    }
    return hr;
  }
}

template <typename TArg>
HRESULT CallManagerInternalWithArg(int vtableIndex, TArg arg) {
  if (UsesHMonitorParameter()) {
    auto pfn =
        GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, HMONITOR, TArg)>(g_pDesktopManagerInternal, vtableIndex);
    HRESULT hr = pfn(g_pDesktopManagerInternal, nullptr, arg);
    if (FAILED(hr) && ReinitializeVirtualDesktopAPI()) {
      pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, HMONITOR, TArg)>(g_pDesktopManagerInternal, vtableIndex);
      hr = pfn(g_pDesktopManagerInternal, nullptr, arg);
    }
    return hr;
  } else {
    auto pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, TArg)>(g_pDesktopManagerInternal, vtableIndex);
    HRESULT hr = pfn(g_pDesktopManagerInternal, arg);
    if (FAILED(hr) && ReinitializeVirtualDesktopAPI()) {
      pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, TArg)>(g_pDesktopManagerInternal, vtableIndex);
      hr = pfn(g_pDesktopManagerInternal, arg);
    }
    return hr;
  }
}

//=============================================================================
// Virtual Desktop Operations
// IVirtualDesktopManagerInternal VTable indices (may vary slightly by version):
//   4 = MoveViewToDesktop, 6 = GetCurrentDesktop, 7 = GetDesktops, 9 = SwitchDesktop
//=============================================================================

static const int VTABLE_MOVE_VIEW_TO_DESKTOP = 4;
static const int VTABLE_GET_CURRENT_DESKTOP = 6;
static const int VTABLE_GET_DESKTOPS = 7;
static const int VTABLE_SWITCH_DESKTOP = 9;

IObjectArray* GetDesktops() {
  if (!g_pDesktopManagerInternal) return nullptr;
  IObjectArray* desktops = nullptr;
  HRESULT hr = CallManagerInternal(VTABLE_GET_DESKTOPS, &desktops);
  if (FAILED(hr)) Wh_Log(L"GetDesktops failed: 0x%08X", hr);
  return desktops;
}

IVirtualDesktop* GetDesktopByIndex(int index) {
  IObjectArray* desktops = GetDesktops();
  if (!desktops) return nullptr;

  UINT count = 0;
  desktops->GetCount(&count);

  IVirtualDesktop* desktop = nullptr;
  if (index >= 0 && (UINT)index < count) {
    desktops->GetAt(index, g_versionIIDs[g_windowsVersionIndex].virtualDesktop, (void**)&desktop);
  }
  desktops->Release();
  return desktop;
}

bool GetCurrentDesktopId(GUID* outGuid) {
  if (!g_pDesktopManagerInternal) return false;

  IVirtualDesktop* desktop = nullptr;
  HRESULT hr = CallManagerInternal(VTABLE_GET_CURRENT_DESKTOP, &desktop);
  if (FAILED(hr) || !desktop) {
    Wh_Log(L"GetCurrentDesktop failed: 0x%08X", hr);
    return false;
  }

  hr = desktop->GetId(outGuid);
  desktop->Release();
  return SUCCEEDED(hr);
}

int GetDesktopIndexById(const GUID& desktopId) {
  IObjectArray* desktops = GetDesktops();
  if (!desktops) return -1;

  UINT count = 0;
  desktops->GetCount(&count);

  for (UINT i = 0; i < count; ++i) {
    IVirtualDesktop* desktop = nullptr;
    if (SUCCEEDED(desktops->GetAt(i, g_versionIIDs[g_windowsVersionIndex].virtualDesktop, (void**)&desktop)) &&
        desktop) {
      GUID guid;
      bool match = SUCCEEDED(desktop->GetId(&guid)) && IsEqualGUID(guid, desktopId);
      desktop->Release();
      if (match) {
        desktops->Release();
        return i;
      }
    }
  }
  desktops->Release();
  return -1;
}

bool SwitchToDesktop(IVirtualDesktop* desktop) {
  if (!g_pDesktopManagerInternal || !desktop) return false;

  HRESULT hr = CallManagerInternalWithArg(VTABLE_SWITCH_DESKTOP, desktop);
  if (FAILED(hr)) Wh_Log(L"SwitchToDesktop failed: 0x%08X", hr);
  return SUCCEEDED(hr);
}

bool MoveViewToDesktop(IApplicationView* view, IVirtualDesktop* desktop) {
  if (!g_pDesktopManagerInternal || !view || !desktop) return false;

  auto pfn = GetVTableFunction<HRESULT(STDMETHODCALLTYPE*)(void*, IApplicationView*, IVirtualDesktop*)>(
      g_pDesktopManagerInternal, VTABLE_MOVE_VIEW_TO_DESKTOP);
  HRESULT hr = pfn(g_pDesktopManagerInternal, view, desktop);

  if (FAILED(hr)) Wh_Log(L"MoveViewToDesktop failed: 0x%08X", hr);
  return SUCCEEDED(hr);
}

// Check if a window is eligible for virtual desktop operations
bool IsEligibleWindow(HWND hwnd) {
  if (!hwnd || !IsWindow(hwnd)) return false;
  LONG_PTR style = GetWindowLongPtr(hwnd, GWL_STYLE);
  if (!(style & WS_VISIBLE) || (style & WS_CHILD)) return false;
  if (GetWindowLongPtr(hwnd, GWL_EXSTYLE) & WS_EX_TOOLWINDOW) return false;
  return GetAncestor(hwnd, GA_ROOTOWNER) == hwnd;
}

bool TryGetWindowDesktopId(HWND hwnd, GUID* outDesktopId) {
  if (!outDesktopId || !hwnd || !g_pDesktopManager) return false;
  return SUCCEEDED(g_pDesktopManager->GetWindowDesktopId(hwnd, outDesktopId));
}

bool IsWindowPinned(HWND hwnd) {
  if (!hwnd || !g_pViewCollection || !g_pPinnedApps) return false;

  IApplicationView* view = nullptr;
  if (FAILED(g_pViewCollection->GetViewForHwnd(hwnd, &view)) || !view) {
    return false;
  }

  BOOL isPinned = FALSE;
  HRESULT hr = g_pPinnedApps->IsViewPinned(view, &isPinned);
  view->Release();
  return SUCCEEDED(hr) && isPinned;
}

// Find the topmost window on a specific virtual desktop
HWND FindWindowOnDesktop(const GUID& desktopId, HWND excludeWindow = nullptr) {
  struct EnumContext {
    GUID targetId;
    HWND excludeHwnd;
    HWND resultHwnd;
  } context = {desktopId, excludeWindow, nullptr};

  EnumWindows(
      [](HWND hwnd, LPARAM lParam) WINAPI -> BOOL {
        auto* ctx = reinterpret_cast<EnumContext*>(lParam);
        if (hwnd == ctx->excludeHwnd || !IsEligibleWindow(hwnd)) return TRUE;

        GUID windowDesktopId;
        if (g_pDesktopManager && SUCCEEDED(g_pDesktopManager->GetWindowDesktopId(hwnd, &windowDesktopId))) {
          if (IsEqualGUID(windowDesktopId, ctx->targetId)) {
            ctx->resultHwnd = hwnd;
            return FALSE;
          }
        }
        return TRUE;
      },
      reinterpret_cast<LPARAM>(&context));

  return context.resultHwnd;
}

void FocusWindow(HWND hwnd) {
  if (!hwnd) return;
  if (IsIconic(hwnd)) ShowWindow(hwnd, SW_RESTORE);
  SetForegroundWindow(hwnd);
}

// Raise a normal window to the front of the non-topmost Z-order group without
// activating it. HWND_TOP keeps non-topmost windows below the topmost group, so
// no temporary always-on-top state is needed.
void RaiseWindowToFrontOfNormalBand(HWND hwnd) {
  if (!hwnd || !IsWindow(hwnd)) return;

  // Don't interfere with windows that are intentionally always-on-top.
  if (GetWindowLongPtrW(hwnd, GWL_EXSTYLE) & WS_EX_TOPMOST) return;

  if (!SetWindowPos(hwnd, HWND_TOP, 0, 0, 0, 0,
                    SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)) {
    Wh_Log(L"Z-order repair failed: %lu", GetLastError());
  }
}
void UpdateCurrentDesktopTracking(const GUID& desktopId, bool updatePreviousDesktop) {
  if (g_hasCurrentDesktop && !IsEqualGUID(g_currentDesktopId, desktopId)) {
    if (updatePreviousDesktop) {
      g_previousDesktopId = g_currentDesktopId;
      g_hasPreviousDesktop = true;
    }
  }

  g_currentDesktopId = desktopId;
  g_hasCurrentDesktop = true;
}

bool SyncCurrentDesktopTracking(bool updatePreviousDesktop) {
  GUID currentDesktopId = {};
  if (!GetCurrentDesktopId(&currentDesktopId)) return false;

  UpdateCurrentDesktopTracking(currentDesktopId, updatePreviousDesktop);
  return true;
}

void HandleForegroundWindowChanged(HWND hwnd) {
  if (!InitializeVirtualDesktopAPI()) return;

  bool eligibleWindow = hwnd && IsEligibleWindow(hwnd);
  GUID currentDesktopId = {};
  bool hasCurrentDesktopId = GetCurrentDesktopId(&currentDesktopId);
  GUID windowDesktopId = {};
  bool hasWindowDesktopId = eligibleWindow && TryGetWindowDesktopId(hwnd, &windowDesktopId);

  // The virtual desktop manager is authoritative. During a desktop transition,
  // the foreground event can briefly refer to a window from the old desktop.
  if (hasCurrentDesktopId) {
    UpdateCurrentDesktopTracking(currentDesktopId, true);

    // Only query pinned state when the foreground window is otherwise a valid
    // focus-map candidate. This avoids two unnecessary COM calls on most
    // foreground changes.
    if (eligibleWindow && hasWindowDesktopId &&
        IsEqualGUID(windowDesktopId, currentDesktopId) && !IsWindowPinned(hwnd)) {
      g_desktopFocusMap[currentDesktopId] = hwnd;
    }
    return;
  }

  // Fall back to the foreground window only when querying the current desktop
  // itself failed. This keeps tracking useful during a transient COM failure.
  if (hasWindowDesktopId && !IsWindowPinned(hwnd)) {
    UpdateCurrentDesktopTracking(windowDesktopId, true);
    g_desktopFocusMap[windowDesktopId] = hwnd;
  }
}

void CALLBACK ForegroundWinEventProc(HWINEVENTHOOK hWinEventHook,
                                     DWORD event,
                                     HWND hwnd,
                                     LONG idObject,
                                     LONG idChild,
                                     DWORD dwEventThread,
                                     DWORD dwmsEventTime) {
  if (event != EVENT_SYSTEM_FOREGROUND || idObject != OBJID_WINDOW || idChild != CHILDID_SELF) return;

  HandleForegroundWindowChanged(hwnd);
}

bool GoToDesktopNum(int desktopNum, HWND preferredFocusHwnd = nullptr) {
  if (!InitializeVirtualDesktopAPI() || desktopNum <= 0) return false;

  // Save current desktop info for "previous desktop" feature
  GUID currentDesktopId = {};
  bool hasCurrentDesktop = GetCurrentDesktopId(&currentDesktopId);
  HWND currentForeground = GetForegroundWindow();

  if (hasCurrentDesktop && currentForeground && IsEligibleWindow(currentForeground)) {
    g_desktopFocusMap[currentDesktopId] = currentForeground;
  }

  IVirtualDesktop* targetDesktop = GetDesktopByIndex(desktopNum - 1);
  if (!targetDesktop) {
    Wh_Log(L"Desktop %d not found", desktopNum);
    return false;
  }

  GUID targetDesktopId = {};
  bool hasTargetId = SUCCEEDED(targetDesktop->GetId(&targetDesktopId));

  // Already on target desktop
  if (hasTargetId && hasCurrentDesktop && IsEqualGUID(currentDesktopId, targetDesktopId)) {
    targetDesktop->Release();
    return true;
  }

  // Find window to focus on target desktop
  HWND windowToFocus = nullptr;
  if (hasTargetId) {
    // If requested, prefer focusing a specific window (e.g. the one that was just moved).
    if (preferredFocusHwnd && IsEligibleWindow(preferredFocusHwnd) && g_pDesktopManager) {
      GUID preferredDesktopId;
      if (SUCCEEDED(g_pDesktopManager->GetWindowDesktopId(preferredFocusHwnd, &preferredDesktopId)) &&
          IsEqualGUID(preferredDesktopId, targetDesktopId)) {
        windowToFocus = preferredFocusHwnd;
      }
    }

    if (!windowToFocus) {
      auto it = g_desktopFocusMap.find(targetDesktopId);
      if (it != g_desktopFocusMap.end() && IsEligibleWindow(it->second)) {
        GUID windowDesktopId;
        if (g_pDesktopManager && SUCCEEDED(g_pDesktopManager->GetWindowDesktopId(it->second, &windowDesktopId))) {
          if (IsEqualGUID(windowDesktopId, targetDesktopId)) {
            windowToFocus = it->second;
          }
        }
      }
    }

    if (!windowToFocus) {
      windowToFocus = FindWindowOnDesktop(targetDesktopId, preferredFocusHwnd);
    }
  }

  bool success = SwitchToDesktop(targetDesktop);
  targetDesktop->Release();

  if (success) {
    if (windowToFocus) {
      FocusWindow(windowToFocus);
      if (hasTargetId) {
        g_desktopFocusMap[targetDesktopId] = windowToFocus;
      }
    }
    // Update previous desktop for toggle feature
    if (hasCurrentDesktop && hasTargetId && !IsEqualGUID(currentDesktopId, targetDesktopId)) {
      g_previousDesktopId = currentDesktopId;
      g_hasPreviousDesktop = true;
    }
    if (hasTargetId) {
      UpdateCurrentDesktopTracking(targetDesktopId, false);
    }
    Wh_Log(L"Switched to desktop %d", desktopNum);
  }
  return success;
}

bool SwitchToLastDesktop() {
  if (!InitializeVirtualDesktopAPI()) {
    Wh_Log(L"SwitchToLastDesktop: API not initialized");
    return false;
  }

  GUID actualCurrentId = {};
  if (!GetCurrentDesktopId(&actualCurrentId)) {
    Wh_Log(L"SwitchToLastDesktop: failed to get current desktop");
    return false;
  }

  // Repair cached state if a desktop transition happened without a clean
  // foreground event. The actual manager state is always authoritative.
  if (!g_hasCurrentDesktop) {
    g_currentDesktopId = actualCurrentId;
    g_hasCurrentDesktop = true;
  } else if (!IsEqualGUID(actualCurrentId, g_currentDesktopId)) {
    Wh_Log(L"SwitchToLastDesktop: repairing stale desktop tracking");
    g_previousDesktopId = g_currentDesktopId;
    g_hasPreviousDesktop = true;
    g_currentDesktopId = actualCurrentId;
  }

  if (!g_hasPreviousDesktop) {
    Wh_Log(L"SwitchToLastDesktop: no previous desktop is known yet");
    return false;
  }

  if (IsEqualGUID(actualCurrentId, g_previousDesktopId)) {
    Wh_Log(L"SwitchToLastDesktop: previous desktop equals the current desktop; ignoring stale target");
    return false;
  }

  int index = GetDesktopIndexById(g_previousDesktopId);
  if (index < 0) {
    g_hasPreviousDesktop = false;
    Wh_Log(L"SwitchToLastDesktop: previous desktop no longer exists");
    return false;
  }
  return GoToDesktopNum(index + 1);
}

bool SwitchToPreviousDesktop() {
  Wh_Log(L"SwitchToPreviousDesktop called");
  if (!InitializeVirtualDesktopAPI()) {
    Wh_Log(L"SwitchToPreviousDesktop: API not initialized");
    return false;
  }

  GUID currentDesktopId = {};
  if (!GetCurrentDesktopId(&currentDesktopId)) {
    Wh_Log(L"SwitchToPreviousDesktop: Failed to get current desktop ID");
    return false;
  }

  int currentIndex = GetDesktopIndexById(currentDesktopId);
  if (currentIndex < 0) {
    Wh_Log(L"SwitchToPreviousDesktop: Invalid current index");
    return false;
  }

  IObjectArray* desktops = GetDesktops();
  if (!desktops) {
    Wh_Log(L"SwitchToPreviousDesktop: Failed to get desktops");
    return false;
  }

  UINT desktopCount = 0;
  desktops->GetCount(&desktopCount);
  desktops->Release();

  Wh_Log(L"SwitchToPreviousDesktop: currentIndex=%d, desktopCount=%u, maxDesktops=%d", currentIndex,
         desktopCount, g_maxDesktops);

  int cycleCount = (int)desktopCount;
  if (cycleCount > g_maxDesktops) cycleCount = g_maxDesktops;
  if (cycleCount <= 0) return false;

  int prevIndex = (currentIndex - 1 + cycleCount) % cycleCount;
  Wh_Log(L"SwitchToPreviousDesktop: Switching to desktop %d", prevIndex + 1);
  return GoToDesktopNum(prevIndex + 1);
}

bool SwitchToNextDesktop() {
  Wh_Log(L"SwitchToNextDesktop called");
  if (!InitializeVirtualDesktopAPI()) {
    Wh_Log(L"SwitchToNextDesktop: API not initialized");
    return false;
  }

  GUID currentDesktopId = {};
  if (!GetCurrentDesktopId(&currentDesktopId)) {
    Wh_Log(L"SwitchToNextDesktop: Failed to get current desktop ID");
    return false;
  }

  int currentIndex = GetDesktopIndexById(currentDesktopId);
  if (currentIndex < 0) {
    Wh_Log(L"SwitchToNextDesktop: Invalid current index");
    return false;
  }

  IObjectArray* desktops = GetDesktops();
  if (!desktops) {
    Wh_Log(L"SwitchToNextDesktop: Failed to get desktops");
    return false;
  }

  UINT desktopCount = 0;
  desktops->GetCount(&desktopCount);
  desktops->Release();

  Wh_Log(L"SwitchToNextDesktop: currentIndex=%d, desktopCount=%u, maxDesktops=%d", currentIndex, desktopCount,
         g_maxDesktops);

  int cycleCount = (int)desktopCount;
  if (cycleCount > g_maxDesktops) cycleCount = g_maxDesktops;
  if (cycleCount <= 0) return false;

  int nextIndex = (currentIndex + 1) % cycleCount;
  Wh_Log(L"SwitchToNextDesktop: Switching to desktop %d", nextIndex + 1);
  return GoToDesktopNum(nextIndex + 1);
}

bool MoveActiveWindowToDesktopNum(int desktopNum) {
  if (!InitializeVirtualDesktopAPI()) return false;

  HWND hwnd = GetForegroundWindow();
  if (!hwnd) {
    Wh_Log(L"No active window to move");
    return false;
  }

  IVirtualDesktop* targetDesktop = GetDesktopByIndex(desktopNum - 1);
  if (!targetDesktop) {
    Wh_Log(L"Target desktop %d not found", desktopNum);
    return false;
  }

  IApplicationView* view = nullptr;
  g_pViewCollection->GetViewForHwnd(hwnd, &view);

  bool success = view && MoveViewToDesktop(view, targetDesktop);

  SAFE_RELEASE(view);
  targetDesktop->Release();

  if (success) {
    RaiseWindowToFrontOfNormalBand(hwnd);
    Wh_Log(L"Moved window to desktop %d", desktopNum);
  }
  return success;
}

bool TogglePinWindow() {
  if (!InitializeVirtualDesktopAPI() || !g_pPinnedApps) {
    Wh_Log(L"Pin feature not available");
    return false;
  }

  HWND hwnd = GetForegroundWindow();
  if (!hwnd) {
    Wh_Log(L"No active window to pin/unpin");
    return false;
  }

  IApplicationView* view = nullptr;
  if (FAILED(g_pViewCollection->GetViewForHwnd(hwnd, &view)) || !view) {
    Wh_Log(L"Failed to get view for window");
    return false;
  }

  BOOL isPinned = FALSE;
  g_pPinnedApps->IsViewPinned(view, &isPinned);

  HRESULT hr = isPinned ? g_pPinnedApps->UnpinView(view) : g_pPinnedApps->PinView(view);
  view->Release();

  if (SUCCEEDED(hr)) {
    Wh_Log(L"Window %s", isPinned ? L"unpinned" : L"pinned");
  } else {
    Wh_Log(L"Failed to %s window: 0x%08X", isPinned ? L"unpin" : L"pin", hr);
  }
  return SUCCEEDED(hr);
}


//=============================================================================
// Hotkey Thread
//=============================================================================

void RegisterHotkeys(HWND hwnd) {
  if (g_enableMoveWindow) {
    for (int i = 1; i <= g_maxDesktops; ++i) {
      BOOL ok = RegisterHotKey(hwnd, HK_MOVE_BASE + i - 1, g_moveModifiers | MOD_NOREPEAT, '0' + i);
      Wh_Log(L"RegisterHotKey MOVE_%d: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             i, g_moveModifiers, '0' + i, ok, ok ? 0 : GetLastError());
    }
  }

  if (g_enableSwitchDesktop) {
    for (int i = 1; i <= g_maxDesktops; ++i) {
      BOOL ok = RegisterHotKey(hwnd, HK_SWITCH_BASE + i - 1, g_switchModifiers | MOD_NOREPEAT, '0' + i);
      Wh_Log(L"RegisterHotKey SWITCH_%d: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             i, g_switchModifiers, '0' + i, ok, ok ? 0 : GetLastError());
    }
  }

  if (g_enablePrevNextDesktop) {
    if (g_prevDesktopKey) {
      BOOL ok = RegisterHotKey(hwnd, HK_PREV, g_utilityModifiers | MOD_NOREPEAT, g_prevDesktopKey);
      Wh_Log(L"RegisterHotKey PREV: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             g_utilityModifiers, g_prevDesktopKey, ok, ok ? 0 : GetLastError());
    } else {
      Wh_Log(L"RegisterHotKey PREV: disabled by blank key setting");
    }

    if (g_nextDesktopKey) {
      BOOL ok = RegisterHotKey(hwnd, HK_NEXT, g_utilityModifiers | MOD_NOREPEAT, g_nextDesktopKey);
      Wh_Log(L"RegisterHotKey NEXT: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             g_utilityModifiers, g_nextDesktopKey, ok, ok ? 0 : GetLastError());
    } else {
      Wh_Log(L"RegisterHotKey NEXT: disabled by blank key setting");
    }

    if (g_lastDesktopKey) {
      BOOL ok = RegisterHotKey(hwnd, HK_LAST, g_utilityModifiers | MOD_NOREPEAT, g_lastDesktopKey);
      Wh_Log(L"RegisterHotKey LAST: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             g_utilityModifiers, g_lastDesktopKey, ok, ok ? 0 : GetLastError());
    } else {
      Wh_Log(L"RegisterHotKey LAST: disabled by blank key setting");
    }
  }

  if (g_enablePinWindow) {
    if (g_pinKey) {
      BOOL ok = RegisterHotKey(hwnd, HK_PIN, g_utilityModifiers | MOD_NOREPEAT, g_pinKey);
      Wh_Log(L"RegisterHotKey PIN: modifiers=0x%X, vk=0x%X, result=%d, error=%lu",
             g_utilityModifiers, g_pinKey, ok, ok ? 0 : GetLastError());
    } else {
      Wh_Log(L"RegisterHotKey PIN: disabled by blank key setting");
    }
  }
}

void UnregisterHotkeys(HWND hwnd) {
  for (int i = 0; i < 9; ++i) {
    UnregisterHotKey(hwnd, HK_MOVE_BASE + i);
    UnregisterHotKey(hwnd, HK_SWITCH_BASE + i);
  }
  UnregisterHotKey(hwnd, HK_PREV);
  UnregisterHotKey(hwnd, HK_NEXT);
  UnregisterHotKey(hwnd, HK_LAST);
  UnregisterHotKey(hwnd, HK_PIN);
}

void HandleHotkey(UINT hotkeyId) {
  if (!g_bInitialized && !InitializeVirtualDesktopAPI()) {
    Wh_Log(L"Hotkey ignored: API not initialized");
    return;
  }

  if (hotkeyId >= HK_MOVE_BASE && hotkeyId < HK_MOVE_BASE + 9) {
    int desktopNum = hotkeyId - HK_MOVE_BASE + 1;
    HWND movedHwnd = GetForegroundWindow();
    bool moved = MoveActiveWindowToDesktopNum(desktopNum);
    if (moved && g_followMovedWindow) {
      GoToDesktopNum(desktopNum, movedHwnd);
    }
  } else if (hotkeyId >= HK_SWITCH_BASE && hotkeyId < HK_SWITCH_BASE + 9) {
    GoToDesktopNum(hotkeyId - HK_SWITCH_BASE + 1);
  } else if (hotkeyId == HK_PREV) {
    SwitchToPreviousDesktop();
  } else if (hotkeyId == HK_NEXT) {
    SwitchToNextDesktop();
  } else if (hotkeyId == HK_LAST) {
    SwitchToLastDesktop();
  } else if (hotkeyId == HK_PIN) {
    TogglePinWindow();
  }
}

LRESULT CALLBACK HotkeyWindowProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam) {
  if (message == WM_HOTKEY) {
    if (g_hotkeyThreadRunning) {
      HandleHotkey(static_cast<UINT>(wParam));
    }
    return 0;
  }

  if (message == WM_APP_SETTINGS_CHANGED) {
    if (!g_hotkeyThreadRunning) return 0;

    UnregisterHotkeys(hwnd);
    int previousWindowsVersionIndex = g_windowsVersionIndex;
    LoadSettings();
    g_desktopFocusMap.clear();

    if (previousWindowsVersionIndex != g_windowsVersionIndex) {
      CleanupVirtualDesktopAPI();
      if (InitializeVirtualDesktopAPI()) {
        SyncCurrentDesktopTracking(false);
      } else {
        Wh_Log(L"Virtual Desktop API failed to initialize after settings change; hotkeys will retry on use");
      }
    }

    RegisterHotkeys(hwnd);
    return 0;
  }

  return DefWindowProc(hwnd, message, wParam, lParam);
}

DWORD WINAPI HotkeyThreadProc(LPVOID) {
  Wh_Log(L"Hotkey thread started, thread ID: %lu", GetCurrentThreadId());

  HRESULT coHr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
  if (FAILED(coHr)) {
    Wh_Log(L"Hotkey thread COM initialization failed: 0x%08X", coHr);
    g_hotkeyThreadRunning = false;
    return 0;
  }

  HINSTANCE module = GetModuleHandle(nullptr);
  WNDCLASSEXW windowClass = {
      .cbSize = sizeof(windowClass),
      .lpfnWndProc = HotkeyWindowProc,
      .hInstance = module,
      .lpszClassName = kHotkeyWindowClassName,
  };

  if (!RegisterClassExW(&windowClass)) {
    Wh_Log(L"Failed to register hotkey window class: %lu", GetLastError());
    CoUninitialize();
    g_hotkeyThreadRunning = false;
    return 0;
  }

  HWND hwnd = CreateWindowExW(0, kHotkeyWindowClassName, nullptr, 0, 0, 0, 0, 0,
                              HWND_MESSAGE, nullptr, module, nullptr);
  if (!hwnd) {
    Wh_Log(L"Failed to create hotkey message window: %lu", GetLastError());
    UnregisterClassW(kHotkeyWindowClassName, module);
    CoUninitialize();
    g_hotkeyThreadRunning = false;
    return 0;
  }

  g_hMsgWnd = hwnd;

  HWINEVENTHOOK foregroundHook = nullptr;
  if (g_hotkeyThreadRunning) {
    foregroundHook =
        SetWinEventHook(EVENT_SYSTEM_FOREGROUND, EVENT_SYSTEM_FOREGROUND, nullptr, ForegroundWinEventProc, 0, 0,
                        WINEVENT_OUTOFCONTEXT);
    if (!foregroundHook) {
      Wh_Log(L"Failed to install foreground WinEvent hook");
    }

    if (g_settingsReloadPending.exchange(false)) {
      LoadSettings();
    }
    RegisterHotkeys(hwnd);
    Wh_Log(L"Hotkey thread ready");

    if (InitializeVirtualDesktopAPI()) {
      SyncCurrentDesktopTracking(false);
    } else {
      Wh_Log(L"Virtual Desktop API failed to initialize on startup; hotkeys will retry on use");
    }
  }

  MSG msg;
  while (g_hotkeyThreadRunning && GetMessage(&msg, nullptr, 0, 0) > 0) {
    TranslateMessage(&msg);
    DispatchMessage(&msg);
  }

  g_hMsgWnd = nullptr;
  UnregisterHotkeys(hwnd);
  if (foregroundHook) {
    UnhookWinEvent(foregroundHook);
  }
  CleanupVirtualDesktopAPI();
  DestroyWindow(hwnd);
  UnregisterClassW(kHotkeyWindowClassName, module);
  CoUninitialize();

  g_hotkeyThreadRunning = false;
  g_hasCurrentDesktop = false;
  g_currentDesktopId = {};
  Wh_Log(L"Hotkey thread stopped");
  return 0;
}

//=============================================================================
// Windhawk Tool Mod Entry Points
//=============================================================================

BOOL WhTool_ModInit() {
  Wh_Log(L"Virtual Desktop Helper mod initializing...");
  LoadSettings();
  g_settingsReloadPending = false;
  g_hotkeyThreadRunning = true;
  g_hThread = CreateThread(nullptr, 0, HotkeyThreadProc, nullptr, 0, nullptr);
  if (!g_hThread) {
    g_hotkeyThreadRunning = false;
    Wh_Log(L"Failed to create hotkey thread: %lu", GetLastError());
    return FALSE;
  }
  Wh_Log(L"Virtual Desktop Helper mod initialized successfully");
  return TRUE;
}

void WhTool_ModUninit() {
  Wh_Log(L"Virtual Desktop Helper mod uninitializing...");
  g_hotkeyThreadRunning = false;
  if (HWND hwnd = g_hMsgWnd.load()) {
    PostMessage(hwnd, WM_QUIT, 0, 0);
  }

  if (g_hThread) {
    DWORD waitResult = WaitForSingleObject(g_hThread, 5000);
    if (waitResult != WAIT_OBJECT_0) {
      Wh_Log(L"Hotkey thread cleanup did not finish before process exit (wait=%lu)", waitResult);
    }
    CloseHandle(g_hThread);
    g_hThread = nullptr;
  }
  Wh_Log(L"Virtual Desktop Helper mod uninitialized");
}

void WhTool_ModSettingsChanged() {
  Wh_Log(L"Settings changed, notifying hotkey thread...");
  if (HWND hwnd = g_hMsgWnd.load()) {
    PostMessage(hwnd, WM_APP_SETTINGS_CHANGED, 0, 0);
    return;
  }

  g_settingsReloadPending = true;
  if (HWND hwnd = g_hMsgWnd.load();
      hwnd && g_settingsReloadPending.exchange(false)) {
    PostMessage(hwnd, WM_APP_SETTINGS_CHANGED, 0, 0);
  }
}
////////////////////////////////////////////////////////////////////////////////
// Windhawk tool mod implementation for mods which don't need to inject to other
// processes or hook other functions. Context:
// https://github.com/ramensoftware/windhawk/wiki/Mods-as-tools:-Running-mods-in-a-dedicated-process
//
// The mod will load and run in a dedicated windhawk.exe process.
//
// Paste the code below as part of the mod code, and use these callbacks:
// * WhTool_ModInit
// * WhTool_ModSettingsChanged
// * WhTool_ModUninit
//
// Currently, other callbacks are not supported.

bool g_isToolModProcessLauncher;
HANDLE g_toolModProcessMutex;

void WINAPI EntryPoint_Hook() {
  Wh_Log(L">");
  ExitThread(0);
}

BOOL Wh_ModInit() {
  DWORD sessionId;
  if (ProcessIdToSessionId(GetCurrentProcessId(), &sessionId) &&
      sessionId == 0) {
    return FALSE;
  }

  bool isExcluded = false;
  bool isToolModProcess = false;
  bool isCurrentToolModProcess = false;
  int argc;
  LPWSTR* argv = CommandLineToArgvW(GetCommandLine(), &argc);
  if (!argv) {
    Wh_Log(L"CommandLineToArgvW failed");
    return FALSE;
  }

  for (int i = 1; i < argc; i++) {
    if (wcscmp(argv[i], L"-service") == 0 ||
        wcscmp(argv[i], L"-service-start") == 0 ||
        wcscmp(argv[i], L"-service-stop") == 0) {
      isExcluded = true;
      break;
    }
  }

  for (int i = 1; i < argc - 1; i++) {
    if (wcscmp(argv[i], L"-tool-mod") == 0) {
      isToolModProcess = true;
      if (wcscmp(argv[i + 1], WH_MOD_ID) == 0) {
        isCurrentToolModProcess = true;
      }
      break;
    }
  }

  LocalFree(argv);

  if (isExcluded) {
    return FALSE;
  }

  if (isCurrentToolModProcess) {
    g_toolModProcessMutex = CreateMutex(nullptr, TRUE, L"windhawk-tool-mod_" WH_MOD_ID);
    if (!g_toolModProcessMutex) {
      Wh_Log(L"CreateMutex failed");
      ExitProcess(1);
    }

    if (GetLastError() == ERROR_ALREADY_EXISTS) {
      Wh_Log(L"Tool mod already running (%s)", WH_MOD_ID);
      ExitProcess(1);
    }

    if (!WhTool_ModInit()) {
      ExitProcess(1);
    }

    IMAGE_DOS_HEADER* dosHeader = (IMAGE_DOS_HEADER*)GetModuleHandle(nullptr);
    IMAGE_NT_HEADERS* ntHeaders = (IMAGE_NT_HEADERS*)((BYTE*)dosHeader + dosHeader->e_lfanew);

    DWORD entryPointRVA = ntHeaders->OptionalHeader.AddressOfEntryPoint;
    void* entryPoint = (BYTE*)dosHeader + entryPointRVA;

    Wh_SetFunctionHook(entryPoint, (void*)EntryPoint_Hook, nullptr);
    return TRUE;
  }

  if (isToolModProcess) {
    return FALSE;
  }

  g_isToolModProcessLauncher = true;
  return TRUE;
}

void Wh_ModAfterInit() {
  if (!g_isToolModProcessLauncher) {
    return;
  }

  WCHAR currentProcessPath[MAX_PATH];
  switch (GetModuleFileName(nullptr, currentProcessPath, ARRAYSIZE(currentProcessPath))) {
    case 0:
    case ARRAYSIZE(currentProcessPath):
      Wh_Log(L"GetModuleFileName failed");
      return;
  }

  WCHAR
  commandLine[MAX_PATH + 2 + (sizeof(L" -tool-mod \"" WH_MOD_ID "\"") / sizeof(WCHAR)) - 1];
  swprintf_s(commandLine, L"\"%s\" -tool-mod \"%s\"", currentProcessPath, WH_MOD_ID);

  HMODULE kernelModule = GetModuleHandle(L"kernelbase.dll");
  if (!kernelModule) {
    kernelModule = GetModuleHandle(L"kernel32.dll");
    if (!kernelModule) {
      Wh_Log(L"No kernelbase.dll/kernel32.dll");
      return;
    }
  }

  using CreateProcessInternalW_t = BOOL(WINAPI*)(
      HANDLE hUserToken, LPCWSTR lpApplicationName, LPWSTR lpCommandLine, LPSECURITY_ATTRIBUTES lpProcessAttributes,
      LPSECURITY_ATTRIBUTES lpThreadAttributes, WINBOOL bInheritHandles, DWORD dwCreationFlags, LPVOID lpEnvironment,
      LPCWSTR lpCurrentDirectory, LPSTARTUPINFOW lpStartupInfo, LPPROCESS_INFORMATION lpProcessInformation,
      PHANDLE hRestrictedUserToken);
  CreateProcessInternalW_t pCreateProcessInternalW =
      (CreateProcessInternalW_t)GetProcAddress(kernelModule, "CreateProcessInternalW");
  if (!pCreateProcessInternalW) {
    Wh_Log(L"No CreateProcessInternalW");
    return;
  }

  STARTUPINFO si{
      .cb = sizeof(STARTUPINFO),
      .dwFlags = STARTF_FORCEOFFFEEDBACK,
  };
  PROCESS_INFORMATION pi;
  if (!pCreateProcessInternalW(nullptr, currentProcessPath, commandLine, nullptr, nullptr, FALSE, NORMAL_PRIORITY_CLASS,
                               nullptr, nullptr, &si, &pi, nullptr)) {
    Wh_Log(L"CreateProcess failed");
    return;
  }

  CloseHandle(pi.hProcess);
  CloseHandle(pi.hThread);
}

void Wh_ModSettingsChanged() {
  if (g_isToolModProcessLauncher) {
    return;
  }

  WhTool_ModSettingsChanged();
}

void Wh_ModUninit() {
  if (g_isToolModProcessLauncher) {
    return;
  }

  WhTool_ModUninit();
  ExitProcess(0);
}

// ==WindhawkMod==
// @id              virtual-desktop-hotkey-cycle
// @name            Virtual Desktop Hotkey Cycle
// @description     Makes Win+Ctrl+Left and Win+Ctrl+Right virtual desktop shortcuts loop through ends.
// @version         1.0.0
// @author          Amrsatrio
// @github          https://github.com/Amrsatrio
// @twitter         https://twitter.com/amrsatrio
// @include         explorer.exe
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Cycling Virtual Desktop Hotkey
This simple mod makes Win+Ctrl+Left and Win+Ctrl+Right cycle to the last/first desktops when the current virtual desktop is the first/last, respectively.

## Compatibility
* Version: Windows 10 1507 and up
* Architecture: x64, ARM64

Tested on Windows 11 24H2 x64 and ARM64.

## How it works

Windows normally calls `CVirtualDesktopCollection::GetAdjacentVirtualDesktop` with a reference to the **current** virtual desktop. This method is implemented in `twinui.pcshell.dll` on Windows builds 17763 (1809) and newer, and in `twinui.dll` on builds prior to 17763. When there is no desktop in the requested direction (for example, pressing **Win+Ctrl+Right** on the last desktop), the function returns `TYPE_E_OUTOFBOUNDS`, which prevents further navigation.

This mod hooks `GetAdjacentVirtualDesktop` and watches for that out-of-bounds result:

1. The original function is called first with the current desktop (`pReference`).
2. If it fails with `TYPE_E_OUTOFBOUNDS`, the mod checks how many virtual desktops exist.
3. If more than one desktop is present, the function is called again with `pReference` set to `nullptr`.

When `pReference` is `nullptr`, Windows interprets the request as:

* **Right / Down**: return the **first** virtual desktop
* **Left / Up**: return the **last** virtual desktop

By reissuing the call this way, the mod effectively turns the standard virtual desktop hotkeys into a loop, allowing seamless cycling from end to beginning and vice versa.

*/
// ==/WindhawkModReadme==

#include <windhawk_utils.h>

interface IVirtualDesktop;
interface IVirtualDesktopCollection;

using CVirtualDesktopCollection_GetCount_t = size_t (STDMETHODCALLTYPE *)(IVirtualDesktopCollection* This);

using CVirtualDesktopCollection_GetAdjacentVirtualDesktop_t = HRESULT (STDMETHODCALLTYPE *)(
    IVirtualDesktopCollection* This, IVirtualDesktop* pReference, UINT uDirection, REFIID riid, void** ppv);
CVirtualDesktopCollection_GetAdjacentVirtualDesktop_t CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Original;
HRESULT STDMETHODCALLTYPE CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Hook(
    IVirtualDesktopCollection* This, IVirtualDesktop* pReference, UINT uDirection, REFIID riid, void** ppv)
{
    HRESULT hr = CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Original(This, pReference, uDirection, riid, ppv);
    if (hr == TYPE_E_OUTOFBOUNDS && pReference)
    {
        size_t cDesktops = ((CVirtualDesktopCollection_GetCount_t)(*(void***)This)[3])(This); // GetCount()
        if (cDesktops > 1)
        {
            hr = CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Original(This, nullptr, uDirection, riid, ppv);
        }
    }

    return hr;
}

#ifdef _WIN64
#   define  SSTDCALL  L"__cdecl"
#else
#   define  SSTDCALL  L"__stdcall"
#endif

BOOL Wh_ModInit()
{
    // twinui.pcshell.dll on 17763+
    // twinui.dll on <17763

    // twinui.pcshell.dll, twinui.dll
    static const WindhawkUtils::SYMBOL_HOOK c_rgTwinUIPCShellHooks[] =
    {
        {
            {
                L"public: virtual long " SSTDCALL " CVirtualDesktopCollection::GetAdjacentVirtualDesktop(struct IVirtualDesktop *,unsigned int,struct _GUID const &,void * *)"
            },
            &CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Original,
            CVirtualDesktopCollection_GetAdjacentVirtualDesktop_Hook
        }
    };

    HMODULE hTwinUIPCShell = LoadLibraryExW(L"twinui.pcshell.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!WindhawkUtils::HookSymbols(hTwinUIPCShell, c_rgTwinUIPCShellHooks, ARRAYSIZE(c_rgTwinUIPCShellHooks)))
    {
        Wh_Log(L"Failed to hook one or more functions in twinui.pcshell.dll, trying twinui.dll");

        HMODULE hTwinUI = LoadLibraryExW(L"twinui.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
        if (!WindhawkUtils::HookSymbols(hTwinUI, c_rgTwinUIPCShellHooks, ARRAYSIZE(c_rgTwinUIPCShellHooks)))
        {
            Wh_Log(L"Failed to hook one or more functions in twinui.dll");
            return FALSE;
        }
    }

    return TRUE;
}

// ==WindhawkMod==
// @id              virtual-desktop-swipe-taskbar-fix
// @name            Virtual Desktop Swipe Taskbar Fix
// @description     Restores taskbar presence in virtual desktop swipe previews.
// @version         1.0.5
// @author          meteoni
// @github          https://github.com/Meteoni
// @license         MIT
// @include         explorer.exe
// @architecture    amd64
// ==/WindhawkMod==

// ==WindhawkModReadme==
/*
# Virtual Desktop Swipe Taskbar Fix

Restores the missing incoming taskbar bitmap during a touchpad virtual desktop swipe
on Windows 11.

![The issue](https://raw.githubusercontent.com/Meteoni/meteoni-assets/main/virtual-desktop-swipe-taskbar-fix/virtual-desktop-swipe-taskbar-fix.png)
_The issue_

## Limitation

While a swipe is held, both previews can show the current desktop's taskbar
buttons, instead of reflecting the incoming taskbar's current state. This is
because Windows has not yet committed the switch during a swipe gesture, and
thumbnails taken at that time inevitably look the same as on the outgoing
desktop.

Keyboard switching avoids this because it freezes the outgoing taskbar preview
and updates the actual taskbar during the transition, allowing the live incoming
preview to show the destination desktop's buttons.

ARM64 is not supported: native methods are resolved through symbols, but internal
member offsets are discovered from those methods at initialization. Initialization
stops if the required symbols or layout cannot be recognized.
*/
// ==/WindhawkModReadme==

#include <windhawk_utils.h>
#include <unknwn.h>
#include <cstddef>
#include <array>
#include <map>
#include <cstdio>
#include <cwchar>
#include <optional>
#include <regex>
#include <string>
#include <vector>

using GetTrayBitmapResult = HRESULT (*)(void*, const void*, int, const RECT&, void*, IUnknown*);
using InitializeGestureWindow = HRESULT (*)(void*, unsigned long);
using GetTrayWindowForMonitor = HWND (*)(HMONITOR);
using AddThumbnailToCollection = HRESULT (*)(void*, unsigned int, IUnknown*);
using CreateWindowThumbnail = HRESULT (*)(void*, IUnknown*, HWND, DWORD,
                                        const SIZE*, RECT*, const GUID&, void**);
using SetThumbnailRect = HRESULT (*)(IUnknown*, const RECT&, int, void*);

GetTrayBitmapResult g_getTrayBitmapResultOriginal;
InitializeGestureWindow g_initializeGestureWindow;
GetTrayWindowForMonitor g_getTrayWindowForMonitor;
AddThumbnailToCollection g_addThumbnailToCollection;
CreateWindowThumbnail g_createWindowThumbnail;
SetThumbnailRect g_setThumbnailRect;
void* g_switchThumbnailFactoryVftable;
void* g_createCustomPaintThumbnail;

struct GestureLayout {
    size_t window;
    size_t bitmap;
    size_t customPaint;
    size_t contextType;
    size_t factory;
    size_t parent;
    size_t firstCollection;
    size_t secondCollection;
    unsigned int firstCollectionSelector;
} g_gestureLayout;

struct NativeInstruction {
    uintptr_t address;
    size_t length;
    std::string text;
    std::vector<uintptr_t> successors;
};

bool ReadFunctionControlFlow(void* function, size_t instructionLimit,
                             std::vector<NativeInstruction>& instructions,
                             const void* nativeImage = nullptr) {
    DWORD64 imageBase = 0;
    auto* entry = RtlLookupFunctionEntry(reinterpret_cast<DWORD64>(function), &imageBase, nullptr);
    IMAGE_DOS_HEADER dos{};
    IMAGE_NT_HEADERS64 nt{};
    if (!entry || !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(imageBase),
            &dos, sizeof(dos), nullptr) || dos.e_magic != IMAGE_DOS_SIGNATURE ||
        dos.e_lfanew < 0 || dos.e_lfanew > 0x100000 ||
        !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(imageBase + dos.e_lfanew),
            &nt, sizeof(nt), nullptr) || nt.Signature != IMAGE_NT_SIGNATURE ||
        nt.FileHeader.Machine != IMAGE_FILE_MACHINE_AMD64 ||
        nt.OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR64_MAGIC ||
        nt.OptionalHeader.SizeOfImage < sizeof(nt)) {
        Wh_Log(L"Function unwind metadata unavailable for %p", function);
        return false;
    }
    uintptr_t codeBase = nativeImage ? reinterpret_cast<uintptr_t>(nativeImage) : imageBase;
    if (nativeImage) {
        IMAGE_DOS_HEADER copyDos{};
        IMAGE_NT_HEADERS64 copyNt{};
        if (!ReadProcessMemory(GetCurrentProcess(), nativeImage, &copyDos, sizeof(copyDos), nullptr) ||
            copyDos.e_magic != dos.e_magic || copyDos.e_lfanew != dos.e_lfanew ||
            !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(codeBase + dos.e_lfanew),
                &copyNt, sizeof(copyNt), nullptr) || copyNt.Signature != nt.Signature ||
            copyNt.FileHeader.Machine != nt.FileHeader.Machine ||
            copyNt.FileHeader.TimeDateStamp != nt.FileHeader.TimeDateStamp ||
            copyNt.OptionalHeader.SizeOfImage != nt.OptionalHeader.SizeOfImage ||
            copyNt.OptionalHeader.CheckSum != nt.OptionalHeader.CheckSum) {
            Wh_Log(L"Native image differs from the loaded shell module");
            return false;
        }
    }

    // Chained unwind entries identify separated regions of the same function.
    // Do not infer ownership from proximity or follow an arbitrary external jump.
    auto primaryEntry = [&](RUNTIME_FUNCTION region) -> std::optional<RUNTIME_FUNCTION> {
        for (int depth = 0; depth < 8; ++depth) {
            BYTE header[4]{};
            if (region.BeginAddress >= region.EndAddress || region.EndAddress > nt.OptionalHeader.SizeOfImage ||
                region.UnwindData > nt.OptionalHeader.SizeOfImage - sizeof(header) ||
                !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(imageBase + region.UnwindData),
                    header, sizeof(header), nullptr) || ((header[0] & 7) != 1 && (header[0] & 7) != 2)) return std::nullopt;
            if (!(header[0] & (UNW_FLAG_CHAININFO << 3))) return region;
            size_t chainOffset = region.UnwindData + 4 + ((header[2] + 1) & ~1u) * 2;
            if (chainOffset > nt.OptionalHeader.SizeOfImage - sizeof(region) ||
                !ReadProcessMemory(GetCurrentProcess(), reinterpret_cast<void*>(imageBase + chainOffset),
                    &region, sizeof(region), nullptr)) return std::nullopt;
        }
        return std::nullopt;
    };
    auto primary = primaryEntry(*entry);
    if (!primary) {
        Wh_Log(L"Invalid function unwind chain for %p", function);
        return false;
    }
    std::vector<std::pair<uintptr_t, uintptr_t>> regions{
        {imageBase + entry->BeginAddress, imageBase + entry->EndAddress}};
    std::map<uintptr_t, size_t> decodedAddresses;
    const std::regex directBranch(R"(0x[0-9a-f]+)");
    std::vector<uintptr_t> pending{reinterpret_cast<uintptr_t>(function)};
    while (!pending.empty()) {
        uintptr_t address = pending.back();
        pending.pop_back();
        while (!decodedAddresses.contains(address)) {
            uintptr_t regionEnd = 0;
            for (const auto& [begin, end] : regions) {
                if (address >= begin && address < end) { regionEnd = end; break; }
            }
            if (!regionEnd) {
                DWORD64 targetImage = 0;
                auto* target = RtlLookupFunctionEntry(address, &targetImage, nullptr);
                auto owner = target && targetImage == imageBase ? primaryEntry(*target) : std::nullopt;
                if (!owner || owner->BeginAddress != primary->BeginAddress ||
                    owner->EndAddress != primary->EndAddress || owner->UnwindData != primary->UnwindData) {
                    Wh_Log(L"Branch outside verified function regions: %p", reinterpret_cast<void*>(address));
                    return false;
                }
                regions.emplace_back(imageBase + target->BeginAddress, imageBase + target->EndAddress);
                regionEnd = regions.back().second;
            }
            if (instructions.size() >= instructionLimit) {
                Wh_Log(L"Function instruction budget exceeded for %p", function);
                return false;
            }
            WH_DISASM_RESULT result{};
            if (!Wh_Disasm(reinterpret_cast<void*>(codeBase + address - imageBase), &result) || !result.length ||
                result.length > 15 || result.length > regionEnd - address) {
                Wh_Log(L"Failed to disassemble instruction at %p", reinterpret_cast<void*>(address));
                return false;
            }
            // Reject branches into an instruction, including instructions decoded earlier.
            auto following = decodedAddresses.upper_bound(address);
            bool overlapsPrevious = false;
            if (following != decodedAddresses.begin()) {
                const auto& previous = instructions[std::prev(following)->second];
                overlapsPrevious = previous.address + previous.length > address;
            }
            if ((following != decodedAddresses.end() && following->first < address + result.length) ||
                overlapsPrevious) {
                Wh_Log(L"Overlapping instruction boundaries at %p", reinterpret_cast<void*>(address));
                return false;
            }
            NativeInstruction instruction{address, result.length, result.text, {}};
            for (char& character : instruction.text) {
                if (character >= 'A' && character <= 'Z') character += 'a' - 'A';
            }
            bool terminates = instruction.text.starts_with("ret") || instruction.text == "int3" || instruction.text == "ud2";
            bool jump = instruction.text.starts_with('j') || instruction.text.starts_with("loop");
            if (jump) {
                auto operand = instruction.text.substr(instruction.text.find(' ') + 1);
                if (!std::regex_match(operand, directBranch)) {
                    Wh_Log(L"Indirect branch not supported at %p", reinterpret_cast<void*>(address));
                    return false;
                }
                uintptr_t target = std::stoull(operand, nullptr, 0);
                if (target < codeBase || target - codeBase >= nt.OptionalHeader.SizeOfImage) {
                    Wh_Log(L"Branch outside native image at %p", reinterpret_cast<void*>(address));
                    return false;
                }
                target = imageBase + target - codeBase;
                instruction.successors.push_back(target);
                if (!instruction.text.starts_with("jmp ")) {
                    instruction.successors.push_back(address + result.length);
                    pending.push_back(target);
                }
            } else if (!terminates) {
                instruction.successors.push_back(address + result.length);
            }
            decodedAddresses.emplace(address, instructions.size());
            instructions.push_back(std::move(instruction));
            if (instructions.back().successors.empty()) break;
            // Conditional fallthrough first; ret only terminates its own path.
            address = instructions.back().successors.back();
        }
    }
    return true;
}

bool FindCreationMembers(const std::vector<NativeInstruction>& instructions,
                         size_t& factoryOffset, size_t& parentOffset, const std::string& owner) {
    enum class Kind { Unknown, Object, Member, Vtable, CreationMethod, Ambiguous };
    struct Value {
        Kind kind = Kind::Unknown;
        intptr_t offset = 0;
        bool mayCreate = false;
        bool operator==(const Value&) const = default;
    };
    using Registers = std::array<Value, 16>;
    const char* registerNames[16][5]{
        {"rax", "eax", "ax", "al", "ah"}, {"rcx", "ecx", "cx", "cl", "ch"},
        {"rdx", "edx", "dx", "dl", "dh"}, {"rbx", "ebx", "bx", "bl", "bh"},
        {"rsp", "esp", "sp", "spl", nullptr}, {"rbp", "ebp", "bp", "bpl", nullptr},
        {"rsi", "esi", "si", "sil", nullptr}, {"rdi", "edi", "di", "dil", nullptr},
        {"r8", "r8d", "r8w", "r8b", nullptr}, {"r9", "r9d", "r9w", "r9b", nullptr},
        {"r10", "r10d", "r10w", "r10b", nullptr}, {"r11", "r11d", "r11w", "r11b", nullptr},
        {"r12", "r12d", "r12w", "r12b", nullptr}, {"r13", "r13d", "r13w", "r13b", nullptr},
        {"r14", "r14d", "r14w", "r14b", nullptr}, {"r15", "r15d", "r15w", "r15b", nullptr},
    };
    auto registerIndex = [&](const std::string& operand) {
        for (int index = 0; index < 16; ++index) {
            for (const char* name : registerNames[index]) if (name && operand == name) return index;
        }
        return -1;
    };
    auto merge = [](Value left, Value right) {
        if (left == right) return left;
        return Value{Kind::Ambiguous, 0, left.mayCreate || right.mayCreate};
    };
    std::regex memoryLoad(R"((?:qword ptr )?\[(r\w+)(?:([+-])(0x[0-9a-f]+))?\])");
    std::map<size_t, bool> creationSlots;
    auto isCreationSlot = [&](size_t offset) {
        if (offset >= 0x10000 || offset % alignof(void*)) return false;
        auto [slot, inserted] = creationSlots.try_emplace(offset, false);
        if (inserted) {
            void* method = nullptr;
            slot->second = ReadProcessMemory(GetCurrentProcess(),
                static_cast<const std::byte*>(g_switchThumbnailFactoryVftable) + offset,
                &method, sizeof(method), nullptr) && method == g_createCustomPaintThumbnail;
        }
        return slot->second;
    };
    std::map<uintptr_t, size_t> addresses;
    for (size_t index = 0; index < instructions.size(); ++index) addresses.emplace(instructions[index].address, index);
    // Identify the owner-parent call sites. The special context passes the
    // adjacent-desktop argument instead; its stack spill is not a member offset.
    std::map<uintptr_t, size_t> ends;
    for (size_t index = 0; index < instructions.size(); ++index) ends.emplace(instructions[index].address + instructions[index].length, index);
    std::vector<std::optional<size_t>> callParents(instructions.size());
    std::regex parentLoad(R"(mov rdx, (?:qword ptr )?\[)" + owner + R"(\+(0x[0-9a-f]+)\])");
    std::regex thisArgument(R"(mov rcx, r\w+)");
    for (size_t index = 0; index < instructions.size(); ++index) {
        if (!instructions[index].text.starts_with("call ")) continue;
        auto method = ends.find(instructions[index].address);
        if (method == ends.end() || !instructions[method->second].text.starts_with("mov rax, ")) continue;
        auto self = ends.find(instructions[method->second].address);
        if (self == ends.end() || !std::regex_match(instructions[self->second].text, thisArgument)) continue;
        auto parent = ends.find(instructions[self->second].address);
        std::smatch load;
        if (parent != ends.end() && std::regex_match(instructions[parent->second].text, load, parentLoad)) callParents[index] = std::stoull(load[1], nullptr, 0);
    }
    std::vector<std::optional<Registers>> incoming(instructions.size());
    Registers entry{};
    entry[1].kind = Kind::Object; // rcx is the gesture object at entry.
    incoming[0] = entry;
    std::vector<size_t> pending{0};
    size_t transfers = 0;
    while (!pending.empty()) {
        if (++transfers > instructions.size() * 64) {
            Wh_Log(L"Factory register analysis budget exceeded");
            return false;
        }
        size_t index = pending.back();
        pending.pop_back();
        Registers state = *incoming[index];
        const std::string& text = instructions[index].text;
        size_t separator = text.find(' ');
        std::string opcode = text.substr(0, separator);
        std::string operands = separator == std::string::npos ? "" : text.substr(separator + 1);
        size_t comma = operands.find(", ");
        std::string destination = operands.substr(0, comma);
        std::string source = comma == std::string::npos ? "" : operands.substr(comma + 2);
        int targetRegister = registerIndex(destination);
        int sourceRegister = registerIndex(source);
        if (opcode == "call") {
            // Windows x64 calls preserve nonvolatile registers, not their arguments.
            for (int reg : {0, 1, 2, 8, 9, 10, 11}) state[reg] = {};
        } else if (opcode == "mov" && targetRegister >= 0) {
            Value value;
            std::smatch load;
            if (destination == registerNames[targetRegister][0]) {
                if (sourceRegister >= 0 && source == registerNames[sourceRegister][0]) {
                    value = state[sourceRegister];
                } else if (std::regex_match(source, load, memoryLoad)) {
                    int base = registerIndex(load[1]);
                    intptr_t offset = load[3].matched ? std::stoll(load[3], nullptr, 0) : 0;
                    if (load[2] == "-") offset = -offset;
                    if (base >= 0 && offset > -0x10000 && offset < 0x10000) {
                        Value pointer = state[base];
                        if (pointer.kind == Kind::Object && offset >= 0) value = {Kind::Member, offset, false};
                        else if (pointer.kind == Kind::Member && !offset) value = {Kind::Vtable, pointer.offset, false};
                        else if (pointer.kind == Kind::Vtable && offset >= 0 && isCreationSlot(offset)) value = {Kind::CreationMethod, pointer.offset, true};
                        else if (pointer.kind == Kind::Ambiguous) {
                            value = pointer;
                            value.mayCreate |= offset >= 0 && isCreationSlot(offset);
                        } else if (pointer.kind == Kind::Unknown && offset >= 0 && isCreationSlot(offset)) value.mayCreate = true;
                    }
                }
            }
            state[targetRegister] = value;
        } else if (opcode.starts_with("cmov") && targetRegister >= 0) {
            Value alternative = sourceRegister >= 0 && source == registerNames[sourceRegister][0] ? state[sourceRegister] : Value{};
            state[targetRegister] = destination == registerNames[targetRegister][0] ?
                merge(state[targetRegister], alternative) : Value{};
        } else if (opcode.starts_with("loop")) {
            state[1] = {}; // LOOP decrements rcx, unlike an ordinary conditional jump.
        } else if (opcode == "cmp" || opcode == "test" || opcode == "push" || opcode == "nop" ||
                   opcode.starts_with('j') || opcode.starts_with("ret") || opcode == "int3" || opcode == "ud2") {
            // These instructions do not write a tracked pointer register.
        } else if (opcode == "mul" || opcode == "imul" || opcode == "div" || opcode == "idiv" || opcode == "cpuid" ||
                   opcode == "xchg" || opcode == "xadd" || opcode.starts_with("cmpxchg")) {
            state = {}; // Implicit or multiple outputs are outside this narrow analysis.
        } else if (targetRegister >= 0) {
            state[targetRegister] = {}; // Includes partial-register writes and arithmetic.
        } else if (opcode == "mov" || opcode == "movaps" || opcode == "movups" ||
                   opcode == "movdqa" || opcode == "movdqu" || opcode == "xorps" ||
                   opcode == "and" || opcode == "or" || opcode == "xor" || opcode == "add" ||
                   opcode == "sub" || opcode == "inc" || opcode == "dec" || opcode == "lea") {
            // Memory and SIMD destinations do not replace the pointer registers.
        } else {
            state = {}; // Unknown side effects must not preserve a guessed definition.
        }
        for (uintptr_t successor : instructions[index].successors) {
            size_t next = addresses.at(successor);
            if (!incoming[next]) {
                incoming[next] = state;
                pending.push_back(next);
            } else {
                bool changed = false;
                for (size_t reg = 0; reg < state.size(); ++reg) {
                    Value combined = merge((*incoming[next])[reg], state[reg]);
                    if (combined != (*incoming[next])[reg]) { (*incoming[next])[reg] = combined; changed = true; }
                }
                if (changed) pending.push_back(next);
            }
        }
    }
    std::optional<intptr_t> factory;
    std::optional<intptr_t> parent;
    for (size_t index = 0; index < instructions.size(); ++index) {
        if (!callParents[index]) continue;
        const Registers& arguments = *incoming[index];
        const Value& method = arguments[0];
        if (!method.mayCreate) continue;
        if (method.kind == Kind::Ambiguous || arguments[1].kind == Kind::Ambiguous || arguments[2].kind == Kind::Ambiguous) {
            Wh_Log(L"Ambiguous thumbnail creation arguments at %p", reinterpret_cast<void*>(instructions[index].address));
            return false;
        }
        if (method.kind != Kind::CreationMethod || arguments[1].kind != Kind::Member || arguments[2].kind != Kind::Member) {
            Wh_Log(L"Unverified thumbnail creation arguments at %p", reinterpret_cast<void*>(instructions[index].address));
            return false;
        }
        if (arguments[1].offset != method.offset || arguments[2].offset != static_cast<intptr_t>(*callParents[index]) ||
            (factory && *factory != method.offset) || (parent && *parent != arguments[2].offset)) {
            Wh_Log(L"Conflicting factory or parent definitions at thumbnail creation");
            return false;
        }
        factory = method.offset;
        parent = arguments[2].offset;
    }
    if (!factory || !parent) {
        Wh_Log(L"Thumbnail creation arguments not recognized");
        return false;
    }
    factoryOffset = static_cast<size_t>(*factory);
    parentOffset = static_cast<size_t>(*parent);
    return true;
}

bool DiscoverGestureLayout(void* bitmapResult, void* initialize, void* addThumbnail,
                           GestureLayout& layout) {
    // Windhawk can retain its entry-point redirection after a hook is removed.
    // Decode the matching on-disk image, without running its code or following hooks.
    // Unwind boundaries and discovered member offsets still refer to the loaded DLL.
    DWORD64 imageBase = 0;
    if (!RtlLookupFunctionEntry(reinterpret_cast<DWORD64>(bitmapResult), &imageBase, nullptr)) return false;
    wchar_t modulePath[MAX_PATH]{};
    DWORD pathLength = GetModuleFileNameW(reinterpret_cast<HMODULE>(imageBase), modulePath, ARRAYSIZE(modulePath));
    if (!pathLength || pathLength >= ARRAYSIZE(modulePath)) return false;
    struct NativeImage {
        HANDLE file = INVALID_HANDLE_VALUE;
        HANDLE mapping = nullptr;
        void* view = nullptr;
        ~NativeImage() {
            if (view) UnmapViewOfFile(view);
            if (mapping) CloseHandle(mapping);
            if (file != INVALID_HANDLE_VALUE) CloseHandle(file);
        }
    } native;
    native.file = CreateFileW(modulePath, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                              nullptr, OPEN_EXISTING, 0, nullptr);
    if (native.file != INVALID_HANDLE_VALUE) {
        native.mapping = CreateFileMappingW(native.file, nullptr, PAGE_READONLY | SEC_IMAGE_NO_EXECUTE, 0, 0, nullptr);
        if (native.mapping) native.view = MapViewOfFile(native.mapping, FILE_MAP_READ, 0, 0, 0);
    }
    if (!native.view) {
        Wh_Log(L"Unable to map native shell code: %lu", GetLastError());
        return false;
    }
    std::string code[3];
    std::vector<NativeInstruction> graphs[3];
    void* functions[]{bitmapResult, initialize, addThumbnail};
    const wchar_t* methodNames[]{L"GetTrayBitmapResult", L"Initialize", L"AddThumbnailToThumbnailCollection"};
    const size_t limits[]{1024, 2048, 512};
    for (size_t index = 0; index < ARRAYSIZE(functions); ++index) {
        if (!ReadFunctionControlFlow(functions[index], limits[index], graphs[index], native.view)) {
            Wh_Log(L"Control-flow discovery failed for %s", methodNames[index]);
            return false;
        }
        uintptr_t previousEnd = 0;
        for (const auto& instruction : graphs[index]) {
            // Keep disjoint paths from forming an artificial multi-instruction match.
            if (previousEnd != instruction.address) code[index] += "#;";
            code[index] += instruction.text + ';';
            previousEnd = instruction.address + instruction.length;
            if (instruction.text.starts_with("jmp ") || instruction.text.starts_with("ret")) previousEnd = 0;
        }
    }
    auto offsetFrom = [](const std::string& instructions, const std::string& pattern,
                         size_t group = 1) -> std::optional<size_t> {
        std::smatch match;
        if (!std::regex_search(instructions, match, std::regex(pattern))) return std::nullopt;
        size_t offset = std::stoull(match[group], nullptr, 0);
        if (offset >= 0x10000) return std::nullopt;
        return offset;
    };

    std::smatch self;
    // Example: mov rsi, rcx. rsi holds the gesture object in subsequent accesses.
    if (!std::regex_search(code[0], self, std::regex(R"(mov (r\w+), rcx;)"))) {
        Wh_Log(L"Gesture object register not found");
        return false;
    }
    const std::string owner = self[1];
    const std::string ownerMember = R"(\[)" + owner + R"(\+(0x[0-9a-f]+)\])";

    // Example: mov rcx, [rdx+0x10]; xor ebx, ebx; test rcx, rcx.
    // The bitmap load and null check must use the same register.
    auto bitmap = offsetFrom(code[0],
        R"(mov (r\w+), (?:qword ptr )?\[rdx\+(0x[0-9a-f]+)\];(?:xor \w+, \w+;)?test \1, \1;)", 2);
    // Example: cmp [rsi+0x08], rbx. This checks the destination HWND for null.
    auto window = offsetFrom(code[0], R"(cmp (?:qword ptr )?)" + ownerMember + R"(, \w+;)");
    // Example: mov [rcx+0xE4], edx. Initialize stores the context-type argument.
    auto contextType = offsetFrom(code[1], R"(mov (?:dword ptr )?\[rcx\+(0x[0-9a-f]+)\], edx;)");
    if (!bitmap) {
        Wh_Log(L"Bitmap handle offset not found");
        return false;
    }
    if (!window) {
        Wh_Log(L"Gesture window offset not found");
        return false;
    }
    if (!contextType) {
        Wh_Log(L"Context-type offset not found");
        return false;
    }

    size_t factoryOffset = 0;
    size_t parentOffset = 0;
    if (!FindCreationMembers(graphs[0], factoryOffset, parentOffset, owner)) return false;
    std::optional<size_t> factory = factoryOffset;
    std::optional<size_t> parent = parentOffset;
    size_t customPaint = SIZE_MAX;
    std::smatch flag;
    // Example: lea r13, [rsi+0xE0]; ...; cmp [r13], bl.
    // The flag address must be followed by a byte comparison through it.
    if (std::regex_search(code[0], flag,
            std::regex(R"(lea (r\w+), \[)" + owner + R"(\+(0x[0-9a-f]+)\];)"))) {
        if (!std::regex_search(code[0],
                std::regex(R"(cmp (?:byte ptr )?\[)" + flag[1].str() + R"(\], (?:[abcd]l|r\d+b);)"))) {
            Wh_Log(L"Custom-paint flag comparison not found");
            return false;
        }
        customPaint = std::stoull(flag[2], nullptr, 0);
        if (customPaint >= 0x10000) {
            Wh_Log(L"Invalid custom-paint offset: 0x%zx", customPaint);
            return false;
        }
    } else {
        // Older builds have no custom-paint flag, only the context-type checks.
        if (std::regex_search(code[0], std::regex("byte ptr \\[" + owner))) {
            Wh_Log(L"Unrecognized custom-paint flag access");
            return false;
        }
        char typeOffset[32]{};
        snprintf(typeOffset, sizeof(typeOffset), "%zx", *contextType);
        std::regex typeBranch("cmp dword ptr \\[" + owner + "\\+0x0*" +
                              typeOffset + R"(\], 0x0*2;)");
        // Example: cmp dword ptr [r14+0xE0], 0x02. Require both mode checks.
        auto branches = std::distance(std::sregex_iterator(code[0].begin(), code[0].end(), typeBranch), std::sregex_iterator());
        if (branches != 2) {
            Wh_Log(L"Expected two context-type checks, found %td", branches);
            return false;
        }
    }

    // Windows owns both thumbnail arrays. Either can receive the adjacent desktop.
    std::smatch collectionOwner;
    std::smatch selectorRegister;
    // Example: mov rsi, rcx; mov ebx, edx. Some builds keep rcx and edx instead.
    const std::string collectionBase = std::regex_search(code[2], collectionOwner,
        std::regex(R"(mov (r\w+), rcx;)")) ? collectionOwner[1].str() : "rcx";
    const std::string selector = std::regex_search(code[2], selectorRegister,
        std::regex(R"(mov (e\w+), edx;)")) ? selectorRegister[1].str() : "edx";
    // Example: cmp ebx, 3; jnz ... . Equality selects the first array.
    auto firstCollectionSelector = offsetFrom(code[2], "cmp " + selector +
        R"(, (0x[0-9a-f]+|[0-9]+);(?:jne|jnz) )");
    if (!firstCollectionSelector) {
        Wh_Log(L"Thumbnail collection selector not found");
        return false;
    }
    std::smatch collectionTarget;
    // Example: lea rcx, [rsi+0x40] / lea rcx, [rsi+0x60].
    // Both branches use the same destination register for the array address.
    if (!std::regex_search(code[2], collectionTarget,
            std::regex(R"(lea (r\w+), \[)" + collectionBase + R"(\+0x[0-9a-f]+\];)"))) {
        Wh_Log(L"Thumbnail collection address calculation not found");
        return false;
    }
    std::regex collectionPattern("lea " + collectionTarget[1].str() + R"(, \[)" + collectionBase +
                                 R"(\+(0x[0-9a-f]+)\];)");
    std::vector<size_t> collections;
    for (auto it = std::sregex_iterator(code[2].begin(), code[2].end(), collectionPattern);
         it != std::sregex_iterator(); ++it) {
        size_t offset = std::stoull((*it)[1], nullptr, 0);
        if (collections.empty() || collections.back() != offset) collections.push_back(offset);
    }
    if (collections.size() != 2) {
        Wh_Log(L"Expected two thumbnail collection offsets, found %zu", collections.size());
        return false;
    }
    for (size_t offset : {*bitmap, *window, *factory, *parent, collections[0], collections[1]}) {
        if (!offset || offset >= 0x10000 || offset % alignof(void*)) {
            Wh_Log(L"Invalid pointer member offset: 0x%zx", offset);
            return false;
        }
    }
    if (*factory == *parent || collections[0] == collections[1] || customPaint == *contextType) {
        Wh_Log(L"Discovered member offsets overlap");
        return false;
    }
    layout = {*window, *bitmap, customPaint, *contextType, *factory, *parent,
              collections[0], collections[1], static_cast<unsigned int>(*firstCollectionSelector)};
    return true;
}

HRESULT GetTrayBitmapResultHook(void* gestureWindow, const void* bitmapData,
                               int desktopOffset, const RECT& bitmapRect,
                               void* thumbnails, IUnknown* adjacentDesktop) {
    auto* windowBytes = static_cast<std::byte*>(gestureWindow);
    HWND destination = *reinterpret_cast<HWND*>(windowBytes + g_gestureLayout.window);
    wchar_t destinationClass[64]{};
    GetClassNameW(destination, destinationClass, ARRAYSIZE(destinationClass));
    if (wcscmp(destinationClass, L"VirtualDesktopGestureSwitcher") != 0) {
        return g_getTrayBitmapResultOriginal(gestureWindow, bitmapData, desktopOffset,
                                            bitmapRect, thumbnails, adjacentDesktop);
    }
    HBITMAP bitmap = *reinterpret_cast<HBITMAP const*>(
        static_cast<const std::byte*>(bitmapData) + g_gestureLayout.bitmap);
    if (bitmap ||
        (thumbnails != windowBytes + g_gestureLayout.firstCollection &&
         thumbnails != windowBytes + g_gestureLayout.secondCollection) ||
        (g_gestureLayout.customPaint != SIZE_MAX &&
         *reinterpret_cast<const bool*>(windowBytes + g_gestureLayout.customPaint)) ||
        *reinterpret_cast<const int*>(windowBytes + g_gestureLayout.contextType) == 2) {
        return g_getTrayBitmapResultOriginal(gestureWindow, bitmapData, desktopOffset,
                                            bitmapRect, thumbnails, adjacentDesktop);
    }

    auto* factory = *reinterpret_cast<void**>(windowBytes + g_gestureLayout.factory);
    IUnknown* parent = *reinterpret_cast<IUnknown**>(windowBytes + g_gestureLayout.parent);
    // Check the concrete factory type without dereferencing an invalid candidate.
    void* factoryVftable = nullptr;
    bool verifiedFactory = factory && ReadProcessMemory(GetCurrentProcess(), factory,
        &factoryVftable, sizeof(factoryVftable), nullptr) &&
        factoryVftable == g_switchThumbnailFactoryVftable;
    HWND taskbar = g_getTrayWindowForMonitor(MonitorFromWindow(destination, MONITOR_DEFAULTTONEAREST));
    IUnknown* taskbarThumbnail = nullptr;
    RECT destinationRect{};
    HRESULT replacementResult = E_NOTIMPL;
    if (verifiedFactory && parent && taskbar && IsWindow(destination) && GetWindowRect(taskbar, &destinationRect)) {
        RECT sourceRect{0, 0, destinationRect.right - destinationRect.left,
                       destinationRect.bottom - destinationRect.top};
        if (sourceRect.right > 0 && sourceRect.bottom > 0) {
            // MapWindowPoints can return zero on success. Check last error then.
            SetLastError(ERROR_SUCCESS);
            int mapped = MapWindowPoints(nullptr, destination,
                                         reinterpret_cast<POINT*>(&destinationRect), 2);
            if (mapped != 0 || GetLastError() == ERROR_SUCCESS) {
                const GUID thumbnailInterface{0x47267895, 0xA4F8, 0x4012,
                                              {0x9E, 0x98, 0x08, 0x7C, 0x61, 0x9E, 0x7C, 0xFC}};
                replacementResult = g_createWindowThumbnail(
                    factory, parent, taskbar, 0, nullptr, &sourceRect, thumbnailInterface,
                    reinterpret_cast<void**>(&taskbarThumbnail));
                if (SUCCEEDED(replacementResult) && taskbarThumbnail) {
                    destinationRect.left += desktopOffset;
                    destinationRect.right += desktopOffset;
                    replacementResult = g_setThumbnailRect(taskbarThumbnail, destinationRect, 0, nullptr);
                    if (SUCCEEDED(replacementResult)) {
                        // Append to the callback's array, regardless of swipe direction.
                        unsigned int collectionSelector = g_gestureLayout.firstCollectionSelector;
                        if (thumbnails == windowBytes + g_gestureLayout.secondCollection) ++collectionSelector;
                        replacementResult = g_addThumbnailToCollection(
                            gestureWindow, collectionSelector, taskbarThumbnail);
                    }
                } else if (SUCCEEDED(replacementResult)) {
                    replacementResult = E_UNEXPECTED;
                }
            } else {
                replacementResult = HRESULT_FROM_WIN32(GetLastError());
            }
        }
    }
    // The native append AddRefs the thumbnail. Release our factory reference.
    if (taskbarThumbnail) taskbarThumbnail->Release();
    if (SUCCEEDED(replacementResult)) {
        Wh_Log(L"Replaced taskbar=%p collection=0x%zx offset=%d rect=(%ld,%ld,%ld,%ld)", taskbar,
               thumbnails == windowBytes + g_gestureLayout.firstCollection ?
                   g_gestureLayout.firstCollection : g_gestureLayout.secondCollection, desktopOffset,
               destinationRect.left, destinationRect.top, destinationRect.right, destinationRect.bottom);
        return S_OK;
    }
    Wh_Log(L"Thumbnail replacement failed: 0x%08lX", static_cast<unsigned long>(replacementResult));
    return g_getTrayBitmapResultOriginal(gestureWindow, bitmapData, desktopOffset,
                                        bitmapRect, thumbnails, adjacentDesktop);
}

BOOL Wh_ModInit() {
    HMODULE shell = GetModuleHandleW(L"twinui.pcshell.dll");
    HMODULE thumbnails = GetModuleHandleW(L"twinui.dll");
    // Load missing shell modules during early Explorer startup.
    // Keep the acquired references for the process lifetime; reuse on mod reload.
    if (!shell) shell = LoadLibraryExW(L"twinui.pcshell.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!thumbnails) thumbnails = LoadLibraryExW(L"twinui.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!shell || !thumbnails) {
        Wh_Log(L"Shell modules unavailable: twinui.pcshell=%p twinui=%p", shell, thumbnails);
        return FALSE;
    }
    // twinui.pcshell.dll
    WindhawkUtils::SYMBOL_HOOK shellSymbols[]{
        {{L"protected: long __cdecl VirtualDesktopGestureWindow::GetTrayBitmapResult(struct TrayBitmapForVDThumbnailData const &,int,struct Geometry::CRect const &,class CCoSimpleArray<class Microsoft::WRL::ComPtr<struct IDCompThumbnail>,4294967294,class CSimpleArrayStandardCompareHelper<class Microsoft::WRL::ComPtr<struct IDCompThumbnail> > > &,struct IDCompThumbnail *)",
          L"private: long __cdecl VirtualDesktopGestureWindow::GetTrayBitmapResult(struct TrayBitmapForVDThumbnailData const &,int,struct Geometry::CRect const &,class CCoSimpleArray<class Microsoft::WRL::ComPtr<struct IDCompThumbnail>,4294967294,class CSimpleArrayStandardCompareHelper<class Microsoft::WRL::ComPtr<struct IDCompThumbnail> > > &,struct IDCompThumbnail *)"}, &g_getTrayBitmapResultOriginal},
        {{L"public: long __cdecl VirtualDesktopGestureWindow::Initialize(unsigned long)"}, &g_initializeGestureWindow},
        {{L"public: long __cdecl VirtualDesktopGestureWindow::AddThumbnailToThumbnailCollection(unsigned int,struct IDCompThumbnail *)"}, &g_addThumbnailToCollection},
        {{L"struct HWND__ * __cdecl TaskbarHelpers::GetTrayWindowForMonitor(struct HMONITOR__ *)"}, &g_getTrayWindowForMonitor},
    };
    // twinui.dll
    WindhawkUtils::SYMBOL_HOOK thumbnailSymbols[]{
        {{L"const CSwitchThumbnailFactory::`vftable'"}, &g_switchThumbnailFactoryVftable},
        {{L"public: virtual long __cdecl CSwitchThumbnailFactory::CreateCustomPaintThumbnail(struct IDCompThumbnail *,struct tagSIZE,enum CustomPaintThumbnailFlags,struct _GUID const &,void * *)"}, &g_createCustomPaintThumbnail},
        {{L"public: virtual long __cdecl CSwitchThumbnailFactory::CreateThumbnail(struct IDCompThumbnail *,struct HWND__ *,unsigned long,struct tagSIZE const *,struct tagRECT *,struct _GUID const &,void * *)"}, &g_createWindowThumbnail},
        {{L"protected: virtual long __cdecl CDCompAbstractThumbnail::SetRect(struct tagRECT const &,enum DCompThumbnailAnimation,struct IUIAnimationStoryboardEventHandler2 *)"}, &g_setThumbnailRect},
    };
    if (!WindhawkUtils::HookSymbols(shell, shellSymbols, ARRAYSIZE(shellSymbols)) ||
        !WindhawkUtils::HookSymbols(thumbnails, thumbnailSymbols, ARRAYSIZE(thumbnailSymbols))) return FALSE;
    try {
        if (!DiscoverGestureLayout(reinterpret_cast<void*>(g_getTrayBitmapResultOriginal),
                reinterpret_cast<void*>(g_initializeGestureWindow),
                reinterpret_cast<void*>(g_addThumbnailToCollection), g_gestureLayout)) {
            return FALSE;
        }
    } catch (const std::exception& exception) {
        Wh_Log(L"Layout discovery failed: %S", exception.what());
        return FALSE;
    }
    if (!WindhawkUtils::SetFunctionHook(g_getTrayBitmapResultOriginal,
            GetTrayBitmapResultHook, &g_getTrayBitmapResultOriginal)) return FALSE;
    Wh_Log(L"Initialized: window=0x%zx bitmap=0x%zx customPaint=0x%zx type=0x%zx factory=0x%zx parent=0x%zx collections=(0x%zx,0x%zx) firstSelector=%u",
           g_gestureLayout.window, g_gestureLayout.bitmap, g_gestureLayout.customPaint,
           g_gestureLayout.contextType, g_gestureLayout.factory, g_gestureLayout.parent,
           g_gestureLayout.firstCollection, g_gestureLayout.secondCollection, g_gestureLayout.firstCollectionSelector);
    return TRUE;
}

