template <typename T>
bool ReplaceStoredComPtr(ScopedComPtr<T>* storage, T* value) {
    if (!storage) {
        return false;
    }

    if (storage->Get() == value) {
        return true;
    }

    if (value) {
        value->AddRef();
    }

    storage->Reset(value);
    return true;
}

