    const DWORD busyDelays[] = {125, 250, 500, 1000, 2000, 4000, 5000, 5000};
    const DWORD hardDelays[] = {2000, 4000, 8000, 16000, 30000, 30000};
    const DWORD targetDelays[] = {250, 500, 1000, 2000, 4000, 5000, 5000};
