    const DWORD canceledRetry = static_cast<DWORD>(-1);
    if (SelectRejectedCallRetryDelay(ComRetryProfile::Background,
                                     SERVERCALL_RETRYLATER,
                                     999,
                                     99,
                                     100) != COM_BACKGROUND_RETRY_DELAY_MS ||
