std::atomic<bool> g_callbacksEnabled;
std::atomic<bool> g_systemTrayHooked;
std::atomic<bool> g_taskbarViewHooked;
std::atomic<bool> g_systemTrayHookAttempted;
std::atomic<bool> g_taskbarViewHookAttempted;
